(373247,41472,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın gece yarısı vatansever kalabalık yine parlamentonun önünde bayrak ...'::text,'sallıyor olacak'::text,'sallayacak'::text,'sallıyor'::text,'Yarın gece yarısı vatansever kalabalık yine parlamentonun önünde bayrak sallıyor olacak.'::text),
(373248,41472,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap éjfélkor a hazafias tömeg ismét zászlókat ... a parlament előtt.'::text,'fog lengetni'::text,'lenget'::text,'lenget'::text,'Holnap éjfélkor a hazafias tömeg ismét zászlókat fog lengetni a parlament előtt.'::text),
(373251,41473,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Offizier verspricht, dass er die Flagge bei jeder patriotischen Feier ...'::text,'hissen wird'::text,'hissen wird'::text,'hisst'::text,'Der Offizier verspricht, dass er die Flagge bei jeder patriotischen Feier hissen wird.'::text),
(373255,41473,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіцер обіцяє, що ... прапор на кожному патріотичному святі.'::text,'підніматиме'::text,'підніматиме'::text,'піднімає'::text,'Офіцер обіцяє, що підніматиме прапор на кожному патріотичному святі.'::text),
(373254,41473,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El oficial promete que ... la bandera en cada celebración patriótica.'::text,'izará'::text,'estará izando'::text,'está izando'::text,'El oficial promete que izará la bandera en cada celebración patriótica.'::text),
(373253,41473,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''officier promet qu''il ... le drapeau à chaque fête patriotique.'::text,'hissera'::text,'sera en train de hisser'::text,'hisse'::text,'L''officier promet qu''il hissera le drapeau à chaque fête patriotique.'::text),
(373256,41473,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Subay, her vatansever kutlamada bayrağı ... söz veriyor.'::text,'çekeceğine'::text,'çekiyor olacağına'::text,'çektiğine'::text,'Subay, her vatansever kutlamada bayrağı çekeceğine söz veriyor.'::text),
(373257,41473,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tiszt megígéri, hogy minden hazafias ünnepségen ... a zászlót.'::text,'felvonja'::text,'fel fogja vonni'::text,'vonja fel'::text,'A tiszt megígéri, hogy minden hazafias ünnepségen felvonja a zászlót.'::text),
(373260,41474,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Flagge ... gestern Abend während der patriotischen Feier den Mast hinaufgezogen.'::text,'wurde'::text,'wird'::text,'zog'::text,'Die Flagge wurde gestern Abend während der patriotischen Feier den Mast hinaufgezogen.'::text),
(373264,41474,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прапор ... на щоглу під час патріотичного свята вчора ввечері.'::text,'був піднятий'::text,'піднімається'::text,'підняв'::text,'Прапор був піднятий на щоглу під час патріотичного свята вчора ввечері.'::text),
(373263,41474,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bandera ... por el mástil durante la celebración patriótica anoche.'::text,'fue izada'::text,'es izada'::text,'izó'::text,'La bandera fue izada por el mástil durante la celebración patriótica anoche.'::text),
(373262,41474,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le drapeau ... en haut du mât pendant la fête patriotique hier soir.'::text,'a été hissé'::text,'est hissé'::text,'a hissé'::text,'Le drapeau a été hissé en haut du mât pendant la fête patriotique hier soir.'::text),
(373265,41474,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün akşam vatansever kutlama sırasında bayrak direğe ...'::text,'çekildi'::text,'çekiliyor'::text,'çekti'::text,'Dün akşam vatansever kutlama sırasında bayrak direğe çekildi.'::text),
(373266,41474,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zászlót tegnap este a hazafias ünnepség alatt ... a rúdra.'::text,'felvonták'::text,'felvonják'::text,'felvonta'::text,'A zászlót tegnap este a hazafias ünnepség alatt felvonták a rúdra.'::text),
(373269,41475,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... patriotische Menschen vor dem Parlament Fahnen und Handylichter hoch.'::text,'hielten'::text,'wurden gehalten'::text,'haltend'::text,'Gestern Abend hielten patriotische Menschen vor dem Parlament Fahnen und Handylichter hoch.'::text),
(373273,41475,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ввечері патріотичні люди ... прапори й ліхтарики телефонів перед парламентом.'::text,'підняли'::text,'були підняті'::text,'піднімаючи'::text,'Учора ввечері патріотичні люди підняли прапори й ліхтарики телефонів перед парламентом.'::text),
(373272,41475,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche, la gente patriota ... banderas y las luces de los móviles frente al parlamento.'::text,'levantó'::text,'fue levantada'::text,'levantando'::text,'Anoche, la gente patriota levantó banderas y las luces de los móviles frente al parlamento.'::text),
(373271,41475,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, des gens patriotes ... des drapeaux et les lumières de leurs téléphones devant le parlement.'::text,'ont brandi'::text,'ont été brandis'::text,'brandissant'::text,'Hier soir, des gens patriotes ont brandi des drapeaux et les lumières de leurs téléphones devant le parlement.'::text),
(373274,41475,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün akşam vatansever insanlar parlamentonun önünde bayrakları ve telefon ışıklarını ...'::text,'havaya kaldırdı'::text,'havaya kaldırıldı'::text,'havaya kaldırarak'::text,'Dün akşam vatansever insanlar parlamentonun önünde bayrakları ve telefon ışıklarını havaya kaldırdı.'::text),
(373275,41475,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este hazafias emberek zászlókat és telefonfényeket ... a parlament előtt.'::text,'tartottak fel'::text,'fel lettek tartva'::text,'feltartva'::text,'Tegnap este hazafias emberek zászlókat és telefonfényeket tartottak fel a parlament előtt.'::text),
(373278,41476,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit ihrem Gesicht in Flaggenfarben ... sie ein bisschen patriotisch sein. Nur ganz leicht.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Mit ihrem Gesicht in Flaggenfarben muss sie ein bisschen patriotisch sein. Nur ganz leicht.'::text),
(373282,41476,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З обличчям, розмальованим у кольори прапора, вона ... бути трохи патріоткою. Ну зовсім трішки.'::text,'мусить'::text,'не може'::text,'не має права'::text,'З обличчям, розмальованим у кольори прапора, вона мусить бути трохи патріоткою. Ну зовсім трішки.'::text),
(373281,41476,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con la cara pintada con los colores de la bandera, ... ser un poquito patriota. Solo un poco.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Con la cara pintada con los colores de la bandera, debe de ser un poquito patriota. Solo un poco.'::text),
(373280,41476,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec le visage peint aux couleurs du drapeau, elle ... être un petit peu patriote. À peine.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Avec le visage peint aux couleurs du drapeau, elle doit être un petit peu patriote. À peine.'::text),
(373283,41476,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzünü bayrak renklerine boyadığına göre hafiften, sadece azıcık vatansever ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Yüzünü bayrak renklerine boyadığına göre hafiften, sadece azıcık vatansever olmalı.'::text),
(373284,41476,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zászló színeire festett arccal ... egy kicsit hazafiasnak lennie. Csak egy picit.'::text,'kell'::text,'nem lehet'::text,'nem szabad'::text,'A zászló színeire festett arccal kell egy kicsit hazafiasnak lennie. Csak egy picit.'::text),
(373287,41477,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Offizier, ... die Flagge gehisst hat, ist eindeutig der patriotischste Mann der Welt. Keine Kritik.'::text,'der'::text,'was'::text,'dessen'::text,'Der Offizier, der die Flagge gehisst hat, ist eindeutig der patriotischste Mann der Welt. Keine Kritik.'::text),
(373291,41477,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіцер, ... підняв прапор, явно найпатріотичніша людина на світі. Без зауважень.'::text,'який'::text,'що'::text,'чий'::text,'Офіцер, який підняв прапор, явно найпатріотичніша людина на світі. Без зауважень.'::text),
(373290,41477,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El oficial ... izó la bandera es claramente el hombre más patriota del mundo. Nada que objetar.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El oficial que izó la bandera es claramente el hombre más patriota del mundo. Nada que objetar.'::text),
(373289,41477,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''officier ... a hissé le drapeau est clairement l''homme le plus patriote du monde. Rien à redire.'::text,'qui'::text,'lequel'::text,'dont'::text,'L''officier qui a hissé le drapeau est clairement l''homme le plus patriote du monde. Rien à redire.'::text),
(373292,41477,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Subay, ... bayrağı çekti, açıkça dünyanın en vatansever adamı. Diyecek yok.'::text,'ki'::text,'ki'::text,'ki onun'::text,'Subay, ki bayrağı çekti, açıkça dünyanın en vatansever adamı. Diyecek yok.'::text),
(373293,41477,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tiszt, ... felvonta a zászlót, egyértelműen a világ leghazafiasabb embere. Nincs mit hozzáfűzni.'::text,'aki'::text,'amely'::text,'akinek'::text,'A tiszt, aki felvonta a zászlót, egyértelműen a világ leghazafiasabb embere. Nincs mit hozzáfűzni.'::text),
(373305,41479,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie ... früher Fahnen, jetzt ist sie das patriotischste Mädchen hier, kein Witz.'::text,'hasste'::text,'hasste'::text,'war es gewohnt zu hassen'::text,'Digga, sie hasste früher Fahnen, jetzt ist sie das patriotischste Mädchen hier, kein Witz.'::text),
(373309,41479,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, вона ... прапори, а тепер вона найпатріотичніша дівчина тут, без брехні.'::text,'раніше ненавиділа'::text,'ненавиділа б'::text,'звикла ненавидіти'::text,'Брате, вона раніше ненавиділа прапори, а тепер вона найпатріотичніша дівчина тут, без брехні.'::text),
(373308,41479,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... las banderas, y ahora es la chica más patriota de aquí, en serio.'::text,'odiaba'::text,'odiaba'::text,'estaba acostumbrada a odiar'::text,'Bro, ella odiaba las banderas, y ahora es la chica más patriota de aquí, en serio.'::text),
(373307,41479,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... les drapeaux, et maintenant c''est la fille la plus patriote ici, sans mentir.'::text,'détestait'::text,'détestait'::text,'avait l''habitude de détester'::text,'Frère, elle détestait les drapeaux, et maintenant c''est la fille la plus patriote ici, sans mentir.'::text),
(373310,41479,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eskiden bayraklardan ..., şimdi buradaki en vatansever kız, yalan yok.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'Kanka, eskiden bayraklardan nefret ederdi, şimdi buradaki en vatansever kız, yalan yok.'::text),
(373311,41479,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő régen ... a zászlókat, most meg ő itt a leghazafiasabb csaj, komolyan.'::text,'utálta'::text,'utálta'::text,'hozzá volt szokva, hogy utálja'::text,'Tesó, ő régen utálta a zászlókat, most meg ő itt a leghazafiasabb csaj, komolyan.'::text),
(373314,41480,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Stadt stimmte zu, 20.000 Euro aus dem Budget für das patriotische Feuerwerk ...'::text,'auszugeben'::text,'ausgeben'::text,'ausgeben'::text,'Die Stadt stimmte zu, 20.000 Euro aus dem Budget für das patriotische Feuerwerk auszugeben.'::text),
(373318,41480,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Місто погодилося ... 20 000 євро з бюджету на патріотичний феєрверк.'::text,'витратити'::text,'витрачання'::text,'витратити'::text,'Місто погодилося витратити 20 000 євро з бюджету на патріотичний феєрверк.'::text),
(373317,41480,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ciudad acordó ... 20.000 euros del presupuesto en los fuegos artificiales patrióticos.'::text,'gastar'::text,'gastando'::text,'gastar'::text,'La ciudad acordó gastar 20.000 euros del presupuesto en los fuegos artificiales patrióticos.'::text),
(373316,41480,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ville a accepté ... 20 000 euros du budget pour le feu d''artifice patriotique.'::text,'de dépenser'::text,'dépensant'::text,'dépenser'::text,'La ville a accepté de dépenser 20 000 euros du budget pour le feu d''artifice patriotique.'::text),
(373319,41480,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belediye bütçeden vatansever havai fişeklere 20.000 euro ... kabul etti.'::text,'harcamayı'::text,'harcamayı'::text,'harcamak'::text,'Belediye bütçeden vatansever havai fişeklere 20.000 euro harcamayı kabul etti.'::text),
(373320,41480,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A város beleegyezett, hogy ... 20 000 eurót a költségvetésből a hazafias tűzijátékra.'::text,'elköltsön'::text,'elköltés'::text,'elkölt'::text,'A város beleegyezett, hogy elköltsön 20 000 eurót a költségvetésből a hazafias tűzijátékra.'::text),
(373323,41481,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... patriotische Menschen unter dem Feuerwerk Fahnen.'::text,'schwenken'::text,'schwenken'::text,'haben geschwenkt'::text,'Gerade schwenken patriotische Menschen unter dem Feuerwerk Fahnen.'::text),
(373327,41481,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз патріотичні люди ... прапорами під феєрверком.'::text,'махають'::text,'махають'::text,'помахали'::text,'Прямо зараз патріотичні люди махають прапорами під феєрверком.'::text),
(373326,41481,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, la gente patriota ... banderas bajo los fuegos artificiales.'::text,'está ondeando'::text,'ondea'::text,'ha ondeado'::text,'Ahora mismo, la gente patriota está ondeando banderas bajo los fuegos artificiales.'::text),
(373325,41481,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, des gens patriotes ... des drapeaux sous le feu d''artifice.'::text,'agitent'::text,'agitent'::text,'ont agité'::text,'En ce moment, des gens patriotes agitent des drapeaux sous le feu d''artifice.'::text),
(373328,41481,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda vatansever insanlar havai fişeklerin altında bayrak ...'::text,'sallıyor'::text,'sallar'::text,'salladı'::text,'Şu anda vatansever insanlar havai fişeklerin altında bayrak sallıyor.'::text),
(373329,41481,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most hazafias emberek zászlókat ... a tűzijáték alatt.'::text,'lengetnek'::text,'lengetnek'::text,'lengettek'::text,'Épp most hazafias emberek zászlókat lengetnek a tűzijáték alatt.'::text),
(369723,41081,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Becken ruhig ..., spiegelt es das weiße Denkmal.'::text,'ist'::text,'war'::text,'sein wird'::text,'Wenn das Becken ruhig ist, spiegelt es das weiße Denkmal.'::text),
(369727,41081,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли басейн ... спокійний, у ньому відбивається білий пам''ятник.'::text,''::text,'був'::text,'буде'::text,'Коли басейн спокійний, у ньому відбивається білий пам''ятник.'::text),
(369726,41081,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el estanque ... tranquilo, refleja el monumento blanco.'::text,'está'::text,'estaba'::text,'estará'::text,'Si el estanque está tranquilo, refleja el monumento blanco.'::text),
(369725,41081,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le bassin ... calme, il reflète le monument blanc.'::text,'est'::text,'était'::text,'sera'::text,'Si le bassin est calme, il reflète le monument blanc.'::text),
(369728,41081,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havuz durgun ..., beyaz anıtı yansıtır.'::text,'olursa'::text,'olsaydı'::text,'olacaksa'::text,'Havuz durgun olursa, beyaz anıtı yansıtır.'::text),
(369729,41081,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a medence nyugodt ..., visszatükrözi a fehér emlékművet.'::text,''::text,'volt'::text,'lesz'::text,'Ha a medence nyugodt, visszatükrözi a fehér emlékművet.'::text),
(369732,41082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das weiße Marmordenkmal ist wunderschön, ...?'::text,'nicht wahr'::text,'oder'::text,'oder'::text,'Das weiße Marmordenkmal ist wunderschön, nicht wahr?'::text),
(369736,41082,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Білий мармуровий пам''ятник гарний, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Білий мармуровий пам''ятник гарний, правда?'::text),
(369735,41082,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El monumento de mármol blanco es precioso, ¿...?'::text,'verdad'::text,'no'::text,'verdad'::text,'El monumento de mármol blanco es precioso, ¿verdad?'::text),
(369734,41082,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le monument en marbre blanc est magnifique, ... ?'::text,'n''est-ce pas'::text,'non'::text,'n''est-ce pas'::text,'Le monument en marbre blanc est magnifique, n''est-ce pas ?'::text),
(369737,41082,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz mermer anıt çok güzel, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Beyaz mermer anıt çok güzel, değil mi?'::text),
(369738,41082,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér márvány emlékmű gyönyörű, ...?'::text,'nem igaz'::text,'ugye'::text,'ugye'::text,'A fehér márvány emlékmű gyönyörű, nem igaz?'::text),
(369750,41084,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... er vor dem Denkmal hundert Selfies gemacht haben. Sehr bescheiden, ganz klar.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis heute Abend wird er vor dem Denkmal hundert Selfies gemacht haben. Sehr bescheiden, ganz klar.'::text),
(369754,41084,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора він ... сто селфі біля пам''ятника. Дуже скромно, звісно.'::text,'зробить'::text,'зробить'::text,'робитиме'::text,'До вечора він зробить сто селфі біля пам''ятника. Дуже скромно, звісно.'::text),
(369753,41084,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche, ... cien selfies frente al monumento. Muy modesto, claramente.'::text,'se habrá hecho'::text,'se hará'::text,'se estará haciendo'::text,'Para esta noche, se habrá hecho cien selfies frente al monumento. Muy modesto, claramente.'::text),
(369752,41084,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, il ... cent selfies devant le monument. Très modeste, clairement.'::text,'aura pris'::text,'prendra'::text,'sera en train de prendre'::text,'D''ici ce soir, il aura pris cent selfies devant le monument. Très modeste, clairement.'::text),
(369755,41084,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar anıtın önünde yüz selfie ..., çok mütevazı tabii.'::text,'çekmiş olacak'::text,'çekecek'::text,'çekiyor olacak'::text,'Bu akşama kadar anıtın önünde yüz selfie çekmiş olacak, çok mütevazı tabii.'::text),
(369756,41084,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére már száz szelfit ... az emlékmű előtt. Nagyon szerény, nyilván.'::text,'lő'::text,'lő'::text,'fog lőni'::text,'Estére már száz szelfit lő az emlékmű előtt. Nagyon szerény, nyilván.'::text),
(369759,41085,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn er früher vom Denkmal weg wäre, ... er diese Farbpulverschlacht nicht gefunden, echt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Digga, wenn er früher vom Denkmal weg wäre, hätte er diese Farbpulverschlacht nicht gefunden, echt.'::text),
(369763,41085,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, якби він пішов від пам''ятника раніше, він ... ту бійку кольоровим порошком, чесно.'::text,'не знайшов би'::text,'не знайде'::text,'не знайшов'::text,'Брате, якби він пішов від пам''ятника раніше, він не знайшов би ту бійку кольоровим порошком, чесно.'::text),
(369762,41085,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si se hubiera ido antes del monumento, ... esa guerra de polvos de colores, en serio.'::text,'no habría encontrado'::text,'no encontrará'::text,'no encontró'::text,'Bro, si se hubiera ido antes del monumento, no habría encontrado esa guerra de polvos de colores, en serio.'::text),
(369761,41085,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, s''il avait quitté le monument plus tôt, il ... cette bataille de poudre colorée, sérieux.'::text,'n''aurait pas trouvé'::text,'ne trouvera pas'::text,'n''a pas trouvé'::text,'Frère, s''il avait quitté le monument plus tôt, il n''aurait pas trouvé cette bataille de poudre colorée, sérieux.'::text),
(369764,41085,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anıttan daha erken ayrılsaydı o renkli toz savaşını ..., cidden.'::text,'bulamazdı'::text,'bulamayacak'::text,'bulamadı'::text,'Kanka, anıttan daha erken ayrılsaydı o renkli toz savaşını bulamazdı, cidden.'::text),
(369765,41085,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha korábban elment volna az emlékműtől, ... azt a színes poros csatát, komolyan.'::text,'nem találta volna meg'::text,'nem fogja megtalálni'::text,'nem találta meg'::text,'Tesó, ha korábban elment volna az emlékműtől, nem találta volna meg azt a színes poros csatát, komolyan.'::text),
(369768,41086,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, nach dem Denkmal ... er echt kein weißes Hemd anziehen sollen, jetzt ist es ruiniert, kein Witz.'::text,'hätte'::text,'durfte'::text,'konnte'::text,'Digga, nach dem Denkmal hätte er echt kein weißes Hemd anziehen sollen, jetzt ist es ruiniert, kein Witz.'::text),
(369772,41086,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, після пам''ятника йому ... вдягати білу сорочку, тепер їй кінець, чесно.'::text,'не треба було'::text,'не можна було'::text,'не можна було'::text,'Брате, після пам''ятника йому не треба було вдягати білу сорочку, тепер їй кінець, чесно.'::text),
(369771,41086,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, después del monumento ... ponerse una camisa blanca, ahora está destrozada, en serio.'::text,'no debió'::text,'no pudo'::text,'no podía'::text,'Bro, después del monumento no debió ponerse una camisa blanca, ahora está destrozada, en serio.'::text),
(369770,41086,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... mettre une chemise blanche après le monument, elle est foutue maintenant, sérieux.'::text,'n''aurait pas dû'::text,'n''a pas dû'::text,'ne pouvait pas'::text,'Frère, il n''aurait pas dû mettre une chemise blanche après le monument, elle est foutue maintenant, sérieux.'::text),
(369773,41086,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, anıttan sonra beyaz gömlek ..., gömlek artık mahvoldu, cidden.'::text,'giymemeliydi'::text,'giymemiş olmalı'::text,'giyemezdi'::text,'Kanka, anıttan sonra beyaz gömlek giymemeliydi, gömlek artık mahvoldu, cidden.'::text),
(369774,41086,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az emlékmű után ... volna fehér inget vennie, most már oda van, komolyan.'::text,'nem kellett'::text,'nem lehetett'::text,'nem tudott'::text,'Tesó, az emlékmű után nem kellett volna fehér inget vennie, most már oda van, komolyan.'::text),
(369777,41087,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ließ einen Fremden für 5 Euro sein Denkmalfoto ..., im Rahmen des Budgets.'::text,'machen'::text,'machen'::text,'gemacht'::text,'Er ließ einen Fremden für 5 Euro sein Denkmalfoto machen, im Rahmen des Budgets.'::text),
(369781,41087,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він домовився, щоб незнайомець ... його фото біля пам''ятника за 5 євро, у межах бюджету.'::text,'зробив'::text,'зробити'::text,'зроблене'::text,'Він домовився, щоб незнайомець зробив його фото біля пам''ятника за 5 євро, у межах бюджету.'::text),
(369780,41087,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Consiguió que un desconocido le ... la foto en el monumento por 5 euros, dentro del presupuesto.'::text,'hiciera'::text,'hacer'::text,'hecha'::text,'Consiguió que un desconocido le hiciera la foto en el monumento por 5 euros, dentro del presupuesto.'::text),
(369779,41087,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a convaincu un inconnu de ... sa photo devant le monument pour 5 euros, dans les limites du budget.'::text,'prendre'::text,'prendre'::text,'prise'::text,'Il a convaincu un inconnu de prendre sa photo devant le monument pour 5 euros, dans les limites du budget.'::text),
(369782,41087,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anıt fotoğrafını 5 euroya bir yabancıya ..., bütçe dahilinde.'::text,'çektirdi'::text,'çektirdi'::text,'çekilmiş'::text,'Anıt fotoğrafını 5 euroya bir yabancıya çektirdi, bütçe dahilinde.'::text),
(369783,41087,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megkért egy idegent, hogy 5 euróért ... le az emlékműves fotóját, a kereten belül.'::text,'fotózza'::text,'fotózni'::text,'lefotózva'::text,'Megkért egy idegent, hogy 5 euróért fotózza le az emlékműves fotóját, a kereten belül.'::text),
(369786,41088,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünschte, er ... mehr Zeit am Denkmal verbracht.'::text,'hätte'::text,'hätte'::text,'hat'::text,'Er wünschte, er hätte mehr Zeit am Denkmal verbracht.'::text),
(369790,41088,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому шкода, що він не ... більше часу біля пам''ятника.'::text,'провів'::text,'провів'::text,'провів'::text,'Йому шкода, що він не провів більше часу біля пам''ятника.'::text),
(369789,41088,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él desearía ... más tiempo en el monumento.'::text,'haber pasado'::text,'pasar'::text,'ha pasado'::text,'Él desearía haber pasado más tiempo en el monumento.'::text),
(369788,41088,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... plus de temps au monument.'::text,'avoir passé'::text,'passer'::text,'a passé'::text,'Il aimerait avoir passé plus de temps au monument.'::text),
(369791,41088,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke anıtta daha fazla zaman ... diye düşünüyor.'::text,'geçirseydi'::text,'geçirse'::text,'geçirdi'::text,'Keşke anıtta daha fazla zaman geçirseydi diye düşünüyor.'::text),
(369792,41088,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak több időt ... volna az emlékműnél.'::text,'töltött'::text,'töltene'::text,'töltött'::text,'Azt kívánja, bárcsak több időt töltött volna az emlékműnél.'::text),
(369795,41089,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Denkmal, ... weiße Marmorkuppel sich im Becken spiegelt, ist typischerweise überfüllt.'::text,'dessen'::text,'das'::text,'das'::text,'Das Denkmal, dessen weiße Marmorkuppel sich im Becken spiegelt, ist typischerweise überfüllt.'::text),
(369799,41089,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пам''ятник, ... білий мармуровий купол відбивається в басейні, зазвичай переповнений.'::text,'чий'::text,'який'::text,'що'::text,'Пам''ятник, чий білий мармуровий купол відбивається в басейні, зазвичай переповнений.'::text),
(369798,41089,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El monumento, ... blanca cúpula de mármol se refleja en el estanque, suele estar abarrotado.'::text,'cuya'::text,'el cual'::text,'que'::text,'El monumento, cuya blanca cúpula de mármol se refleja en el estanque, suele estar abarrotado.'::text),
(369797,41089,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le monument, ... le dôme de marbre blanc se reflète dans le bassin, est typiquement bondé.'::text,'dont'::text,'lequel'::text,'que'::text,'Le monument, dont le dôme de marbre blanc se reflète dans le bassin, est typiquement bondé.'::text),
(369800,41089,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anıt, ... beyaz mermer kubbesi havuza yansıyor, tipik olarak kalabalıktır.'::text,'ki onun'::text,'ki'::text,'ki'::text,'Anıt, ki onun beyaz mermer kubbesi havuza yansıyor, tipik olarak kalabalıktır.'::text),
(369801,41089,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az emlékmű, ... fehér márványkupolája tükröződik a medencében, jellemzően zsúfolt.'::text,'amelynek'::text,'amely'::text,'ami'::text,'Az emlékmű, amelynek fehér márványkupolája tükröződik a medencében, jellemzően zsúfolt.'::text),
(369813,41091,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dem Denkmal filmte er auch einen Gewürzmarkt und ein Farbenfest.'::text,'Außer'::text,'Statt'::text,'Wegen'::text,'Außer dem Denkmal filmte er auch einen Gewürzmarkt und ein Farbenfest.'::text),
(369817,41091,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... пам''ятника він також зняв ринок спецій і фестиваль фарб.'::text,'Окрім'::text,'Замість'::text,'Через'::text,'Окрім пам''ятника він також зняв ринок спецій і фестиваль фарб.'::text),
(369816,41091,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el monumento, también grabó un mercado de especias y un festival de colores.'::text,'Aparte de'::text,'En lugar de'::text,'Debido a'::text,'Aparte de el monumento, también grabó un mercado de especias y un festival de colores.'::text),
(369815,41091,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... monument, il a aussi filmé un marché aux épices et un festival de couleurs.'::text,'En plus du'::text,'Au lieu du'::text,'À cause du'::text,'En plus du monument, il a aussi filmé un marché aux épices et un festival de couleurs.'::text),
(369818,41091,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anıtın ... bir baharat pazarını ve bir renk festivalini de çekti.'::text,'yanı sıra'::text,'yerine'::text,'yüzünden'::text,'Anıtın yanı sıra bir baharat pazarını ve bir renk festivalini de çekti.'::text),
(369819,41091,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az emlékmű ... egy fűszerpiacot és egy színfesztivált is lefilmezett.'::text,'mellett'::text,'helyett'::text,'miatt'::text,'Az emlékmű mellett egy fűszerpiacot és egy színfesztivált is lefilmezett.'::text),
(384699,42745,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Verkäufer einen Tropfen verschüttete, ... die jungen Männer nicht so laut.'::text,'jubelten'::text,'werden jubeln'::text,'jubelten'::text,'Wenn der Verkäufer einen Tropfen verschüttete, jubelten die jungen Männer nicht so laut.'::text),
(384703,42745,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби продавець розлив краплю, хлопці ... так гучно.'::text,'не аплодували б'::text,'не аплодуватимуть'::text,'не аплодували'::text,'Якби продавець розлив краплю, хлопці не аплодували б так гучно.'::text),
(384702,42745,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el vendedor derramara una gota, los chicos no ... tan fuerte.'::text,'vitorearían'::text,'vitorearán'::text,'vitorearon'::text,'Si el vendedor derramara una gota, los chicos no vitorearían tan fuerte.'::text),
(384701,42745,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vendeur renversait une goutte, les jeunes hommes ... aussi fort.'::text,'ne l''acclameraient pas'::text,'ne l''acclameront pas'::text,'ne l''ont pas acclamé'::text,'Si le vendeur renversait une goutte, les jeunes hommes ne l''acclameraient pas aussi fort.'::text),
(384704,42745,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Satıcı bir damla dökse, gençler bu kadar yüksek sesle ...'::text,'tezahürat yapmazdı'::text,'tezahürat yapmayacak'::text,'tezahürat yapmadı'::text,'Satıcı bir damla dökse, gençler bu kadar yüksek sesle tezahürat yapmazdı.'::text),
(384705,42745,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az árus kilöttyintene egy cseppet, a fiatalok nem ... ilyen hangosan.'::text,'ujjonganának'::text,'fognak ujjongani'::text,'ujjongtak'::text,'Ha az árus kilöttyintene egy cseppet, a fiatalok nem ujjonganának ilyen hangosan.'::text),
(384708,42746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei jeder Bestellung ... der Tee von über dem Kopf des Verkäufers eingegossen. Natürlich die schnellste Methode.'::text,'wird'::text,'wurde'::text,'gießt'::text,'Bei jeder Bestellung wird der Tee von über dem Kopf des Verkäufers eingegossen. Natürlich die schnellste Methode.'::text),
(384712,42746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'При кожному замовленні чай ... з-над голови продавця. Звісно, найшвидший метод.'::text,'наливається'::text,'наливався'::text,'наливає'::text,'При кожному замовленні чай наливається з-над голови продавця. Звісно, найшвидший метод.'::text),
(384711,42746,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En cada pedido, el té ... desde encima de la cabeza del vendedor. Obviamente, el método más rápido.'::text,'se sirve'::text,'se sirvió'::text,'sirve'::text,'En cada pedido, el té se sirve desde encima de la cabeza del vendedor. Obviamente, el método más rápido.'::text),
(384710,42746,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À chaque commande, le thé ... depuis au-dessus de la tête du vendeur. Évidemment la méthode la plus rapide.'::text,'est versé'::text,'a été versé'::text,'verse'::text,'À chaque commande, le thé est versé depuis au-dessus de la tête du vendeur. Évidemment la méthode la plus rapide.'::text),
(384713,42746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her siparişte çay satıcının başının üstünden ..., tabii ki en hızlı yöntem.'::text,'dökülür'::text,'döküldü'::text,'döker'::text,'Her siparişte çay satıcının başının üstünden dökülür, tabii ki en hızlı yöntem.'::text),
(384714,42746,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden rendelésnél az árus feje fölül ... a teát. Nyilván a leggyorsabb módszer.'::text,'öntik'::text,'öntötték'::text,'önti'::text,'Minden rendelésnél az árus feje fölül öntik a teát. Nyilván a leggyorsabb módszer.'::text),
(384717,42747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach der Show ... der Verkäufer den jungen Männern kleine Tassen Tee aus.'::text,'teilte'::text,'wurde'::text,'austeilend'::text,'Nach der Show teilte der Verkäufer den jungen Männern kleine Tassen Tee aus.'::text),
(384721,42747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після шоу продавець ... хлопцям маленькі чашки чаю.'::text,'роздав'::text,'був розданий'::text,'роздаючи'::text,'Після шоу продавець роздав хлопцям маленькі чашки чаю.'::text),
(384720,42747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después del show, el vendedor ... tacitas de té a los chicos.'::text,'repartió'::text,'fue repartido'::text,'repartiendo'::text,'Después del show, el vendedor repartió tacitas de té a los chicos.'::text),
(384719,42747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après le show, le vendeur ... des petites tasses de thé aux jeunes hommes.'::text,'a distribué'::text,'a été distribué'::text,'distribuant'::text,'Après le show, le vendeur a distribué des petites tasses de thé aux jeunes hommes.'::text),
(384722,42747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gösteriden sonra satıcı gençlere küçük bardaklarda çay ...'::text,'dağıttı'::text,'dağıtıldı'::text,'dağıtarak'::text,'Gösteriden sonra satıcı gençlere küçük bardaklarda çay dağıttı.'::text),
(384723,42747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A show után az árus kis csésze teákat ... a fiataloknak.'::text,'osztott ki'::text,'ki lett osztva'::text,'kiosztva'::text,'A show után az árus kis csésze teákat osztott ki a fiataloknak.'::text),
(384726,42748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Verkäufer verschüttet nie einen Tropfen. Er ... viel üben, echt.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Digga, der Verkäufer verschüttet nie einen Tropfen. Er muss viel üben, echt.'::text),
(384730,42748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, цей продавець ніколи не розливає ні краплі. Він ... багато тренуватися, чесно.'::text,'мусить'::text,'не може'::text,'не має права'::text,'Брате, цей продавець ніколи не розливає ні краплі. Він мусить багато тренуватися, чесно.'::text),
(384729,42748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese vendedor nunca derrama ni una gota. ... practicar un montón, en serio.'::text,'Debe de'::text,'No puede'::text,'No debe'::text,'Bro, ese vendedor nunca derrama ni una gota. Debe de practicar un montón, en serio.'::text),
(384728,42748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ce vendeur ne renverse jamais une goutte. Il ... s''entraîner beaucoup, sérieux.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Frère, ce vendeur ne renverse jamais une goutte. Il doit s''entraîner beaucoup, sérieux.'::text),
(384731,42748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o satıcı hiç damla dökmüyor. Çok pratik ..., cidden.'::text,'yapıyor olmalı'::text,'yapıyor olamaz'::text,'yapmamalı'::text,'Kanka, o satıcı hiç damla dökmüyor. Çok pratik yapıyor olmalı, cidden.'::text),
(384732,42748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az az árus soha egy cseppet se lottyant ki. Biztos sokat ... gyakorolnia, komolyan.'::text,'kell'::text,'nem lehet'::text,'nem szabad'::text,'Tesó, az az árus soha egy cseppet se lottyant ki. Biztos sokat kell gyakorolnia, komolyan.'::text),
(384744,42750,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Verkäufer sagte, der Tee ... im Krug, weil er ihn dort hineingegossen hatte.'::text,'sei'::text,'ist'::text,'sei gewesen'::text,'Der Verkäufer sagte, der Tee sei im Krug, weil er ihn dort hineingegossen hatte.'::text),
(384748,42750,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Продавець сказав, що чай ... у глечику, бо він його туди налив.'::text,'був'::text,'є'::text,'був'::text,'Продавець сказав, що чай був у глечику, бо він його туди налив.'::text),
(384747,42750,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vendedor dijo que el té ... en la jarra porque él lo había servido ahí.'::text,'estaba'::text,'está siendo'::text,'ha estado'::text,'El vendedor dijo que el té estaba en la jarra porque él lo había servido ahí.'::text),
(384746,42750,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vendeur a dit que le thé ... dans la carafe parce qu''il l''y avait versé.'::text,'était'::text,'est en train d''être'::text,'a été'::text,'Le vendeur a dit que le thé était dans la carafe parce qu''il l''y avait versé.'::text),
(384749,42750,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Satıcı, çayı oraya döktüğü için çayın sürahide ... söyledi.'::text,'olduğunu'::text,'olmakta olduğunu'::text,'olmuş olduğunu'::text,'Satıcı, çayı oraya döktüğü için çayın sürahide olduğunu söyledi.'::text),
(384750,42750,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az árus azt mondta, hogy a tea a kancsóban ..., mert ő öntötte oda.'::text,'van'::text,'van'::text,'volt'::text,'Az árus azt mondta, hogy a tea a kancsóban van, mert ő öntötte oda.'::text),
(384753,42751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vermutlich ... der Verkäufer früher aus viel geringerer Höhe, bevor der Trick perfektioniert wurde.'::text,'goss'::text,'war gewohnt zu gießen'::text,'goss'::text,'Vermutlich goss der Verkäufer früher aus viel geringerer Höhe, bevor der Trick perfektioniert wurde.'::text),
(384757,42751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Імовірно, продавець ... з набагато меншої висоти, поки трюк не був доведений до досконалості.'::text,'раніше наливав'::text,'звик наливати'::text,'наливав би'::text,'Імовірно, продавець раніше наливав з набагато меншої висоти, поки трюк не був доведений до досконалості.'::text),
(384756,42751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presumiblemente, el vendedor ... servir desde mucho más abajo antes de perfeccionar el truco.'::text,'solía'::text,'estaba acostumbrado a'::text,'solía'::text,'Presumiblemente, el vendedor solía servir desde mucho más abajo antes de perfeccionar el truco.'::text),
(384755,42751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vraisemblablement, le vendeur ... verser d''une hauteur bien plus basse avant que le tour soit perfectionné.'::text,'avait l''habitude de'::text,'était habitué à'::text,'avait l''habitude de'::text,'Vraisemblablement, le vendeur avait l''habitude de verser d''une hauteur bien plus basse avant que le tour soit perfectionné.'::text),
(384758,42751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhtemelen satıcı, numara mükemmelleşmeden önce çok daha alçaktan ...'::text,'dökerdi'::text,'dökmeye alışkındı'::text,'dökerdi'::text,'Muhtemelen satıcı, numara mükemmelleşmeden önce çok daha alçaktan dökerdi.'::text),
(384759,42751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Feltehetően az árus régen jóval alacsonyabbról ..., mielőtt a trükköt tökélyre fejlesztették.'::text,'öntött'::text,'hozzá volt szokva, hogy öntsön'::text,'öntött'::text,'Feltehetően az árus régen jóval alacsonyabbról öntött, mielőtt a trükköt tökélyre fejlesztették.'::text),
(384762,42752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Verkäufer weigert sich, auch nur einen einzigen Tropfen ...! Keinen einzigen, nie wieder!'::text,'zu verschütten'::text,'verschütten'::text,'verschütten'::text,'Der Verkäufer weigert sich, auch nur einen einzigen Tropfen zu verschütten! Keinen einzigen, nie wieder!'::text),
(384766,42752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Продавець відмовляється ... бодай одну краплю! Жодної, більше ніколи!'::text,'розлити'::text,'розливання'::text,'розлити'::text,'Продавець відмовляється розлити бодай одну краплю! Жодної, більше ніколи!'::text),
(384765,42752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El vendedor se niega ... ni una sola gota! ¡Ni una, nunca más!'::text,'a derramar'::text,'derramando'::text,'derramar'::text,'¡El vendedor se niega a derramar ni una sola gota! ¡Ni una, nunca más!'::text),
(384764,42752,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vendeur refuse ... la moindre goutte ! Pas une, plus jamais !'::text,'de renverser'::text,'renversant'::text,'renverser'::text,'Le vendeur refuse de renverser la moindre goutte ! Pas une, plus jamais !'::text),
(384767,42752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Satıcı tek bir damla bile ... reddediyor! Bir tane bile, bir daha asla!'::text,'dökmeyi'::text,'dökmeyi'::text,'dökmek'::text,'Satıcı tek bir damla bile dökmeyi reddediyor! Bir tane bile, bir daha asla!'::text),
(384768,42752,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az árus nem hajlandó egyetlen cseppet se ...! Egyet se, soha többé!'::text,'kiönteni'::text,'kiöntés'::text,'kiönteni'::text,'Az árus nem hajlandó egyetlen cseppet se kiönteni! Egyet se, soha többé!'::text),
(384771,42753,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein verschütteter Tropfen und dieser Verkäufer würde buchstäblich zusammenbrechen, ...?'::text,'nicht wahr'::text,'oder'::text,'oder'::text,'Ein verschütteter Tropfen und dieser Verkäufer würde buchstäblich zusammenbrechen, nicht wahr?'::text),
(384775,42753,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна розлита крапля — і цей продавець буквально знепритомніє, ...?'::text,'правда'::text,'хіба ні'::text,'так'::text,'Одна розлита крапля — і цей продавець буквально знепритомніє, правда?'::text),
(384774,42753,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una gota derramada y este vendedor se derrumbaría literalmente, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Una gota derramada y este vendedor se derrumbaría literalmente, ¿verdad?'::text),
(384773,42753,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une goutte renversée et ce vendeur s''effondrerait littéralement, ... ?'::text,'n''est-ce pas'::text,'non'::text,'hein'::text,'Une goutte renversée et ce vendeur s''effondrerait littéralement, n''est-ce pas ?'::text),
(384776,42753,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tek bir damla dökülse bu satıcı resmen yıkılırdı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Tek bir damla dökülse bu satıcı resmen yıkılırdı, değil mi?'::text),
(384777,42753,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyetlen kilöttyent csepp, és ez az árus szó szerint összeomlana, ...?'::text,'nem igaz'::text,'ugye'::text,'ugye'::text,'Egyetlen kilöttyent csepp, és ez az árus szó szerint összeomlana, nem igaz?'::text),
(384780,42754,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Verkäufer lächelte die Menge an, und ...'::text,'die jungen Männer auch'::text,'die jungen Männer auch'::text,'die jungen Männer auch nicht'::text,'Der Verkäufer lächelte die Menge an, und die jungen Männer auch.'::text),
(384784,42754,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Продавець усміхався натовпу, і ...'::text,'хлопці теж'::text,'хлопці теж'::text,'хлопці теж ні'::text,'Продавець усміхався натовпу, і хлопці теж.'::text),
(384783,42754,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vendedor le sonreía a la multitud, y ...'::text,'los chicos también'::text,'los chicos también'::text,'los chicos tampoco'::text,'El vendedor le sonreía a la multitud, y los chicos también.'::text),
(384782,42754,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vendeur souriait à la foule, et ...'::text,'les jeunes hommes aussi'::text,'les jeunes hommes aussi'::text,'les jeunes hommes non plus'::text,'Le vendeur souriait à la foule, et les jeunes hommes aussi.'::text),
(384785,42754,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Satıcı kalabalığa gülümsüyordu ve ...'::text,'gençler de'::text,'gençler de'::text,'gençler de değil'::text,'Satıcı kalabalığa gülümsüyordu ve gençler de.'::text),
(384786,42754,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az árus mosolygott a tömegre, és ...'::text,'a fiatalok is'::text,'a fiatalok is'::text,'a fiatalok sem'::text,'Az árus mosolygott a tömegre, és a fiatalok is.'::text),
(400107,44457,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: In fünf Minuten ... du deine Impfung hinter dir und das Pflaster schon gezeigt.'::text,'hast'::text,'wirst haben'::text,'hättest'::text,'Respekt: In fünf Minuten hast du deine Impfung hinter dir und das Pflaster schon gezeigt.'::text),
(400111,44457,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: за п''ять хвилин ти вже ... щеплення і похизуєшся пластирем.'::text,'зробиш'::text,'робитимеш'::text,'зробив би'::text,'Респект: за п''ять хвилин ти вже зробиш щеплення і похизуєшся пластирем.'::text),
(400110,44457,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: en cinco minutos ... tu vacuna y presumido de tirita.'::text,'habrás recibido'::text,'recibirás'::text,'recibirías'::text,'Respeto: en cinco minutos habrás recibido tu vacuna y presumido de tirita.'::text),
(400109,44457,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : dans cinq minutes, tu ... ton vaccin et montré ton pansement.'::text,'auras eu'::text,'auras'::text,'aurais'::text,'Respect : dans cinq minutes, tu auras eu ton vaccin et montré ton pansement.'::text),
(400112,44457,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal olsun: beş dakika sonra aşını ... ve yara bandını da göstermiş olacaksın.'::text,'olmuş'::text,'olacaksın'::text,'olurdun'::text,'Helal olsun: beş dakika sonra aşını olmuş ve yara bandını da göstermiş olacaksın.'::text),
(400113,44457,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: öt perc múlva már ... az oltáson, és a tapaszt is megmutattad.'::text,'túl leszel'::text,'túl leszel'::text,'túl lennél'::text,'Respekt: öt perc múlva már túl leszel az oltáson, és a tapaszt is megmutattad.'::text),
(400116,44458,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um zwölf ... die Krankenschwester schon sechs Stunden lang Impfungen gegeben haben. Eindeutig eine entspannte Schicht.'::text,'wird'::text,'wird'::text,'wird'::text,'Um zwölf wird die Krankenschwester schon sechs Stunden lang Impfungen gegeben haben. Eindeutig eine entspannte Schicht.'::text),
(400120,44458,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду медсестра ... щеплення вже шість годин. Явно розслаблена зміна.'::text,'робитиме'::text,'робитиме'::text,'зробить'::text,'До обіду медсестра робитиме щеплення вже шість годин. Явно розслаблена зміна.'::text),
(400119,44458,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, la enfermera ... vacunas durante seis horas. Claramente un turno relajado.'::text,'habrá estado poniendo'::text,'estará poniendo'::text,'habrá puesto'::text,'Para el mediodía, la enfermera habrá estado poniendo vacunas durante seis horas. Claramente un turno relajado.'::text),
(400118,44458,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, l''infirmière ... des vaccins pendant six heures. Clairement une garde reposante.'::text,'aura fait'::text,'fera'::text,'aura fait'::text,'D''ici midi, l''infirmière aura fait des vaccins pendant six heures. Clairement une garde reposante.'::text),
(400121,44458,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar hemşire altı saattir aşı ..., belli ki çok rahat bir vardiya.'::text,'yapıyor olacak'::text,'yapıyor olacak'::text,'yapmış olacak'::text,'Öğlene kadar hemşire altı saattir aşı yapıyor olacak, belli ki çok rahat bir vardiya.'::text),
(400122,44458,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre az ápoló már hat órája ... oltásokat. Nyilván egy pihentető műszak.'::text,'ad be'::text,'fog adni'::text,'beadott'::text,'Délre az ápoló már hat órája ad be oltásokat. Nyilván egy pihentető műszak.'::text),
(400125,44459,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er seinen Ärmel nicht hochgekrempelt hätte, ... ihm die Krankenschwester die Impfung nicht so schnell gegeben.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn er seinen Ärmel nicht hochgekrempelt hätte, hätte ihm die Krankenschwester die Impfung nicht so schnell gegeben.'::text),
(400129,44459,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не закотив рукав, медсестра ... йому щеплення так швидко.'::text,'не зробила б'::text,'не зробить'::text,'не зробила'::text,'Якби він не закотив рукав, медсестра не зробила б йому щеплення так швидко.'::text),
(400128,44459,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no se hubiera subido la manga, la enfermera no le ... la vacuna tan rápido.'::text,'habría puesto'::text,'pondrá'::text,'puso'::text,'Si no se hubiera subido la manga, la enfermera no le habría puesto la vacuna tan rápido.'::text),
(400127,44459,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas remonté sa manche, l''infirmière ... le vaccin aussi vite.'::text,'ne lui aurait pas fait'::text,'ne lui fera pas'::text,'ne lui a pas fait'::text,'S''il n''avait pas remonté sa manche, l''infirmière ne lui aurait pas fait le vaccin aussi vite.'::text),
(400130,44459,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kolunu sıvamasaydı hemşire aşıyı bu kadar hızlı ...'::text,'yapmazdı'::text,'yapmayacak'::text,'yapmadı'::text,'Kolunu sıvamasaydı hemşire aşıyı bu kadar hızlı yapmazdı.'::text),
(400131,44459,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem tűrte volna fel az ingujját, az ápoló nem ... ilyen gyorsan az oltást.'::text,'adta volna be'::text,'fogja beadni'::text,'adta be'::text,'Ha nem tűrte volna fel az ingujját, az ápoló nem adta volna be ilyen gyorsan az oltást.'::text),
(400134,44460,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten sie heute keine Impfung bekommen, ... sie jetzt keine Pflaster auf den Armen.'::text,'hätten'::text,'hätten gehabt'::text,'werden haben'::text,'Hätten sie heute keine Impfung bekommen, hätten sie jetzt keine Pflaster auf den Armen.'::text),
(400138,44460,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони сьогодні не зробили щеплення, зараз вони ... пластирів на руках.'::text,'не мали б'::text,'не мали б'::text,'не матимуть'::text,'Якби вони сьогодні не зробили щеплення, зараз вони не мали б пластирів на руках.'::text),
(400137,44460,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no se hubieran vacunado hoy, ahora no ... tiritas en los brazos.'::text,'llevarían'::text,'habrían llevado'::text,'llevarán'::text,'Si no se hubieran vacunado hoy, ahora no llevarían tiritas en los brazos.'::text),
(400136,44460,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils ne s''étaient pas fait vacciner aujourd''hui, ils ... de pansements sur les bras maintenant.'::text,'ne porteraient pas'::text,'n''auraient pas porté'::text,'ne porteront pas'::text,'S''ils ne s''étaient pas fait vacciner aujourd''hui, ils ne porteraient pas de pansements sur les bras maintenant.'::text),
(400139,44460,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün aşı olmasalardı şimdi kollarında yara bandı ...'::text,'olmazdı'::text,'olmazdı'::text,'olmayacak'::text,'Bugün aşı olmasalardı şimdi kollarında yara bandı olmazdı.'::text),
(400140,44460,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ma nem kapták volna meg az oltást, most nem ... tapasz a karjukon.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha ma nem kapták volna meg az oltást, most nem lenne tapasz a karjukon.'::text),
(400152,44462,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er leugnete buchstäblich, dass er Angst vor der Impfung ..., und dann sagte er „Au“!'::text,'habe'::text,'zu haben'::text,'haben'::text,'Er leugnete buchstäblich, dass er Angst vor der Impfung habe, und dann sagte er „Au“!'::text),
(400156,44462,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він буквально заперечував, що ... наляканий щепленням, а потім сказав «Ой»!'::text,'був'::text,'бути'::text,'бути'::text,'Він буквально заперечував, що був наляканий щепленням, а потім сказав «Ой»!'::text),
(400155,44462,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Literalmente negó ... miedo a la vacuna, y luego dijo «Ay»!'::text,'tener'::text,'tener'::text,'tener'::text,'¡Literalmente negó tener miedo a la vacuna, y luego dijo «Ay»!'::text),
(400154,44462,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a littéralement nié ... peur du vaccin, et ensuite il a dit « Aïe » !'::text,'avoir'::text,'avoir'::text,'avoir'::text,'Il a littéralement nié avoir peur du vaccin, et ensuite il a dit « Aïe » !'::text),
(400157,44462,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşıdan ... resmen inkâr etti, sonra da “Ah” dedi!'::text,'korktuğunu'::text,'korkmayı'::text,'korkmak'::text,'Aşıdan korktuğunu resmen inkâr etti, sonra da “Ah” dedi!'::text),
(400158,44462,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szó szerint tagadta, hogy ... az oltástól, aztán azt mondta: „Au”!'::text,'fél'::text,'félni'::text,'félni'::text,'Szó szerint tagadta, hogy fél az oltástól, aztán azt mondta: „Au”!'::text),
(400161,44463,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... mir sagen sollen, dass die Impfung nur ein kleiner Piks ist! Ich hatte total umsonst Todesangst!'::text,'hättest'::text,'musst'::text,'solltest'::text,'Du hättest mir sagen sollen, dass die Impfung nur ein kleiner Piks ist! Ich hatte total umsonst Todesangst!'::text),
(400165,44463,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... мені сказати, що щеплення — це лише маленький укол! Я був страшенно наляканий дарма!'::text,'мав би'::text,'напевно'::text,'маєш'::text,'Ти мав би мені сказати, що щеплення — це лише маленький укол! Я був страшенно наляканий дарма!'::text),
(400164,44463,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Me ... dicho que la vacuna era un pinchacito! ¡Estaba aterrado para nada!'::text,'deberías haber'::text,'debes haber'::text,'deberías'::text,'¡Me deberías haber dicho que la vacuna era un pinchacito! ¡Estaba aterrado para nada!'::text),
(400163,44463,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... me dire que le vaccin, c''était juste une petite piqûre ! J''étais terrifié pour rien !'::text,'aurais dû'::text,'as dû'::text,'devrais'::text,'Tu aurais dû me dire que le vaccin, c''était juste une petite piqûre ! J''étais terrifié pour rien !'::text),
(400166,44463,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşının minicik bir iğne olduğunu bana ...! Tamamen boşuna ödüm koptu!'::text,'söylemeliydin'::text,'söylemiş olmalısın'::text,'söylemelisin'::text,'Aşının minicik bir iğne olduğunu bana söylemeliydin! Tamamen boşuna ödüm koptu!'::text),
(400167,44463,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ... volna mondanod, hogy az oltás csak egy pici szúrás! Teljesen feleslegesen voltam halálra rémülve!'::text,'kellett'::text,'kellett'::text,'kell'::text,'El kellett volna mondanod, hogy az oltás csak egy pici szúrás! Teljesen feleslegesen voltam halálra rémülve!'::text),
(400170,44464,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... nach einer Impfung so glücklich.'::text,'wirkt eine Gruppe'::text,'eine Gruppe wirkt'::text,'wirkt eine Gruppe'::text,'Selten wirkt eine Gruppe nach einer Impfung so glücklich.'::text),
(400174,44464,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... такою щасливою після щеплення.'::text,'виглядає група'::text,'група виглядає'::text,'виглядає група'::text,'Рідко виглядає група такою щасливою після щеплення.'::text),
(400173,44464,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... tan feliz después de una vacuna.'::text,'se ve un grupo'::text,'un grupo se ve'::text,'se ve un grupo'::text,'Rara vez se ve un grupo tan feliz después de una vacuna.'::text),
(400172,44464,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... aussi heureux après un vaccin.'::text,'un groupe a-t-il l''air'::text,'un groupe a l''air'::text,'un groupe a-t-il l''air'::text,'Rarement un groupe a-t-il l''air aussi heureux après un vaccin.'::text),
(400175,44464,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren ... aşıdan sonra bu kadar mutlu görünür.'::text,'bir grup'::text,'bir grup'::text,'bir grup'::text,'Nadiren bir grup aşıdan sonra bu kadar mutlu görünür.'::text),
(400176,44464,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... ilyen boldognak egy oltás után.'::text,'néz ki egy csoport'::text,'egy csoport néz ki'::text,'néz ki egy csoport'::text,'Ritkán néz ki egy csoport ilyen boldognak egy oltás után.'::text),
(400179,44465,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, die ganze Gruppe hat sich in zehn Minuten ... lassen.'::text,'impfen'::text,'impfen'::text,'zu impfen'::text,'Bestie, ich hab gehört, die ganze Gruppe hat sich in zehn Minuten impfen lassen.'::text),
(400183,44465,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що вся група ... щеплення за десять хвилин.'::text,'зробила'::text,'робити'::text,'зробити'::text,'Подруго, я чула, що вся група зробила щеплення за десять хвилин.'::text),
(400182,44465,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, escuché que todo el grupo se ... las vacunas en diez minutos.'::text,'puso'::text,'pone'::text,'poner'::text,'Amiga, escuché que todo el grupo se puso las vacunas en diez minutos.'::text),
(400181,44465,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît que tout le groupe s''est fait ... en dix minutes.'::text,'vacciner'::text,'vacciner'::text,'vacciner'::text,'Ma belle, il paraît que tout le groupe s''est fait vacciner en dix minutes.'::text),
(400184,44465,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki bütün grup on dakikada aşılarını ...'::text,'olmuş'::text,'ol'::text,'olmak'::text,'Kanka, duydum ki bütün grup on dakikada aşılarını olmuş.'::text),
(400185,44465,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy az egész csoport tíz perc alatt ... az oltást.'::text,'beadatta'::text,'beadni'::text,'beadatni'::text,'Csajszi, azt hallottam, hogy az egész csoport tíz perc alatt beadatta az oltást.'::text),
(400188,44466,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, sie hat mir erzählt, sie wünschte, sie ... ihre Impfung lieber schon letzte Woche bekommen.'::text,'hätte'::text,'hat'::text,'hatte'::text,'Girl, sie hat mir erzählt, sie wünschte, sie hätte ihre Impfung lieber schon letzte Woche bekommen.'::text),
(400192,44466,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що краще б ... щеплення ще минулого тижня.'::text,'зробила'::text,'зробила'::text,'зробила'::text,'Подруго, вона сказала мені, що краще б зробила щеплення ще минулого тижня.'::text),
(400191,44466,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que ojalá ... puesto la vacuna la semana pasada.'::text,'se hubiera'::text,'se ha'::text,'se había'::text,'Tía, me dijo que ojalá se hubiera puesto la vacuna la semana pasada.'::text),
(400190,44466,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit qu''elle aurait préféré ... son vaccin la semaine dernière.'::text,'avoir fait'::text,'a fait'::text,'faire'::text,'Meuf, elle m''a dit qu''elle aurait préféré avoir fait son vaccin la semaine dernière.'::text),
(400193,44466,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana keşke aşısını geçen hafta ... dedi.'::text,'olsaydı'::text,'oldu'::text,'oldu'::text,'Kızım, bana keşke aşısını geçen hafta olsaydı dedi.'::text),
(400194,44466,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, bárcsak inkább múlt héten ... meg az oltást.'::text,'kapta volna'::text,'kapta'::text,'kapta'::text,'Csajszi, azt mondta, bárcsak inkább múlt héten kapta volna meg az oltást.'::text),
(400197,44467,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ..., die du heute bekommen hast, hat dich nicht mal erschreckt. Beeindruckend.'::text,'die Impfung'::text,'eine Impfung'::text,'Impfung'::text,'Ehrlich, die Impfung, die du heute bekommen hast, hat dich nicht mal erschreckt. Beeindruckend.'::text),
(400201,44467,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ..., яке ти сьогодні зробив, тебе навіть не налякало. Вражає.'::text,'щеплення'::text,'щеплення'::text,'щеплення'::text,'Чесно, щеплення, яке ти сьогодні зробив, тебе навіть не налякало. Вражає.'::text),
(400200,44467,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... que te pusieron hoy ni te asustó. Impresionante.'::text,'la vacuna'::text,'una vacuna'::text,'vacuna'::text,'La verdad, la vacuna que te pusieron hoy ni te asustó. Impresionante.'::text),
(400199,44467,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ... que tu as eu aujourd''hui ne t''a même pas fait peur. Impressionnant.'::text,'le vaccin'::text,'un vaccin'::text,'vaccin'::text,'Franchement, le vaccin que tu as eu aujourd''hui ne t''a même pas fait peur. Impressionnant.'::text),
(400202,44467,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bugün olduğun ... seni korkutmadı bile. Etkileyici.'::text,'aşı'::text,'bir aşı'::text,'aşı'::text,'Açıkçası bugün olduğun aşı seni korkutmadı bile. Etkileyici.'::text),
(400203,44467,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ..., amit ma kaptál, meg se ijesztett. Lenyűgöző.'::text,'az oltás'::text,'egy oltás'::text,'oltás'::text,'Őszintén, az oltás, amit ma kaptál, meg se ijesztett. Lenyűgöző.'::text),
(336441,37383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann mit der Aktentasche ... sein Büro verlassen, bevor er aufs Skateboard stieg.'::text,'hatte'::text,'hat'::text,'verlässt'::text,'Der Mann mit der Aktentasche hatte sein Büro verlassen, bevor er aufs Skateboard stieg.'::text),
(336445,37383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік з портфелем ... офіс, перш ніж став на скейтборд.'::text,'залишив'::text,'залишив'::text,'залишає'::text,'Чоловік з портфелем залишив офіс, перш ніж став на скейтборд.'::text),
(336444,37383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre del maletín ... su oficina antes de subirse al monopatín.'::text,'había dejado'::text,'ha dejado'::text,'deja'::text,'El hombre del maletín había dejado su oficina antes de subirse al monopatín.'::text),
(336443,37383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme à la mallette ... son bureau avant de monter sur le skateboard.'::text,'avait quitté'::text,'a quitté'::text,'quitte'::text,'L''homme à la mallette avait quitté son bureau avant de monter sur le skateboard.'::text),
(336446,37383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evrak çantalı adam kaykaya binmeden önce ofisinden ...'::text,'çıkmıştı'::text,'çıktı'::text,'çıkıyor'::text,'Evrak çantalı adam kaykaya binmeden önce ofisinden çıkmıştı.'::text),
(336447,37383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az aktatáskás férfi ... az irodáját, mielőtt gördeszkára lépett.'::text,'elhagyta'::text,'elhagyta'::text,'elhagyja'::text,'Az aktatáskás férfi elhagyta az irodáját, mielőtt gördeszkára lépett.'::text),
(336459,37385,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er seine Aktentasche auf einer Bank lassen würde, ... er leichter fahren.'::text,'würde'::text,'wird'::text,'fährt'::text,'Wenn er seine Aktentasche auf einer Bank lassen würde, würde er leichter fahren.'::text),
(336463,37385,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він залишив портфель на лавці, він ... легше.'::text,'їздив би'::text,'їздитиме'::text,'їздить'::text,'Якби він залишив портфель на лавці, він їздив би легше.'::text),
(336462,37385,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si dejara el maletín en un banco, ... con más facilidad.'::text,'patinaría'::text,'patinará'::text,'patina'::text,'Si dejara el maletín en un banco, patinaría con más facilidad.'::text),
(336461,37385,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il laissait sa mallette sur un banc, il ... plus facilement.'::text,'roulerait'::text,'roulera'::text,'roule'::text,'S''il laissait sa mallette sur un banc, il roulerait plus facilement.'::text),
(336464,37385,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evrak çantasını bir bankta bıraksa daha kolay ...'::text,'kayardı'::text,'kayacak'::text,'kayıyor'::text,'Evrak çantasını bir bankta bıraksa daha kolay kayardı.'::text),
(336465,37385,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az aktatáskáját egy padon hagyná, könnyebben ...'::text,'gurulna'::text,'fog gurulni'::text,'gurul'::text,'Ha az aktatáskáját egy padon hagyná, könnyebben gurulna.'::text),
(336468,37386,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also, anscheinend ... ihm die Aktentasche von seinem Chef geschenkt.'::text,'wurde'::text,'wird'::text,'schenkte'::text,'Okay, also, anscheinend wurde ihm die Aktentasche von seinem Chef geschenkt.'::text),
(336472,37386,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Короче, кажуть, цей портфель ... йому шефом у подарунок.'::text,'був подарований'::text,'дарується'::text,'подарував'::text,'Короче, кажуть, цей портфель був подарований йому шефом у подарунок.'::text),
(336471,37386,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer ese maletín le ... como regalo por su jefe.'::text,'fue dado'::text,'es dado'::text,'dio'::text,'Vale, pues al parecer ese maletín le fue dado como regalo por su jefe.'::text),
(336470,37386,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment cette mallette lui ... en cadeau par son patron.'::text,'a été offerte'::text,'est offerte'::text,'a offert'::text,'Bon alors, apparemment cette mallette lui a été offerte en cadeau par son patron.'::text),
(336473,37386,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, güya o evrak çantası ona patronu tarafından hediye olarak ...'::text,'verilmiş'::text,'veriliyor'::text,'verdi'::text,'Neyse, güya o evrak çantası ona patronu tarafından hediye olarak verilmiş.'::text),
(336474,37386,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag azt az aktatáskát ajándékba ... a főnökétől.'::text,'kapta'::text,'kapja'::text,'adta'::text,'Szóval állítólag azt az aktatáskát ajándékba kapta a főnökétől.'::text),
(336477,37387,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann im Anzug ... beim Fahren seine Aktentasche in einer Hand.'::text,'hält'::text,'wird gehalten'::text,'haltend'::text,'Der Mann im Anzug hält beim Fahren seine Aktentasche in einer Hand.'::text),
(336481,37387,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у костюмі ... портфель в одній руці, поки їде.'::text,'тримає'::text,'тримається'::text,'тримаючи'::text,'Чоловік у костюмі тримає портфель в одній руці, поки їде.'::text),
(336480,37387,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre del traje ... el maletín en una mano mientras patina.'::text,'sostiene'::text,'es sostenido'::text,'sosteniendo'::text,'El hombre del traje sostiene el maletín en una mano mientras patina.'::text),
(336479,37387,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme en costume ... sa mallette d''une main pendant qu''il roule.'::text,'tient'::text,'est tenu'::text,'tenant'::text,'L''homme en costume tient sa mallette d''une main pendant qu''il roule.'::text),
(336482,37387,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takım elbiseli adam kayarken evrak çantasını tek elinde ...'::text,'tutuyor'::text,'tutuluyor'::text,'tutarak'::text,'Takım elbiseli adam kayarken evrak çantasını tek elinde tutuyor.'::text),
(336483,37387,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az öltönyös férfi gurulás közben egy kézben ... az aktatáskáját.'::text,'tartja'::text,'tartva van'::text,'tartva'::text,'Az öltönyös férfi gurulás közben egy kézben tartja az aktatáskáját.'::text),
(336486,37388,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit Aktentasche skaten? Du ... der smootheste Mensch auf dieser Promenade sein.'::text,'musst'::text,'kannst nicht'::text,'solltest'::text,'Mit Aktentasche skaten? Du musst der smootheste Mensch auf dieser Promenade sein.'::text),
(336490,37388,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кататися на скейтборді з портфелем? Ти ... бути найхаризматичнішою людиною на цій набережній.'::text,'мусиш'::text,'не можеш'::text,'мав би'::text,'Кататися на скейтборді з портфелем? Ти мусиш бути найхаризматичнішою людиною на цій набережній.'::text),
(336489,37388,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Patinar con maletín? Tú ... ser la persona con más flow de este paseo.'::text,'debes de'::text,'no puedes'::text,'deberías'::text,'¿Patinar con maletín? Tú debes de ser la persona con más flow de este paseo.'::text),
(336488,37388,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Skater avec une mallette ? Tu ... être la personne la plus stylée de cette promenade.'::text,'dois'::text,'ne peux pas'::text,'devrais'::text,'Skater avec une mallette ? Tu dois être la personne la plus stylée de cette promenade.'::text),
(336491,37388,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evrak çantasıyla kaykay mı? Bu sahil yolundaki en havalı insan sen ...'::text,'olmalısın'::text,'olamazsın'::text,'olmalısın'::text,'Evrak çantasıyla kaykay mı? Bu sahil yolundaki en havalı insan sen olmalısın.'::text),
(336492,37388,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gördeszkázni aktatáskával? Neked ... a legmenőbb embernek lenned ezen a sétányon.'::text,'kell'::text,'nem lehet'::text,'kellene'::text,'Gördeszkázni aktatáskával? Neked kell a legmenőbb embernek lenned ezen a sétányon.'::text),
(336495,37389,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann, ... eine Aktentasche trägt, ist eindeutig fürs Skaten angezogen.'::text,'der'::text,'das'::text,'dessen'::text,'Der Mann, der eine Aktentasche trägt, ist eindeutig fürs Skaten angezogen.'::text),
(336499,37389,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік, ... несе портфель, явно вдягнений для скейтингу.'::text,'який'::text,'що'::text,'чий'::text,'Чоловік, який несе портфель, явно вдягнений для скейтингу.'::text),
(336498,37389,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... lleva un maletín claramente va vestido para patinar.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El hombre que lleva un maletín claramente va vestido para patinar.'::text),
(336497,37389,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... porte une mallette est clairement habillé pour skater.'::text,'qui'::text,'lequel'::text,'dont'::text,'L''homme qui porte une mallette est clairement habillé pour skater.'::text),
(336500,37389,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam, ... evrak çantası taşıyor, belli ki kaykay için giyinmiş.'::text,'ki'::text,'ki'::text,'ki onun'::text,'Adam, ki evrak çantası taşıyor, belli ki kaykay için giyinmiş.'::text),
(336501,37389,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi, ... aktatáskát visz, egyértelműen gördeszkázáshoz öltözött.'::text,'aki'::text,'amely'::text,'akinek'::text,'A férfi, aki aktatáskát visz, egyértelműen gördeszkázáshoz öltözött.'::text),
(336504,37390,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Tag davor sagte er, er ... seine Aktentasche zu Hause lassen. Eindeutig ein Mann, der Wort hält.'::text,'würde'::text,'wird'::text,'lässt'::text,'Am Tag davor sagte er, er würde seine Aktentasche zu Hause lassen. Eindeutig ein Mann, der Wort hält.'::text),
(336508,37390,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Напередодні він сказав, що ... портфель удома. Явно людина слова.'::text,'залишить'::text,'залишить'::text,'залишає'::text,'Напередодні він сказав, що залишить портфель удома. Явно людина слова.'::text),
(336507,37390,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El día anterior dijo que ... el maletín en casa. Claramente un hombre de palabra.'::text,'dejaría'::text,'dejará'::text,'deja'::text,'El día anterior dijo que dejaría el maletín en casa. Claramente un hombre de palabra.'::text),
(336506,37390,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La veille, il a dit qu''il ... sa mallette à la maison. Clairement un homme de parole.'::text,'laisserait'::text,'laissera'::text,'laisse'::text,'La veille, il a dit qu''il laisserait sa mallette à la maison. Clairement un homme de parole.'::text),
(336509,37390,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir gün önce evrak çantasını evde ... söyledi. Belli ki sözünün eri.'::text,'bırakacağını'::text,'bırakacağını'::text,'bıraktığını'::text,'Bir gün önce evrak çantasını evde bırakacağını söyledi. Belli ki sözünün eri.'::text),
(336510,37390,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Előző nap azt mondta, hogy otthon ... az aktatáskáját. Egyértelműen szavatartó ember.'::text,'hagyja'::text,'fogja hagyni'::text,'hagyja'::text,'Előző nap azt mondta, hogy otthon hagyja az aktatáskáját. Egyértelműen szavatartó ember.'::text),
(336513,37391,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... früher Skateboards, jetzt fährt er eins mit Aktentasche, echt.'::text,'hasste'::text,'hasste'::text,'ist es gewohnt zu hassen'::text,'Alter, er hasste früher Skateboards, jetzt fährt er eins mit Aktentasche, echt.'::text),
(336517,37391,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він ... скейтборди, а тепер катається на одному з портфелем, чесно.'::text,'раніше ненавидів'::text,'ненавидів би'::text,'звик ненавидіти'::text,'Чувак, він раніше ненавидів скейтборди, а тепер катається на одному з портфелем, чесно.'::text),
(336516,37391,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... los monopatines, y ahora va en uno con el maletín, en serio.'::text,'odiaba'::text,'odiaría'::text,'está acostumbrado a odiar'::text,'Tío, él odiaba los monopatines, y ahora va en uno con el maletín, en serio.'::text),
(336515,37391,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ... les skateboards, maintenant il en fait avec sa mallette, sérieux.'::text,'détestait'::text,'détesterait'::text,'a l''habitude de détester'::text,'Mec, il détestait les skateboards, maintenant il en fait avec sa mallette, sérieux.'::text),
(336518,37391,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eskiden kaykaylardan ..., şimdi evrak çantasıyla kaykay sürüyor, cidden.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkın'::text,'Kanka, eskiden kaykaylardan nefret ederdi, şimdi evrak çantasıyla kaykay sürüyor, cidden.'::text),
(336519,37391,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, régen ... a gördeszkákat, most meg aktatáskával gördeszkázik, komolyan.'::text,'utálta'::text,'utálta volna'::text,'hozzá van szokva, hogy utálja'::text,'Tesó, régen utálta a gördeszkákat, most meg aktatáskával gördeszkázik, komolyan.'::text),
(336522,37392,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er kann dem ... nicht widerstehen, sogar mit Aktentasche in der Hand, echt.'::text,'Skaten'::text,'Skaten'::text,'Skaten'::text,'Alter, er kann dem Skaten nicht widerstehen, sogar mit Aktentasche in der Hand, echt.'::text),
(336526,37392,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він не може встояти перед ..., навіть з портфелем у руці, чесно.'::text,'катанням'::text,'кататися'::text,'кататися'::text,'Чувак, він не може встояти перед катанням, навіть з портфелем у руці, чесно.'::text),
(336525,37392,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, no puede resistirse a ..., ni siquiera con el maletín en la mano, en serio.'::text,'patinar'::text,'patinar'::text,'patinar'::text,'Tío, no puede resistirse a patinar, ni siquiera con el maletín en la mano, en serio.'::text),
(336524,37392,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ne peut pas s''empêcher de ..., même avec une mallette à la main, sérieux.'::text,'skater'::text,'skater'::text,'skater'::text,'Mec, il ne peut pas s''empêcher de skater, même avec une mallette à la main, sérieux.'::text),
(336527,37392,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, elinde evrak çantası olsa bile ... karşı koyamıyor, cidden.'::text,'kaymaya'::text,'kaymaya'::text,'kaymak'::text,'Kanka, elinde evrak çantası olsa bile kaymaya karşı koyamıyor, cidden.'::text),
(336528,37392,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nem tud ellenállni a ..., még aktatáskával a kezében sem, komolyan.'::text,'gördeszkázásnak'::text,'gördeszkázni'::text,'gördeszkázni'::text,'Tesó, nem tud ellenállni a gördeszkázásnak, még aktatáskával a kezében sem, komolyan.'::text),
(353757,39307,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie schwört, dass sie den Bildschirm diesmal richtig an der Wand ...'::text,'befestigen wird'::text,'befestigen wird'::text,'befestigt'::text,'Bestie, sie schwört, dass sie den Bildschirm diesmal richtig an der Wand befestigen wird.'::text),
(353761,39307,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона клянеться, що цього разу нормально ... екран до стіни.'::text,'прикріпить'::text,'кріпитиме'::text,'кріпить'::text,'Подруго, вона клянеться, що цього разу нормально прикріпить екран до стіни.'::text),
(353760,39307,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, jura que esta vez ... bien la pantalla a la pared.'::text,'fijará'::text,'estará fijando'::text,'está fijando'::text,'Amiga, jura que esta vez fijará bien la pantalla a la pared.'::text),
(353759,39307,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle jure qu''elle ... l''écran au mur correctement cette fois.'::text,'fixera'::text,'sera en train de fixer'::text,'fixe'::text,'Ma belle, elle jure qu''elle fixera l''écran au mur correctement cette fois.'::text),
(353762,39307,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu sefer ekranı duvara düzgünce ... yemin ediyor.'::text,'sabitleyeceğine'::text,'sabitliyor olacağına'::text,'sabitlediğine'::text,'Kanka, bu sefer ekranı duvara düzgünce sabitleyeceğine yemin ediyor.'::text),
(353763,39307,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, esküszik, hogy ezúttal rendesen ... a képernyőt a falra.'::text,'felrögzíti'::text,'fel fogja rögzíteni'::text,'rögzíti'::text,'Csajszi, esküszik, hogy ezúttal rendesen felrögzíti a képernyőt a falra.'::text),
(353766,39308,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du eine Halterung so fest ..., fällt der Bildschirm nie runter.'::text,'befestigst'::text,'befestigtest'::text,'befestigen wirst'::text,'Ehrlich, wenn du eine Halterung so fest befestigst, fällt der Bildschirm nie runter.'::text),
(353770,39308,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якщо ти ... кронштейн так міцно, екран ніколи не падає.'::text,'кріпиш'::text,'прикріпив'::text,'прикріпиш'::text,'Чесно, якщо ти кріпиш кронштейн так міцно, екран ніколи не падає.'::text),
(353769,39308,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, si ... un soporte así de firme, la pantalla nunca se cae.'::text,'fijas'::text,'fijaste'::text,'fijarás'::text,'La verdad, si fijas un soporte así de firme, la pantalla nunca se cae.'::text),
(353768,39308,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu ... un support aussi solidement, l''écran ne tombe jamais.'::text,'fixes'::text,'fixais'::text,'fixeras'::text,'Franchement, si tu fixes un support aussi solidement, l''écran ne tombe jamais.'::text),
(353771,39308,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bir askıyı bu kadar sağlam ..., ekran asla düşmez.'::text,'sabitlersen'::text,'sabitlesen'::text,'sabitleyeceksen'::text,'Açıkçası, bir askıyı bu kadar sağlam sabitlersen, ekran asla düşmez.'::text),
(353772,39308,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha ilyen erősen ... fel egy tartót, a képernyő sosem esik le.'::text,'rögzítesz'::text,'rögzítettél'::text,'fogsz rögzíteni'::text,'Őszintén, ha ilyen erősen rögzítesz fel egy tartót, a képernyő sosem esik le.'::text),
(353775,39309,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Smooth: Du hast den Bildschirm auf Anhieb an der Wand befestigt, ...?'::text,'nicht wahr'::text,'oder'::text,'oder'::text,'Smooth: Du hast den Bildschirm auf Anhieb an der Wand befestigt, nicht wahr?'::text),
(353779,39309,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стильно: ти прикріпив той екран до стіни з першого разу, ...?'::text,'правда'::text,'хіба ні'::text,'так'::text,'Стильно: ти прикріпив той екран до стіни з першого разу, правда?'::text),
(353778,39309,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué estilo: fijaste esa pantalla a la pared a la primera, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Qué estilo: fijaste esa pantalla a la pared a la primera, ¿verdad?'::text),
(353777,39309,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trop classe : tu as fixé cet écran au mur du premier coup, ... ?'::text,'n''est-ce pas'::text,'non'::text,'hein'::text,'Trop classe : tu as fixé cet écran au mur du premier coup, n''est-ce pas ?'::text),
(353780,39309,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havalı: o ekranı tek seferde duvara sabitledin, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Havalı: o ekranı tek seferde duvara sabitledin, değil mi?'::text),
(353781,39309,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Menő: elsőre felrögzítetted azt a képernyőt a falra, ...?'::text,'ugye'::text,'nem igaz'::text,'ugye'::text,'Menő: elsőre felrögzítetted azt a képernyőt a falra, ugye?'::text),
(353784,39310,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig ein Job für zwei: Sie hat die Halterung an der Wand befestigt, und ...'::text,'er auch'::text,'er auch'::text,'er auch'::text,'Eindeutig ein Job für zwei: Sie hat die Halterung an der Wand befestigt, und er auch.'::text),
(353788,39310,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно робота для двох: вона прикріпила кронштейн до стіни, і ...'::text,'він теж'::text,'він теж'::text,'він теж'::text,'Явно робота для двох: вона прикріпила кронштейн до стіни, і він теж.'::text),
(353787,39310,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente un trabajo de dos: ella fijó el soporte a la pared, y ...'::text,'él también'::text,'él también'::text,'él también'::text,'Claramente un trabajo de dos: ella fijó el soporte a la pared, y él también.'::text),
(353786,39310,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un boulot à deux : elle a fixé le support au mur, et ...'::text,'lui aussi'::text,'lui aussi'::text,'lui aussi'::text,'Clairement un boulot à deux : elle a fixé le support au mur, et lui aussi.'::text),
(353789,39310,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki iki kişilik iş: kadın askıyı duvara sabitledi, ...'::text,'adam da'::text,'adam da'::text,'adam da'::text,'Belli ki iki kişilik iş: kadın askıyı duvara sabitledi, adam da.'::text),
(353790,39310,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen kétfős meló: a nő felrögzítette a tartót a falra, és ...'::text,'a férfi is'::text,'a férfi is'::text,'a férfi is'::text,'Egyértelműen kétfős meló: a nő felrögzítette a tartót a falra, és a férfi is.'::text),
(353793,39311,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Mittag ... sie alle neun Bildschirme an der Wand befestigt haben. Eindeutig ein ruhiger Tag.'::text,'werden'::text,'werden'::text,'werden'::text,'Bis zum Mittag werden sie alle neun Bildschirme an der Wand befestigt haben. Eindeutig ein ruhiger Tag.'::text),
(353797,39311,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду вони ... всі дев''ять екранів до стіни. Явно повільний день.'::text,'прикріплять'::text,'прикріплять'::text,'кріпитимуть'::text,'До обіду вони прикріплять всі дев''ять екранів до стіни. Явно повільний день.'::text),
(353796,39311,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la hora de comer, ... las nueve pantallas a la pared. Claramente un día tranquilo.'::text,'habrán fijado'::text,'fijarán'::text,'estarán fijando'::text,'Para la hora de comer, habrán fijado las nueve pantallas a la pared. Claramente un día tranquilo.'::text),
(353795,39311,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le déjeuner, ils ... les neuf écrans au mur. Clairement une journée tranquille.'::text,'auront fixé'::text,'fixeront'::text,'seront en train de fixer'::text,'D''ici le déjeuner, ils auront fixé les neuf écrans au mur. Clairement une journée tranquille.'::text),
(353798,39311,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeğine kadar dokuz ekranın hepsini duvara ..., belli ki sakin bir gün.'::text,'sabitlemiş olacaklar'::text,'sabitleyecekler'::text,'sabitliyor olacaklar'::text,'Öğle yemeğine kadar dokuz ekranın hepsini duvara sabitlemiş olacaklar, belli ki sakin bir gün.'::text),
(353799,39311,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebédre mind a kilenc képernyőt ... a falra. Egyértelműen lassú nap.'::text,'felrögzítik'::text,'fel fogják rögzíteni'::text,'rögzíteni fogják'::text,'Ebédre mind a kilenc képernyőt felrögzítik a falra. Egyértelműen lassú nap.'::text),
(353802,39312,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn sie die Halterung nicht befestigt hätten, ... der Bildschirm direkt runtergekracht, echt.'::text,'wäre'::text,'wird'::text,'ist'::text,'Digga, wenn sie die Halterung nicht befestigt hätten, wäre der Bildschirm direkt runtergekracht, echt.'::text),
(353806,39312,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, якби вони не прикріпили той кронштейн, екран ... прямо вниз, чесно.'::text,'гепнувся б'::text,'гепнеться'::text,'гепнувся'::text,'Брате, якби вони не прикріпили той кронштейн, екран гепнувся б прямо вниз, чесно.'::text),
(353805,39312,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si no hubieran fijado ese soporte, la pantalla ... directo al suelo, en serio.'::text,'se habría estrellado'::text,'se estrellará'::text,'se estrelló'::text,'Bro, si no hubieran fijado ese soporte, la pantalla se habría estrellado directo al suelo, en serio.'::text),
(353804,39312,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, s''ils n''avaient pas fixé ce support, l''écran ... direct par terre, sérieux.'::text,'se serait écrasé'::text,'s''écrasera'::text,'s''est écrasé'::text,'Frère, s''ils n''avaient pas fixé ce support, l''écran se serait écrasé direct par terre, sérieux.'::text),
(353807,39312,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o askıyı sabitlemeselerdi ekran direkt aşağı ..., cidden.'::text,'çakılırdı'::text,'çakılacak'::text,'çakıldı'::text,'Kanka, o askıyı sabitlemeselerdi ekran direkt aşağı çakılırdı, cidden.'::text),
(353808,39312,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nem rögzítették volna fel azt a tartót, a képernyő egyenesen ..., komolyan.'::text,'lezuhant volna'::text,'le fog zuhanni'::text,'lezuhant'::text,'Tesó, ha nem rögzítették volna fel azt a tartót, a képernyő egyenesen lezuhant volna, komolyan.'::text),
(353811,39313,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie hat angeboten, den Bildschirm selbst an der Wand ..., kein Witz.'::text,'zu befestigen'::text,'befestigen'::text,'befestigt'::text,'Digga, sie hat angeboten, den Bildschirm selbst an der Wand zu befestigen, kein Witz.'::text),
(353815,39313,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, вона сама запропонувала ... екран до стіни, без брехні.'::text,'прикріпити'::text,'кріплення'::text,'прикріпила'::text,'Брате, вона сама запропонувала прикріпити екран до стіни, без брехні.'::text),
(353814,39313,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, se ofreció a ... ella misma la pantalla a la pared, en serio.'::text,'fijar'::text,'fijando'::text,'fijado'::text,'Bro, se ofreció a fijar ella misma la pantalla a la pared, en serio.'::text),
(353813,39313,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle a proposé ... l''écran au mur elle-même, sans mentir.'::text,'de fixer'::text,'fixant'::text,'fixé'::text,'Frère, elle a proposé de fixer l''écran au mur elle-même, sans mentir.'::text),
(353816,39313,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ekranı duvara kendisi ... teklif etti, yalan yok.'::text,'sabitlemeyi'::text,'sabitlemeyi'::text,'sabitledi'::text,'Kanka, ekranı duvara kendisi sabitlemeyi teklif etti, yalan yok.'::text),
(353817,39313,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, felajánlotta, hogy ő maga ... fel a képernyőt a falra, komolyan.'::text,'rögzíti'::text,'rögzítés'::text,'rögzítette'::text,'Tesó, felajánlotta, hogy ő maga rögzíti fel a képernyőt a falra, komolyan.'::text),
(353820,39314,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bildschirm hat das 5-Punkte-Audit bestanden, also ... sie die Halterung korrekt befestigt haben.'::text,'müssen'::text,'sollten'::text,'können nicht'::text,'Der Bildschirm hat das 5-Punkte-Audit bestanden, also müssen sie die Halterung korrekt befestigt haben.'::text),
(353824,39314,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Екран пройшов аудит із 5 пунктів, тож вони ... правильно закріпити кронштейн.'::text,'мусили'::text,'мали'::text,'не могли'::text,'Екран пройшов аудит із 5 пунктів, тож вони мусили правильно закріпити кронштейн.'::text),
(353823,39314,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pantalla pasó la auditoría de 5 puntos, así que ... fijado bien el soporte.'::text,'deben de haber'::text,'deberían haber'::text,'no pueden haber'::text,'La pantalla pasó la auditoría de 5 puntos, así que deben de haber fijado bien el soporte.'::text),
(353822,39314,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''écran a passé l''audit en 5 points, donc ils ... fixé le support correctement.'::text,'ont dû'::text,'auraient dû'::text,'n''ont pas pu'::text,'L''écran a passé l''audit en 5 points, donc ils ont dû fixé le support correctement.'::text),
(353825,39314,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekran 5 maddelik denetimi geçti, yani askıyı doğru ...'::text,'sabitlemiş olmalılar'::text,'sabitlemeliydiler'::text,'sabitlemiş olamazlar'::text,'Ekran 5 maddelik denetimi geçti, yani askıyı doğru sabitlemiş olmalılar.'::text),
(353826,39314,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A képernyő átment az 5 pontos auditon, szóval a tartót ... helyesen rögzíteniük.'::text,'kellett'::text,'kellett volna'::text,'nem lehetett'::text,'A képernyő átment az 5 pontos auditon, szóval a tartót kellett helyesen rögzíteniük.'::text),
(353838,39316,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Halterung an der Wand befestigt, bevor sie den Bildschirm hochhoben.'::text,'hatten'::text,'haben'::text,'waren'::text,'Sie hatten die Halterung an der Wand befestigt, bevor sie den Bildschirm hochhoben.'::text),
(353842,39316,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... кронштейн до стіни, перш ніж підняли екран.'::text,'прикріпили'::text,'прикріпили'::text,'кріпили'::text,'Вони прикріпили кронштейн до стіни, перш ніж підняли екран.'::text),
(353841,39316,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el soporte a la pared antes de levantar la pantalla.'::text,'Habían fijado'::text,'Han fijado'::text,'Estaban fijando'::text,'Habían fijado el soporte a la pared antes de levantar la pantalla.'::text),
(353840,39316,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... le support au mur avant de soulever l''écran.'::text,'avaient fixé'::text,'ont fixé'::text,'fixaient'::text,'Ils avaient fixé le support au mur avant de soulever l''écran.'::text),
(353843,39316,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekranı kaldırmadan önce askıyı duvara ...'::text,'sabitlemişlerdi'::text,'sabitlediler'::text,'sabitliyorlardı'::text,'Ekranı kaldırmadan önce askıyı duvara sabitlemişlerdi.'::text),
(353844,39316,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt felemelték a képernyőt, már ... a tartót a falra.'::text,'felrögzítették'::text,'felrögzítették'::text,'rögzítették'::text,'Mielőtt felemelték a képernyőt, már felrögzítették a tartót a falra.'::text),
(376455,41829,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade ihre Arbeit, als der Kaffee kam. Perfektes Timing, natürlich.'::text,'präsentierte'::text,'präsentierte'::text,'hat präsentiert'::text,'Sie präsentierte gerade ihre Arbeit, als der Kaffee kam. Perfektes Timing, natürlich.'::text),
(376459,41829,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... свою роботу, коли принесли каву. Ідеальний таймінг, звісно.'::text,'презентувала'::text,'презентувала'::text,'презентувала'::text,'Вона презентувала свою роботу, коли принесли каву. Ідеальний таймінг, звісно.'::text),
(376458,41829,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... su trabajo cuando llegó el café. Timing perfecto, obvio.'::text,'estaba presentando'::text,'presentó'::text,'ha presentado'::text,'Ella estaba presentando su trabajo cuando llegó el café. Timing perfecto, obvio.'::text),
(376457,41829,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son travail quand le café est arrivé. Timing parfait, évidemment.'::text,'présentait'::text,'a présenté'::text,'a présenté'::text,'Elle présentait son travail quand le café est arrivé. Timing parfait, évidemment.'::text),
(376460,41829,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kahve geldiğinde işini ..., mükemmel zamanlama tabii.'::text,'sunuyordu'::text,'sundu'::text,'sundu'::text,'Kahve geldiğinde işini sunuyordu, mükemmel zamanlama tabii.'::text),
(376461,41829,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a munkáját, amikor megjött a kávé. Tökéletes időzítés, nyilván.'::text,'mutatta be'::text,'bemutatta'::text,'bemutatta'::text,'Épp mutatta be a munkáját, amikor megjött a kávé. Tökéletes időzítés, nyilván.'::text),
(376464,41830,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihr Projekt seit zwanzig Minuten, und niemand hat zugehört. Fesselnd.'::text,'präsentiert'::text,'präsentiert'::text,'präsentiert'::text,'Sie präsentiert ihr Projekt seit zwanzig Minuten, und niemand hat zugehört. Fesselnd.'::text),
(376468,41830,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... свій проєкт уже двадцять хвилин, і ніхто не слухає. Захопливо.'::text,'презентує'::text,'презентує'::text,'презентує'::text,'Вона презентує свій проєкт уже двадцять хвилин, і ніхто не слухає. Захопливо.'::text),
(376467,41830,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... su proyecto desde hace veinte minutos, y nadie la ha escuchado. Apasionante.'::text,'ha estado presentando'::text,'está presentando'::text,'presenta'::text,'Ella ha estado presentando su proyecto desde hace veinte minutos, y nadie la ha escuchado. Apasionante.'::text),
(376466,41830,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son projet depuis vingt minutes, et personne n''a écouté. Captivant.'::text,'présente'::text,'présente'::text,'présente'::text,'Elle présente son projet depuis vingt minutes, et personne n''a écouté. Captivant.'::text),
(376469,41830,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yirmi dakikadır projesini ... ve kimse dinlemedi. Büyüleyici.'::text,'sunuyor'::text,'sunuyor'::text,'sunar'::text,'Yirmi dakikadır projesini sunuyor ve kimse dinlemedi. Büyüleyici.'::text),
(376470,41830,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Húsz perce ... a projektjét, és senki sem figyelt. Lebilincselő.'::text,'mutatja be'::text,'mutatja be'::text,'mutatja be'::text,'Húsz perce mutatja be a projektjét, és senki sem figyelt. Lebilincselő.'::text),
(376473,41831,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Kaffee ... rein, während sie präsentierte, ziemlich brutal.'::text,'kam'::text,'kam gerade'::text,'ist gekommen'::text,'Digga, der Kaffee kam rein, während sie präsentierte, ziemlich brutal.'::text),
(376477,41831,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, каву ..., поки вона презентувала, жорстко.'::text,'принесли'::text,'несли'::text,'принесли'::text,'Брате, каву принесли, поки вона презентувала, жорстко.'::text),
(376476,41831,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el café ... mientras ella presentaba, qué fuerte.'::text,'llegó'::text,'estaba llegando'::text,'ha llegado'::text,'Bro, el café llegó mientras ella presentaba, qué fuerte.'::text),
(376475,41831,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le café ... pendant qu''elle présentait, un peu violent.'::text,'est arrivé'::text,'arrivait'::text,'est arrivé'::text,'Frère, le café est arrivé pendant qu''elle présentait, un peu violent.'::text),
(376478,41831,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o sunum yaparken kahve ..., baya acımasız.'::text,'geldi'::text,'geliyordu'::text,'gelmiş'::text,'Kanka, o sunum yaparken kahve geldi, baya acımasız.'::text),
(376479,41831,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a kávé pont akkor ..., amikor prezentált, elég brutál.'::text,'jött be'::text,'jött be épp'::text,'bejött'::text,'Tesó, a kávé pont akkor jött be, amikor prezentált, elég brutál.'::text),
(376491,41833,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Kaffee kam, ... sie erst die Hälfte des Q3-Berichts präsentiert.'::text,'hatte'::text,'hat'::text,'präsentiert'::text,'Als der Kaffee kam, hatte sie erst die Hälfte des Q3-Berichts präsentiert.'::text),
(376495,41833,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли принесли каву, вона ... лише половину звіту за третій квартал.'::text,'презентувала'::text,'презентувала'::text,'презентує'::text,'Коли принесли каву, вона презентувала лише половину звіту за третій квартал.'::text),
(376494,41833,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegó el café, ... solo la mitad del informe del tercer trimestre.'::text,'había presentado'::text,'ha presentado'::text,'presenta'::text,'Para cuando llegó el café, había presentado solo la mitad del informe del tercer trimestre.'::text),
(376493,41833,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le café est arrivé, elle ... seulement la moitié du rapport du T3.'::text,'avait présenté'::text,'a présenté'::text,'présente'::text,'Quand le café est arrivé, elle avait présenté seulement la moitié du rapport du T3.'::text),
(376496,41833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kahve geldiğinde üçüncü çeyrek raporunun sadece yarısını ...'::text,'sunmuştu'::text,'sundu'::text,'sunuyor'::text,'Kahve geldiğinde üçüncü çeyrek raporunun sadece yarısını sunmuştu.'::text),
(376497,41833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire megjött a kávé, a Q3-as jelentésnek csak a felét ...'::text,'mutatta be'::text,'mutatta be'::text,'mutatja be'::text,'Mire megjött a kávé, a Q3-as jelentésnek csak a felét mutatta be.'::text),
(376500,41834,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie steht am Whiteboard, also wenn sie dort präsentiert, ... alle sie dort sehen.'::text,'werden'::text,'würden'::text,'sahen'::text,'Sie steht am Whiteboard, also wenn sie dort präsentiert, werden alle sie dort sehen.'::text),
(376504,41834,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона біля дошки, тож якщо вона там презентуватиме, всі її там ...'::text,'побачать'::text,'побачили б'::text,'бачили'::text,'Вона біля дошки, тож якщо вона там презентуватиме, всі її там побачать.'::text),
(376503,41834,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está en la pizarra, así que si presenta ahí, todos la ... ahí.'::text,'verán'::text,'verían'::text,'vieron'::text,'Está en la pizarra, así que si presenta ahí, todos la verán ahí.'::text),
(376502,41834,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est au tableau, donc si elle présente là-bas, tout le monde la ... là-bas.'::text,'verra'::text,'verrait'::text,'a vue'::text,'Elle est au tableau, donc si elle présente là-bas, tout le monde la verra là-bas.'::text),
(376505,41834,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz tahtanın başında, yani orada sunum yaparsa herkes onu orada ...'::text,'görecek'::text,'görürdü'::text,'gördü'::text,'Beyaz tahtanın başında, yani orada sunum yaparsa herkes onu orada görecek.'::text),
(376506,41834,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A táblánál áll, szóval ha ott prezentál, mindenki ott ... őt.'::text,'fogja látni'::text,'látná'::text,'látta'::text,'A táblánál áll, szóval ha ott prezentál, mindenki ott fogja látni őt.'::text),
(376509,41835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Kollegen still blieben, ... sie ihr gesamtes Projekt präsentieren, wie dokumentiert.'::text,'würde'::text,'wird'::text,'präsentiert'::text,'Wenn die Kollegen still blieben, würde sie ihr gesamtes Projekt präsentieren, wie dokumentiert.'::text),
(376513,41835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби колеги мовчали, вона ... весь свій проєкт, як задокументовано.'::text,'презентувала б'::text,'презентує'::text,'презентує'::text,'Якби колеги мовчали, вона презентувала б весь свій проєкт, як задокументовано.'::text),
(376512,41835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los colegas se quedaran callados, ... todo su proyecto, según consta.'::text,'presentaría'::text,'presentará'::text,'presenta'::text,'Si los colegas se quedaran callados, presentaría todo su proyecto, según consta.'::text),
(376511,41835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les collègues restaient silencieux, elle ... tout son projet, comme documenté.'::text,'présenterait'::text,'présentera'::text,'présente'::text,'Si les collègues restaient silencieux, elle présenterait tout son projet, comme documenté.'::text),
(376514,41835,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meslektaşları sessiz kalsa, belgelendiği gibi tüm projesini ...'::text,'sunardı'::text,'sunacak'::text,'sunuyor'::text,'Meslektaşları sessiz kalsa, belgelendiği gibi tüm projesini sunardı.'::text),
(376515,41835,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kollégák csendben maradnának, ... a teljes projektjét, ahogy dokumentálva van.'::text,'bemutatná'::text,'be fogja mutatni'::text,'bemutatja'::text,'Ha a kollégák csendben maradnának, bemutatná a teljes projektjét, ahogy dokumentálva van.'::text),
(376518,41836,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das neue Projekt ... dem Team heute Morgen im Besprechungsraum präsentiert.'::text,'wurde'::text,'wird'::text,'präsentierte'::text,'Das neue Projekt wurde dem Team heute Morgen im Besprechungsraum präsentiert.'::text),
(376522,41836,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Новий проєкт ... команді в переговорній сьогодні вранці.'::text,'був презентований'::text,'презентується'::text,'презентував'::text,'Новий проєкт був презентований команді в переговорній сьогодні вранці.'::text),
(376521,41836,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El nuevo proyecto ... al equipo en la sala de reuniones esta mañana.'::text,'fue presentado'::text,'es presentado'::text,'presentó'::text,'El nuevo proyecto fue presentado al equipo en la sala de reuniones esta mañana.'::text),
(376520,41836,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le nouveau projet ... à l''équipe dans la salle de réunion ce matin.'::text,'a été présenté'::text,'est présenté'::text,'a présenté'::text,'Le nouveau projet a été présenté à l''équipe dans la salle de réunion ce matin.'::text),
(376523,41836,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeni proje bu sabah toplantı odasında ekibe ...'::text,'sunuldu'::text,'sunuluyor'::text,'sundu'::text,'Yeni proje bu sabah toplantı odasında ekibe sunuldu.'::text),
(376524,41836,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az új projektet ma reggel ... a csapatnak a tárgyalóban.'::text,'mutatták be'::text,'mutatják be'::text,'mutatta be'::text,'Az új projektet ma reggel mutatták be a csapatnak a tárgyalóban.'::text),
(376527,41837,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... sie ihren Kollegen am Whiteboard ihre Arbeit.'::text,'präsentierte'::text,'wurde präsentiert'::text,'präsentierend'::text,'Gestern präsentierte sie ihren Kollegen am Whiteboard ihre Arbeit.'::text),
(376531,41837,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора вона ... свою роботу колегам біля дошки.'::text,'презентувала'::text,'була презентована'::text,'презентуючи'::text,'Учора вона презентувала свою роботу колегам біля дошки.'::text),
(376530,41837,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer ... su trabajo a sus colegas en la pizarra.'::text,'presentó'::text,'fue presentada'::text,'presentando'::text,'Ayer presentó su trabajo a sus colegas en la pizarra.'::text),
(376529,41837,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, elle ... son travail à ses collègues au tableau.'::text,'a présenté'::text,'a été présentée'::text,'présentant'::text,'Hier, elle a présenté son travail à ses collègues au tableau.'::text),
(376532,41837,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün beyaz tahtada meslektaşlarına işini ...'::text,'sundu'::text,'sunuldu'::text,'sunarak'::text,'Dün beyaz tahtada meslektaşlarına işini sundu.'::text),
(376533,41837,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap ... a munkáját a kollégáinak a táblánál.'::text,'bemutatta'::text,'be lett mutatva'::text,'bemutatva'::text,'Tegnap bemutatta a munkáját a kollégáinak a táblánál.'::text),
(376536,41838,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand hört zu, also ... sie genervt sein, während sie präsentiert.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Niemand hört zu, also muss sie genervt sein, während sie präsentiert.'::text),
(376540,41838,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто не слухає, тож вона ... бути роздратованою, поки презентує.'::text,'мусить'::text,'не може'::text,'не має права'::text,'Ніхто не слухає, тож вона мусить бути роздратованою, поки презентує.'::text),
(376539,41838,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadie escucha, así que ... sentirse molesta mientras presenta.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Nadie escucha, así que debe de sentirse molesta mientras presenta.'::text),
(376538,41838,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne n''écoute, donc elle ... se sentir agacée pendant qu''elle présente.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Personne n''écoute, donc elle doit se sentir agacée pendant qu''elle présente.'::text),
(376541,41838,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse dinlemiyor, yani sunum yaparken sinirli ...'::text,'hissediyor olmalı'::text,'hissediyor olamaz'::text,'hissetmemeli'::text,'Kimse dinlemiyor, yani sunum yaparken sinirli hissediyor olmalı.'::text),
(376542,41838,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki sem figyel, szóval ... idegesnek éreznie magát prezentálás közben.'::text,'kell'::text,'nem lehet'::text,'nem szabad'::text,'Senki sem figyel, szóval kell idegesnek éreznie magát prezentálás közben.'::text),
(368589,40955,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... gerade diesen chaotischen Klamottenhaufen, als du das blaue Hemd gefunden hast, Respekt.'::text,'sortiertest'::text,'sortiertest'::text,'hast sortiert'::text,'Ehrlich, du sortiertest gerade diesen chaotischen Klamottenhaufen, als du das blaue Hemd gefunden hast, Respekt.'::text),
(368593,40955,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... ту безладну купу одягу, коли знайшов синю сорочку, респект.'::text,'розбирав'::text,'розібрав'::text,'розібрав'::text,'Чесно, ти розбирав ту безладну купу одягу, коли знайшов синю сорочку, респект.'::text),
(368592,40955,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... ese montón de ropa desordenado cuando encontraste la camisa azul, respeto.'::text,'estabas ordenando'::text,'ordenaste'::text,'has ordenado'::text,'La verdad, estabas ordenando ese montón de ropa desordenado cuando encontraste la camisa azul, respeto.'::text),
(368591,40955,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... ce tas de vêtements en bazar quand tu as trouvé la chemise bleue, respect.'::text,'triais'::text,'as trié'::text,'as trié'::text,'Franchement, tu triais ce tas de vêtements en bazar quand tu as trouvé la chemise bleue, respect.'::text),
(368594,40955,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, mavi gömleği bulduğunda o dağınık kıyafet yığınını ..., helal.'::text,'ayıklıyordun'::text,'ayıkladın'::text,'ayıkladın'::text,'Açıkçası, mavi gömleği bulduğunda o dağınık kıyafet yığınını ayıklıyordun, helal.'::text),
(368595,40955,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, épp ... azt a rendetlen ruhakupacot, amikor megtaláltad a kék inget, respekt.'::text,'válogattad'::text,'átválogattad'::text,'átválogattad'::text,'Őszintén, épp válogattad azt a rendetlen ruhakupacot, amikor megtaláltad a kék inget, respekt.'::text),
(368598,40956,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt ... du schon den ganzen Morgen Hemden aus diesem chaotischen Haufen, und man sieht''s.'::text,'bügelst'::text,'bügelst'::text,'bügelst'::text,'Ehrlich gesagt bügelst du schon den ganzen Morgen Hemden aus diesem chaotischen Haufen, und man sieht''s.'::text),
(368602,40956,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ... сорочки з тієї безладної купи весь ранок, і це видно.'::text,'прасуєш'::text,'прасуєш'::text,'прасуєш'::text,'Не буду брехати, ти прасуєш сорочки з тієї безладної купи весь ранок, і це видно.'::text),
(368601,40956,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ... camisas de ese montón desordenado toda la mañana, y se nota.'::text,'has estado planchando'::text,'estás planchando'::text,'planchas'::text,'No te voy a mentir, has estado planchando camisas de ese montón desordenado toda la mañana, y se nota.'::text),
(368600,40956,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... des chemises de ce tas en bazar depuis ce matin, et ça se voit.'::text,'repasses'::text,'repasses'::text,'repasses'::text,'Je vais pas mentir, tu repasses des chemises de ce tas en bazar depuis ce matin, et ça se voit.'::text),
(368603,40956,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bütün sabah o dağınık yığındaki gömlekleri ... ve belli oluyor.'::text,'ütülüyorsun'::text,'ütülüyorsun'::text,'ütülersin'::text,'Yalan yok, bütün sabah o dağınık yığındaki gömlekleri ütülüyorsun ve belli oluyor.'::text),
(368604,40956,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, egész délelőtt ... az ingeket abból a rendetlen kupacból, és látszik is.'::text,'vasalod'::text,'vasalod'::text,'vasalod'::text,'Nem fogok hazudni, egész délelőtt vasalod az ingeket abból a rendetlen kupacból, és látszik is.'::text),
