(364200,40467,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el vendedor le da un helado aún más grande, su risa ... más fuerte.'::text,'se volverá'::text,'se volvería'::text,'se volvió'::text,'Si el vendedor le da un helado aún más grande, su risa se volverá más fuerte.'::text),
(364199,40467,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vendeur lui donne une glace encore plus grosse, son rire ... plus fort.'::text,'deviendra'::text,'deviendrait'::text,'est devenu'::text,'Si le vendeur lui donne une glace encore plus grosse, son rire deviendra plus fort.'::text),
(364202,40467,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Satıcı ona daha da büyük bir dondurma verirse kahkahası daha da ...'::text,'yükselecek'::text,'yükselirdi'::text,'yükseldi'::text,'Satıcı ona daha da büyük bir dondurma verirse kahkahası daha da yükselecek.'::text),
(364203,40467,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az árus még nagyobb fagyit ad neki, a nevetése még hangosabb ...'::text,'lesz'::text,'lenne'::text,'lett'::text,'Ha az árus még nagyobb fagyit ad neki, a nevetése még hangosabb lesz.'::text),
(364206,40468,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn ich dein Lachen hätte, ... ich auch jeden Trip filmen.'::text,'würde'::text,'werde'::text,'filme'::text,'Ehrlich, wenn ich dein Lachen hätte, würde ich auch jeden Trip filmen.'::text),
(364210,40468,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби в мене був твій сміх, я теж ... кожну поїздку на камеру.'::text,'знімав би'::text,'зніматиму'::text,'знімаю'::text,'Чесно, якби в мене був твій сміх, я теж знімав би кожну поїздку на камеру.'::text),
(364209,40468,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, si tuviera tu risa, yo también ... cada viaje.'::text,'grabaría'::text,'grabaré'::text,'grabo'::text,'La verdad, si tuviera tu risa, yo también grabaría cada viaje.'::text),
(364208,40468,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si j''avais ton rire, moi aussi je ... chaque voyage.'::text,'filmerais'::text,'filmerai'::text,'filme'::text,'Franchement, si j''avais ton rire, moi aussi je filmerais chaque voyage.'::text),
(364211,40468,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, senin kahkahan bende olsa ben de her geziyi kameraya ...'::text,'çekerdim'::text,'çekeceğim'::text,'çekiyorum'::text,'Açıkçası, senin kahkahan bende olsa ben de her geziyi kameraya çekerdim.'::text),
(364212,40468,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha nekem lenne a nevetésed, én is minden utat ... kamerára.'::text,'felvennék'::text,'fel fogok venni'::text,'felveszek'::text,'Őszintén, ha nekem lenne a nevetésed, én is minden utat felvennék kamerára.'::text),
(364215,40469,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein lautes Lachen ... am Schiefen Turm von Pisa mit seinem Handy aufgenommen.'::text,'wurde'::text,'nahm'::text,'nimmt'::text,'Sein lautes Lachen wurde am Schiefen Turm von Pisa mit seinem Handy aufgenommen.'::text),
(364219,40469,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його гучний сміх ... на телефон біля Пізанської вежі.'::text,'був записаний'::text,'записав'::text,'записує'::text,'Його гучний сміх був записаний на телефон біля Пізанської вежі.'::text),
(364218,40469,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su risa fuerte ... con su móvil en la Torre de Pisa.'::text,'fue grabada'::text,'grabó'::text,'está grabando'::text,'Su risa fuerte fue grabada con su móvil en la Torre de Pisa.'::text),
(364217,40469,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son grand rire ... sur son téléphone devant la tour de Pise.'::text,'a été enregistré'::text,'a enregistré'::text,'enregistre'::text,'Son grand rire a été enregistré sur son téléphone devant la tour de Pise.'::text),
(364220,40469,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüksek kahkahası Pisa Kulesi''nde telefonuna ...'::text,'kaydedildi'::text,'kaydetti'::text,'kaydediyor'::text,'Yüksek kahkahası Pisa Kulesi''nde telefonuna kaydedildi.'::text),
(364221,40469,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hangos nevetését a pisai ferde toronynál ... a telefonjára.'::text,'vették fel'::text,'felvette'::text,'veszi fel'::text,'A hangos nevetését a pisai ferde toronynál vették fel a telefonjára.'::text),
(364224,40470,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein leises kleines Lachen ... jede Taube in Pisa. Wirklich dezent.'::text,'verscheuchte'::text,'wurde verscheucht'::text,'verscheuchend'::text,'Sein leises kleines Lachen verscheuchte jede Taube in Pisa. Wirklich dezent.'::text),
(364228,40470,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його тихенький сміх ... кожного голуба в Пізі. Справді непомітно.'::text,'налякав'::text,'був наляканий'::text,'лякаючи'::text,'Його тихенький сміх налякав кожного голуба в Пізі. Справді непомітно.'::text),
(364227,40470,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su risita tranquila ... a todas las palomas de Pisa. Muy sutil, de verdad.'::text,'asustó'::text,'fue asustada'::text,'asustando'::text,'Su risita tranquila asustó a todas las palomas de Pisa. Muy sutil, de verdad.'::text),
(364226,40470,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son petit rire discret ... tous les pigeons de Pise. Vraiment subtil.'::text,'a effrayé'::text,'a été effrayé'::text,'effrayant'::text,'Son petit rire discret a effrayé tous les pigeons de Pise. Vraiment subtil.'::text),
(364229,40470,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun sessiz minik kahkahası Pisa''daki bütün güvercinleri ..., gerçekten çok incelikli.'::text,'korkuttu'::text,'korkutuldu'::text,'korkutarak'::text,'Onun sessiz minik kahkahası Pisa''daki bütün güvercinleri korkuttu, gerçekten çok incelikli.'::text),
(364230,40470,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A halk kis nevetése ... Pisa összes galambját. Igazán visszafogott.'::text,'elijesztette'::text,'el lett ijesztve'::text,'elijesztve'::text,'A halk kis nevetése elijesztette Pisa összes galambját. Igazán visszafogott.'::text),
(364233,40471,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit so einem lauten Lachen ... er ein kleines bisschen glücklich über das Eis sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Mit so einem lauten Lachen muss er ein kleines bisschen glücklich über das Eis sein.'::text),
(364237,40471,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З таким гучним сміхом він ... бути трішки задоволеним морозивом.'::text,'мусить'::text,'не може'::text,'не має права'::text,'З таким гучним сміхом він мусить бути трішки задоволеним морозивом.'::text),
(364236,40471,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con una risa tan fuerte, ... estar un poquito contento con el helado.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Con una risa tan fuerte, debe de estar un poquito contento con el helado.'::text),
(364235,40471,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec un rire aussi fort, il ... être un petit peu content de sa glace.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Avec un rire aussi fort, il doit être un petit peu content de sa glace.'::text),
(364238,40471,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar yüksek bir kahkahayla dondurmadan azıcık memnun ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'O kadar yüksek bir kahkahayla dondurmadan azıcık memnun olmalı.'::text),
(364239,40471,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ilyen hangos nevetéssel ... egy kicsit örülnie a fagyinak.'::text,'kell'::text,'nem lehet'::text,'nem szabad'::text,'Ilyen hangos nevetéssel kell egy kicsit örülnie a fagyinak.'::text),
(364242,40472,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Verkäufer, ... ihm das Eis gab, hörte sein Lachen.'::text,'der'::text,'das'::text,'dessen'::text,'Der Verkäufer, der ihm das Eis gab, hörte sein Lachen.'::text),
(364246,40472,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Продавець, ... дав йому морозиво, почув його сміх.'::text,'який'::text,'що'::text,'чий'::text,'Продавець, який дав йому морозиво, почув його сміх.'::text),
(364245,40472,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vendedor ... le dio el helado oyó su risa.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El vendedor que le dio el helado oyó su risa.'::text),
(364244,40472,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vendeur ... lui a donné la glace a entendu son rire.'::text,'qui'::text,'lequel'::text,'dont'::text,'Le vendeur qui lui a donné la glace a entendu son rire.'::text),
(364247,40472,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Satıcı, ... ona dondurmayı verdi, kahkahasını duydu.'::text,'ki'::text,'ki'::text,'ki onun'::text,'Satıcı, ki ona dondurmayı verdi, kahkahasını duydu.'::text),
(364248,40472,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az árus, ... a fagyit adta neki, hallotta a nevetését.'::text,'aki'::text,'amely'::text,'akinek'::text,'Az árus, aki a fagyit adta neki, hallotta a nevetését.'::text),
(364251,40473,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, dass sein Lachen in Venedig lauter als in Pisa ...'::text,'gewesen sei'::text,'gewesen ist'::text,'ist'::text,'Er sagte, dass sein Lachen in Venedig lauter als in Pisa gewesen sei.'::text),
(364255,40473,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що його сміх у Венеції ... гучнішим, ніж у Пізі.'::text,'був'::text,'був'::text,'є'::text,'Він сказав, що його сміх у Венеції був гучнішим, ніж у Пізі.'::text),
(364254,40473,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que su risa ... más fuerte en Venecia que en Pisa.'::text,'había sido'::text,'ha sido'::text,'está siendo'::text,'Dijo que su risa había sido más fuerte en Venecia que en Pisa.'::text),
(364253,40473,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que son rire ... plus fort à Venise qu''à Pise.'::text,'avait été'::text,'a été'::text,'est'::text,'Il a dit que son rire avait été plus fort à Venise qu''à Pise.'::text),
(364256,40473,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kahkahasının Venedik''te Pisa''dakinden daha yüksek ... söyledi.'::text,'olduğunu'::text,'olduğunu'::text,'olmakta olduğunu'::text,'Kahkahasının Venedik''te Pisa''dakinden daha yüksek olduğunu söyledi.'::text),
(364257,40473,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a nevetése Velencében hangosabb ..., mint Pisában.'::text,'volt'::text,'volt'::text,NULL::text,'Azt mondta, hogy a nevetése Velencében hangosabb volt, mint Pisában.'::text),
(399027,44337,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er den Tunnel aus Toren ..., blieb seine große Kamera um seinen Hals hängen. Makellos.'::text,'filmte'::text,'filmte'::text,'gefilmt hat'::text,'Während er den Tunnel aus Toren filmte, blieb seine große Kamera um seinen Hals hängen. Makellos.'::text),
(399031,44337,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... тунель із воріт, його великий фотоапарат так і висів на шиї. Бездоганно.'::text,'знімав'::text,'зняв'::text,'зняв'::text,'Поки він знімав тунель із воріт, його великий фотоапарат так і висів на шиї. Бездоганно.'::text),
(399030,44337,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... el túnel de puertas, su gran cámara siguió colgada del cuello. Impecable.'::text,'grababa'::text,'grabó'::text,'ha grabado'::text,'Mientras grababa el túnel de puertas, su gran cámara siguió colgada del cuello. Impecable.'::text),
(399029,44337,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... le tunnel de portes, son gros appareil photo est resté autour de son cou. Impeccable.'::text,'filmait'::text,'a filmé'::text,'a filmé'::text,'Pendant qu''il filmait le tunnel de portes, son gros appareil photo est resté autour de son cou. Impeccable.'::text),
(399032,44337,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapı tünelini ... büyük fotoğraf makinesi boynunda asılı kaldı. Kusursuz.'::text,'çekerken'::text,'çekti'::text,'çekti'::text,'Kapı tünelini çekerken büyük fotoğraf makinesi boynunda asılı kaldı. Kusursuz.'::text),
(399033,44337,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ... a kapukból álló alagutat, a nagy fényképezőgépe a nyakában maradt. Hibátlan.'::text,'filmezte'::text,'lefilmezte'::text,'lefilmezte'::text,'Miközben filmezte a kapukból álló alagutat, a nagy fényképezőgépe a nyakában maradt. Hibátlan.'::text),
(399045,44339,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... durch den Tunnel, erreichte das Licht und aß dann das beste Ramen aller Zeiten! Unglaublich!'::text,'ging'::text,'ging gerade'::text,'ist gegangen'::text,'Er ging durch den Tunnel, erreichte das Licht und aß dann das beste Ramen aller Zeiten! Unglaublich!'::text),
(399049,44339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... тунелем, дійшов до світла, а потім з''їв найкращий рамен у світі! Неймовірно!'::text,'пройшов'::text,'ішов'::text,'пройшов'::text,'Він пройшов тунелем, дійшов до світла, а потім з''їв найкращий рамен у світі! Неймовірно!'::text),
(399048,44339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... por el túnel, llegó a la luz y luego se comió el mejor ramen de su vida! ¡Increíble!'::text,'Caminó'::text,'Estaba caminando'::text,'Ha caminado'::text,'¡Caminó por el túnel, llegó a la luz y luego se comió el mejor ramen de su vida! ¡Increíble!'::text),
(399047,44339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le tunnel, a atteint la lumière, puis a mangé les meilleurs ramen de sa vie ! Incroyable !'::text,'a traversé'::text,'traversait'::text,'a traversé'::text,'Il a traversé le tunnel, a atteint la lumière, puis a mangé les meilleurs ramen de sa vie ! Incroyable !'::text),
(399050,44339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tünelden ..., ışığa ulaştı, sonra gelmiş geçmiş en iyi rameni yedi! İnanılmaz!'::text,'geçti'::text,'geçiyordu'::text,'geçmiş'::text,'Tünelden geçti, ışığa ulaştı, sonra gelmiş geçmiş en iyi rameni yedi! İnanılmaz!'::text),
(399051,44339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... az alagúton, elért a fényig, aztán megette minden idők legjobb ramenjét! Hihetetlen!'::text,'Átsétált'::text,'Sétált'::text,'Átsétált'::text,'Átsétált az alagúton, elért a fényig, aztán megette minden idők legjobb ramenjét! Hihetetlen!'::text),
(399054,44340,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... heute durch fünf Tunnel aus Toren gelaufen, und er ist komplett fertig!'::text,'ist'::text,'ist'::text,'lief'::text,'Er ist heute durch fünf Tunnel aus Toren gelaufen, und er ist komplett fertig!'::text),
(399058,44340,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні він ... п''ять тунелів із воріт, і він геть без сил!'::text,'пройшов'::text,'ходить'::text,'пройшов'::text,'Сьогодні він пройшов п''ять тунелів із воріт, і він геть без сил!'::text),
(399057,44340,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Hoy ... por cinco túneles de puertas y está completamente muerto!'::text,'ha caminado'::text,'ha estado caminando'::text,'caminó'::text,'¡Hoy ha caminado por cinco túneles de puertas y está completamente muerto!'::text),
(399056,44340,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... cinq tunnels de portes aujourd''hui, et il est complètement mort !'::text,'a traversé'::text,'traverse'::text,'a traversé'::text,'Il a traversé cinq tunnels de portes aujourd''hui, et il est complètement mort !'::text),
(399059,44340,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün beş kapı tünelinden ... ve tamamen bitmiş durumda!'::text,'geçti'::text,'geçiyor'::text,'geçti'::text,'Bugün beş kapı tünelinden geçti ve tamamen bitmiş durumda!'::text),
(399060,44340,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma öt kapualagúton ... át, és teljesen kész van!'::text,'sétált'::text,'sétál'::text,'sétált'::text,'Ma öt kapualagúton sétált át, és teljesen kész van!'::text),
(399063,44341,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, er hat mir erzählt, er ... den ganzen Tunnel gefilmt, bevor er überhaupt an Ramen dachte.'::text,'hatte'::text,'hat'::text,'filmt'::text,'Warte, er hat mir erzählt, er hatte den ganzen Tunnel gefilmt, bevor er überhaupt an Ramen dachte.'::text),
(399067,44341,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чекай, він сказав мені, що ... весь тунель, ще до того, як узагалі подумав про рамен.'::text,'зняв'::text,'зняв'::text,'знімає'::text,'Чекай, він сказав мені, що зняв весь тунель, ще до того, як узагалі подумав про рамен.'::text),
(399066,44341,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, me dijo que ... todo el túnel antes de siquiera pensar en ramen.'::text,'había grabado'::text,'ha grabado'::text,'graba'::text,'Espera, me dijo que había grabado todo el túnel antes de siquiera pensar en ramen.'::text),
(399065,44341,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, il m''a dit qu''il ... tout le tunnel avant même de penser aux ramen.'::text,'avait filmé'::text,'a filmé'::text,'filme'::text,'Attends, il m''a dit qu''il avait filmé tout le tunnel avant même de penser aux ramen.'::text),
(399068,44341,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, bana, daha ramen aklına bile gelmeden bütün tüneli ... söyledi.'::text,'çektiğini'::text,'çektiğini'::text,'çektiğini'::text,'Dur, bana, daha ramen aklına bile gelmeden bütün tüneli çektiğini söyledi.'::text),
(399069,44341,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, azt mondta, hogy ... az egész alagutat, mielőtt egyáltalán a ramenre gondolt.'::text,'lefilmezte'::text,'lefilmezte'::text,'filmezi'::text,'Várj, azt mondta, hogy lefilmezte az egész alagutat, mielőtt egyáltalán a ramenre gondolt.'::text),
(399072,44342,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er bis zum Ende des Tunnels geht, ... er die helle Öffnung.'::text,'erreicht'::text,'würde erreichen'::text,'erreichte'::text,'Wenn er bis zum Ende des Tunnels geht, erreicht er die helle Öffnung.'::text),
(399076,44342,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він дійде до кінця тунелю, він ... до яскравого виходу.'::text,'дійде'::text,'дійшов би'::text,'дійшов'::text,'Якщо він дійде до кінця тунелю, він дійде до яскравого виходу.'::text),
(399075,44342,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si camina hasta el final del túnel, ... a la abertura luminosa.'::text,'llegará'::text,'llegaría'::text,'llegó'::text,'Si camina hasta el final del túnel, llegará a la abertura luminosa.'::text),
(399074,44342,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il marche jusqu''au bout du tunnel, il ... l''ouverture lumineuse.'::text,'atteindra'::text,'atteindrait'::text,'a atteint'::text,'S''il marche jusqu''au bout du tunnel, il atteindra l''ouverture lumineuse.'::text),
(399077,44342,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tünelin sonuna kadar yürürse aydınlık çıkışa ...'::text,'ulaşacak'::text,'ulaşırdı'::text,'ulaştı'::text,'Tünelin sonuna kadar yürürse aydınlık çıkışa ulaşacak.'::text),
(399078,44342,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha elsétál az alagút végéig, ... a világos kijárathoz.'::text,'eljut'::text,'eljutna'::text,'eljutott'::text,'Ha elsétál az alagút végéig, eljut a világos kijárathoz.'::text),
(399081,44343,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn ich durch so einen Tunnel ..., würde ich auch vloggen, kein Witz.'::text,'ginge'::text,'gehe'::text,'gehen würde'::text,'Digga, wenn ich durch so einen Tunnel ginge, würde ich auch vloggen, kein Witz.'::text),
(399085,44343,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, якби я ... таким тунелем, я б теж вів влог, без брехні.'::text,'ішов'::text,'іду'::text,'ішов би'::text,'Брате, якби я ішов таким тунелем, я б теж вів влог, без брехні.'::text),
(399084,44343,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si yo ... por un túnel así, también estaría haciendo vlogs, en serio.'::text,'caminara'::text,'camino'::text,'caminaría'::text,'Bro, si yo caminara por un túnel así, también estaría haciendo vlogs, en serio.'::text),
(399083,44343,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si je ... dans un tunnel comme ça, je ferais des vlogs aussi, sans mentir.'::text,'marchais'::text,'marche'::text,'marcherais'::text,'Frère, si je marchais dans un tunnel comme ça, je ferais des vlogs aussi, sans mentir.'::text),
(399086,44343,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, öyle bir tünelden ... ben de vlog çekiyor olurdum, yalan yok.'::text,'geçsem'::text,'geçiyorum'::text,'geçerdim'::text,'Kanka, öyle bir tünelden geçsem ben de vlog çekiyor olurdum, yalan yok.'::text),
(399087,44343,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha én egy ilyen alagúton ... át, én is vlogolnék, komolyan.'::text,'sétálnék'::text,'sétálok'::text,'sétálnék'::text,'Tesó, ha én egy ilyen alagúton sétálnék át, én is vlogolnék, komolyan.'::text),
(399099,44345,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sich die Kamera durch einen langen Tunnel aus orangefarbenen Toren nach vorne.'::text,'bewegt'::text,'bewegt'::text,'hat bewegt'::text,'Gerade bewegt sich die Kamera durch einen langen Tunnel aus orangefarbenen Toren nach vorne.'::text),
(399103,44345,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз камера ... вперед довгим тунелем з помаранчевих воріт.'::text,'рухається'::text,'рухається'::text,'рушила'::text,'Прямо зараз камера рухається вперед довгим тунелем з помаранчевих воріт.'::text),
(399102,44345,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, la cámara ... hacia delante por un largo túnel de puertas naranjas.'::text,'está avanzando'::text,'avanza'::text,'ha avanzado'::text,'Ahora mismo, la cámara está avanzando hacia delante por un largo túnel de puertas naranjas.'::text),
(399101,44345,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la caméra ... dans un long tunnel de portes orange.'::text,'avance'::text,'avance'::text,'a avancé'::text,'En ce moment, la caméra avance dans un long tunnel de portes orange.'::text),
(399104,44345,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda kamera turuncu kapılardan oluşan uzun bir tünelde ...'::text,'ilerliyor'::text,'ilerler'::text,'ilerledi'::text,'Şu anda kamera turuncu kapılardan oluşan uzun bir tünelde ilerliyor.'::text),
(399105,44345,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a kamera ... előre egy hosszú, narancssárga kapukból álló alagútban.'::text,'halad'::text,'halad'::text,'haladt'::text,'Épp most a kamera halad előre egy hosszú, narancssárga kapukból álló alagútban.'::text),
(399108,44346,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er sich zum Ramen hinsetzte, ... er schon durch den Tunnel aus Toren gelaufen.'::text,'war'::text,'lief'::text,'ist'::text,'Als er sich zum Ramen hinsetzte, war er schon durch den Tunnel aus Toren gelaufen.'::text),
(399112,44346,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він сів їсти рамен, він уже ... тунелем із воріт.'::text,'пройшов'::text,'пройшов'::text,'пройшов'::text,'Коли він сів їсти рамен, він уже пройшов тунелем із воріт.'::text),
(399111,44346,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se sentó a comer ramen, ya ... por el túnel de puertas.'::text,'había caminado'::text,'caminó'::text,'ha caminado'::text,'Para cuando se sentó a comer ramen, ya había caminado por el túnel de puertas.'::text),
(399110,44346,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il s''est assis pour manger ses ramen, il ... le tunnel de portes.'::text,'avait traversé'::text,'a traversé'::text,'a traversé'::text,'Quand il s''est assis pour manger ses ramen, il avait traversé le tunnel de portes.'::text),
(399113,44346,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ramen için oturduğunda kapı tünelinden çoktan ...'::text,'geçmişti'::text,'geçti'::text,'geçti'::text,'Ramen için oturduğunda kapı tünelinden çoktan geçmişti.'::text),
(399114,44346,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire leült ramenezni, már ... a kapualagúton.'::text,'átsétált'::text,'átsétált'::text,'átsétált'::text,'Mire leült ramenezni, már átsétált a kapualagúton.'::text),
(399117,44347,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... er sein Tunnelvideo an alle geschickt haben, die er kennt. Eindeutig ein bescheidener Reisender.'::text,'wird'::text,'wird'::text,'schickt'::text,'Bis heute Abend wird er sein Tunnelvideo an alle geschickt haben, die er kennt. Eindeutig ein bescheidener Reisender.'::text),
(399121,44347,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора він ... своє відео з тунелю всім знайомим. Явно скромний мандрівник.'::text,'надішле'::text,'надішле'::text,'надсилає'::text,'До вечора він надішле своє відео з тунелю всім знайомим. Явно скромний мандрівник.'::text),
(399120,44347,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche ... su vídeo del túnel a todos sus conocidos. Claramente un viajero humilde.'::text,'habrá enviado'::text,'enviará'::text,'envía'::text,'Para esta noche habrá enviado su vídeo del túnel a todos sus conocidos. Claramente un viajero humilde.'::text),
(399119,44347,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, il ... sa vidéo du tunnel à tous ceux qu''il connaît. Clairement un voyageur modeste.'::text,'aura envoyé'::text,'enverra'::text,'envoie'::text,'D''ici ce soir, il aura envoyé sa vidéo du tunnel à tous ceux qu''il connaît. Clairement un voyageur modeste.'::text),
(399122,44347,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar tünel videosunu tanıdığı herkese ..., belli ki mütevazı bir gezgin.'::text,'göndermiş olacak'::text,'gönderecek'::text,'gönderiyor'::text,'Bu akşama kadar tünel videosunu tanıdığı herkese göndermiş olacak, belli ki mütevazı bir gezgin.'::text),
(399123,44347,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére már ... az alagutas videóját mindenkinek, akit ismer. Egyértelműen szerény utazó.'::text,'elküldi'::text,'el fogja küldeni'::text,'küldi'::text,'Estére már elküldi az alagutas videóját mindenkinek, akit ismer. Egyértelműen szerény utazó.'::text),
(340977,37887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Ende des Monats ... er in dieser Trainingshalle gegen zehn Gegner gekämpft haben.'::text,'wird'::text,'wird'::text,'kämpft'::text,'Bis Ende des Monats wird er in dieser Trainingshalle gegen zehn Gegner gekämpft haben.'::text),
(340981,37887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця місяця він ... з десятьма суперниками в цьому тренувальному залі.'::text,'проведе бої'::text,'битиметься'::text,'б''ється'::text,'До кінця місяця він проведе бої з десятьма суперниками в цьому тренувальному залі.'::text),
(340980,37887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para fin de mes, ... contra diez rivales en esta sala de entrenamiento.'::text,'habrá combatido'::text,'combatirá'::text,'combate'::text,'Para fin de mes, habrá combatido contra diez rivales en esta sala de entrenamiento.'::text),
(340979,37887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du mois, il ... contre dix adversaires dans cette salle d''entraînement.'::text,'aura combattu'::text,'combattra'::text,'combat'::text,'D''ici la fin du mois, il aura combattu contre dix adversaires dans cette salle d''entraînement.'::text),
(340982,37887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ay sonuna kadar bu antrenman salonunda on rakiple ...'::text,'dövüşmüş olacak'::text,'dövüşecek'::text,'dövüşüyor'::text,'Ay sonuna kadar bu antrenman salonunda on rakiple dövüşmüş olacak.'::text),
(340983,37887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hónap végére ebben az edzőteremben tíz ellenféllel ...'::text,'megküzd'::text,'fog küzdeni'::text,'küzd'::text,'A hónap végére ebben az edzőteremben tíz ellenféllel megküzd.'::text),
(349554,38840,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In der Abenddämmerung, während die Mitarbeiter in den See ..., begann das Meeting um 20 Uhr ohne sie.'::text,'sprangen'::text,'sprangen'::text,'gesprungen sind'::text,'In der Abenddämmerung, während die Mitarbeiter in den See sprangen, begann das Meeting um 20 Uhr ohne sie.'::text),
(349558,38840,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У сутінках, поки працівники ... в озеро, нарада о 20:00 почалася без них.'::text,'стрибали'::text,'стрибнули'::text,'стрибнули'::text,'У сутінках, поки працівники стрибали в озеро, нарада о 20:00 почалася без них.'::text),
(349557,38840,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al anochecer, mientras el personal ... al lago, la reunión de las 20:00 empezó sin ellos.'::text,'se lanzaba'::text,'se lanzó'::text,'se ha lanzado'::text,'Al anochecer, mientras el personal se lanzaba al lago, la reunión de las 20:00 empezó sin ellos.'::text),
(349556,38840,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au crépuscule, pendant que l''équipe ... dans le lac, la réunion de 20 h a commencé sans elle.'::text,'sautait'::text,'a sauté'::text,'a sauté'::text,'Au crépuscule, pendant que l''équipe sautait dans le lac, la réunion de 20 h a commencé sans elle.'::text),
(349559,38840,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alacakaranlıkta çalışanlar göle ... saat 20.00 toplantısı onlarsız başladı.'::text,'atlarken'::text,'atladı'::text,'atladılar'::text,'Alacakaranlıkta çalışanlar göle atlarken saat 20.00 toplantısı onlarsız başladı.'::text),
(349560,38840,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alkonyatkor, miközben a munkatársak ... a tóba, a 20 órás megbeszélés nélkülük kezdődött.'::text,'ugráltak'::text,'beugrottak'::text,'beugrottak'::text,'Alkonyatkor, miközben a munkatársak ugráltak a tóba, a 20 órás megbeszélés nélkülük kezdődött.'::text),
(349563,38841,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit der Dämmerung in den See, deshalb sind sie nass.'::text,'springen'::text,'springen'::text,'springen'::text,'Sie springen seit der Dämmerung in den See, deshalb sind sie nass.'::text),
(349567,38841,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... в озеро від сутінків, тому вони мокрі.'::text,'стрибають'::text,'стрибають'::text,'стрибають'::text,'Вони стрибають в озеро від сутінків, тому вони мокрі.'::text),
(349566,38841,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... al lago desde el anochecer, así que están mojados.'::text,'Han estado saltando'::text,'Están saltando'::text,'Saltan'::text,'Han estado saltando al lago desde el anochecer, así que están mojados.'::text),
(349565,38841,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... dans le lac depuis le crépuscule, donc ils sont mouillés.'::text,'sautent'::text,'sautent'::text,'sautent'::text,'Ils sautent dans le lac depuis le crépuscule, donc ils sont mouillés.'::text),
(349568,38841,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alacakaranlıktan beri göle ..., o yüzden ıslaklar.'::text,'atlıyorlar'::text,'atlıyorlar'::text,'atlarlar'::text,'Alacakaranlıktan beri göle atlıyorlar, o yüzden ıslaklar.'::text),
(349569,38841,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alkonyat óta ... a tóba, ezért vizesek.'::text,'ugrálnak'::text,'ugrálnak'::text,'ugrálnak'::text,'Alkonyat óta ugrálnak a tóba, ezért vizesek.'::text),
(349572,38842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In der Dämmerung ... das Licht gerade, als der erste Schwimmer auf dem Steg beobachtet wurde.'::text,'verblasste'::text,'verblasste'::text,'ist verblasst'::text,'In der Dämmerung verblasste das Licht gerade, als der erste Schwimmer auf dem Steg beobachtet wurde.'::text),
(349576,38842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У сутінках світло ..., коли на помості помітили першого плавця.'::text,'згасало'::text,'згасло'::text,'згасло'::text,'У сутінках світло згасало, коли на помості помітили першого плавця.'::text),
(349575,38842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al anochecer, la luz ... cuando se observó al primer nadador en el embarcadero.'::text,'se estaba apagando'::text,'se apagó'::text,'se ha apagado'::text,'Al anochecer, la luz se estaba apagando cuando se observó al primer nadador en el embarcadero.'::text),
(349574,38842,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au crépuscule, la lumière ... quand le premier nageur a été observé sur le ponton.'::text,'déclinait'::text,'a décliné'::text,'a décliné'::text,'Au crépuscule, la lumière déclinait quand le premier nageur a été observé sur le ponton.'::text),
(349577,38842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alacakaranlıkta iskelede ilk yüzücü gözlemlendiğinde ışık ...'::text,'sönüyordu'::text,'söndü'::text,'söndü'::text,'Alacakaranlıkta iskelede ilk yüzücü gözlemlendiğinde ışık sönüyordu.'::text),
(349578,38842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alkonyatkor a fény épp ..., amikor megfigyelték az első úszót a stégen.'::text,'halványult'::text,'elhalványult'::text,'elhalványult'::text,'Alkonyatkor a fény épp halványult, amikor megfigyelték az első úszót a stégen.'::text),
(349581,38843,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit der Dämmerung ... fünf Leute vom Steg in den See gesprungen.'::text,'sind'::text,'sind'::text,'sprangen'::text,'Seit der Dämmerung sind fünf Leute vom Steg in den See gesprungen.'::text),
(349585,38843,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Від сутінків п''ятеро людей ... з помосту в озеро.'::text,'стрибнули'::text,'стрибають'::text,'стрибнули'::text,'Від сутінків п''ятеро людей стрибнули з помосту в озеро.'::text),
(349584,38843,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desde el anochecer, cinco personas ... del embarcadero al lago.'::text,'han saltado'::text,'han estado saltando'::text,'saltaron'::text,'Desde el anochecer, cinco personas han saltado del embarcadero al lago.'::text),
(349583,38843,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis le crépuscule, cinq personnes ... du ponton dans le lac.'::text,'ont sauté'::text,'sautent'::text,'ont sauté'::text,'Depuis le crépuscule, cinq personnes ont sauté du ponton dans le lac.'::text),
(349586,38843,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alacakaranlıktan beri beş kişi iskeleden göle ...'::text,'atladı'::text,'atlıyor'::text,'atladı'::text,'Alacakaranlıktan beri beş kişi iskeleden göle atladı.'::text),
(349587,38843,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alkonyat óta öt ember ... a stégről a tóba.'::text,'ugrott'::text,'ugrál'::text,'ugrott'::text,'Alkonyat óta öt ember ugrott a stégről a tóba.'::text),
(349599,38845,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie noch viel länger schwimmen, ... die Dämmerung zur Nacht.'::text,'wird'::text,'würde'::text,'wurde'::text,'Wenn sie noch viel länger schwimmen, wird die Dämmerung zur Nacht.'::text),
(349603,38845,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони плаватимуть набагато довше, сутінки ... у ніч.'::text,'перейдуть'::text,'перейшли б'::text,'перейшли'::text,'Якщо вони плаватимуть набагато довше, сутінки перейдуть у ніч.'::text),
(349602,38845,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si nadan mucho más, el anochecer ... en noche.'::text,'se convertirá'::text,'se convertiría'::text,'se convirtió'::text,'Si nadan mucho más, el anochecer se convertirá en noche.'::text),
(349601,38845,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils nagent encore longtemps, le crépuscule ... la nuit.'::text,'deviendra'::text,'deviendrait'::text,'est devenu'::text,'S''ils nagent encore longtemps, le crépuscule deviendra la nuit.'::text),
(349604,38845,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok daha uzun yüzerlerse alacakaranlık geceye ...'::text,'dönecek'::text,'dönerdi'::text,'döndü'::text,'Çok daha uzun yüzerlerse alacakaranlık geceye dönecek.'::text),
(349605,38845,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még sokkal tovább úsznak, az alkony ... éjszakába.'::text,'át fog fordulni'::text,'átfordulna'::text,'átfordult'::text,'Ha még sokkal tovább úsznak, az alkony át fog fordulni éjszakába.'::text),
(349608,38846,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich in der Dämmerung dein Selbstbewusstsein hätte, ... ich auch von dem Steg springen, ehrlich.'::text,'würde'::text,'werde'::text,'springe'::text,'Wenn ich in der Dämmerung dein Selbstbewusstsein hätte, würde ich auch von dem Steg springen, ehrlich.'::text),
(349612,38846,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в мене в сутінках була твоя впевненість, я теж ... з того помосту, чесно.'::text,'стрибнув би'::text,'стрибну'::text,'стрибаю'::text,'Якби в мене в сутінках була твоя впевненість, я теж стрибнув би з того помосту, чесно.'::text),
(349611,38846,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si yo tuviera tu confianza al anochecer, también ... de ese embarcadero, la verdad.'::text,'saltaría'::text,'saltaré'::text,'salto'::text,'Si yo tuviera tu confianza al anochecer, también saltaría de ese embarcadero, la verdad.'::text),
(349610,38846,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si j''avais ta confiance au crépuscule, je ... de ce ponton aussi, franchement.'::text,'sauterais'::text,'sauterai'::text,'saute'::text,'Si j''avais ta confiance au crépuscule, je sauterais de ce ponton aussi, franchement.'::text),
(349613,38846,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alacakaranlıkta sendeki özgüven bende olsa ben de o iskeleden ..., açıkçası.'::text,'atlardım'::text,'atlayacağım'::text,'atlıyorum'::text,'Alacakaranlıkta sendeki özgüven bende olsa ben de o iskeleden atlardım, açıkçası.'::text),
(349614,38846,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha alkonyatkor olyan magabiztos lennék, mint te, én is ... arról a stégről, őszintén.'::text,'leugranék'::text,'le fogok ugrani'::text,'leugrom'::text,'Ha alkonyatkor olyan magabiztos lennék, mint te, én is leugranék arról a stégről, őszintén.'::text),
(349617,38847,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünschen sich eindeutig, die Dämmerung ... nie enden. Keiner hat hier auch nur ein bisschen Spaß.'::text,'würde'::text,'wird'::text,'hätte'::text,'Sie wünschen sich eindeutig, die Dämmerung würde nie enden. Keiner hat hier auch nur ein bisschen Spaß.'::text),
(349621,38847,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони явно хочуть, щоб сутінки ... вічно. Ніхто тут зовсім не розважається.'::text,'тривали'::text,'триватимуть'::text,'тривали'::text,'Вони явно хочуть, щоб сутінки тривали вічно. Ніхто тут зовсім не розважається.'::text),
(349620,38847,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente desean que el anochecer no ... nunca. Nadie se está divirtiendo nada.'::text,'terminara'::text,'terminará'::text,'hubiera terminado'::text,'Claramente desean que el anochecer no terminara nunca. Nadie se está divirtiendo nada.'::text),
(349619,38847,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils voudraient clairement que le crépuscule ne ... jamais. Personne ne s''amuse du tout.'::text,'finisse'::text,'finira'::text,'ait fini'::text,'Ils voudraient clairement que le crépuscule ne finisse jamais. Personne ne s''amuse du tout.'::text),
(349622,38847,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki alacakaranlığın hiç ... istiyorlar. Kimse hiç eğlenmiyor.'::text,'bitmemesini'::text,'bitmeyeceğini'::text,'bitmemiş olmasını'::text,'Belli ki alacakaranlığın hiç bitmemesini istiyorlar. Kimse hiç eğlenmiyor.'::text),
(349623,38847,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen azt kívánják, bárcsak soha ne ... vége az alkonynak. Senki sem szórakozik egyáltalán.'::text,'lenne'::text,'lesz'::text,'lett volna'::text,'Egyértelműen azt kívánják, bárcsak soha ne lenne vége az alkonynak. Senki sem szórakozik egyáltalán.'::text),
(349635,38849,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gehen ... schwimmen, kurz vor der Nacht.'::text,'in der Dämmerung'::text,'in der Dämmerung'::text,'in einer Dämmerung'::text,'Sie gehen in der Dämmerung schwimmen, kurz vor der Nacht.'::text),
(349639,38849,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони йдуть плавати в ..., якраз перед ніччю.'::text,'сутінках'::text,'сутінках'::text,'сутінках'::text,'Вони йдуть плавати в сутінках, якраз перед ніччю.'::text),
(349638,38849,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van a nadar ..., justo antes de la noche.'::text,'al anochecer'::text,'al anochecer'::text,'en un anochecer'::text,'Van a nadar al anochecer, justo antes de la noche.'::text),
(349637,38849,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils vont nager ..., juste avant la nuit.'::text,'au crépuscule'::text,'au crépuscule'::text,'à un crépuscule'::text,'Ils vont nager au crépuscule, juste avant la nuit.'::text),
(349640,38849,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... yüzmeye gidiyorlar, gece çökmeden hemen önce.'::text,'Alacakaranlıkta'::text,'Alacakaranlıkta'::text,'Bir alacakaranlıkta'::text,'Alacakaranlıkta yüzmeye gidiyorlar, gece çökmeden hemen önce.'::text),
(349641,38849,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mennek úszni, éppen az éjszaka előtt.'::text,'Alkonyatkor'::text,'Az alkonyatkor'::text,'Egy alkonyatkor'::text,'Alkonyatkor mennek úszni, éppen az éjszaka előtt.'::text),
(349644,38850,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des schwindenden Lichts in der Dämmerung sprangen sie weiter in den See.'::text,'Trotz'::text,'Obwohl'::text,'Dank'::text,'Trotz des schwindenden Lichts in der Dämmerung sprangen sie weiter in den See.'::text),
(349648,38850,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... згасаюче світло в сутінках, вони й далі стрибали в озеро.'::text,'Попри'::text,'Хоча'::text,'Завдяки'::text,'Попри згасаюче світло в сутінках, вони й далі стрибали в озеро.'::text),
(349647,38850,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la luz menguante del anochecer, siguieron saltando al lago.'::text,'A pesar de'::text,'Aunque'::text,'Gracias a'::text,'A pesar de la luz menguante del anochecer, siguieron saltando al lago.'::text),
(349646,38850,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la lumière déclinante du crépuscule, ils ont continué à sauter dans le lac.'::text,'Malgré'::text,'Même si'::text,'Grâce à'::text,'Malgré la lumière déclinante du crépuscule, ils ont continué à sauter dans le lac.'::text),
(349649,38850,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alacakaranlıkta azalan ışığa ... göle atlamaya devam ettiler.'::text,'rağmen'::text,'olsa da'::text,'sayesinde'::text,'Alacakaranlıkta azalan ışığa rağmen göle atlamaya devam ettiler.'::text),
(349650,38850,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alkonyati halványuló fény ... tovább ugráltak a tóba.'::text,'ellenére'::text,'bár'::text,'köszönhetően'::text,'Az alkonyati halványuló fény ellenére tovább ugráltak a tóba.'::text),
(399729,44415,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie die schwarze Tür auf, weil die schwarze Tür ein Schloss hat.'::text,'schließt'::text,'schließt'::text,'schließt'::text,'Morgen um diese Zeit schließt sie die schwarze Tür auf, weil die schwarze Tür ein Schloss hat.'::text),
(399733,44415,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона ... чорні двері, бо в чорних дверях є замок.'::text,'відмикатиме'::text,'відімкне'::text,'відмикає'::text,'Завтра в цей час вона відмикатиме чорні двері, бо в чорних дверях є замок.'::text),
(399732,44415,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... la puerta negra, porque la puerta negra tiene cerradura.'::text,'estará abriendo'::text,'abrirá'::text,'abre'::text,'Mañana a esta hora estará abriendo la puerta negra, porque la puerta negra tiene cerradura.'::text),
(399731,44415,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, elle ... la porte noire, parce que la porte noire a une serrure.'::text,'sera en train de déverrouiller'::text,'déverrouillera'::text,'déverrouille'::text,'Demain à cette heure-ci, elle sera en train de déverrouiller la porte noire, parce que la porte noire a une serrure.'::text),
(399734,44415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte siyah kapının kilidini ..., çünkü siyah kapının kilidi var.'::text,'açıyor olacak'::text,'açacak'::text,'açıyor'::text,'Yarın bu saatte siyah kapının kilidini açıyor olacak, çünkü siyah kapının kilidi var.'::text),
(399735,44415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ... a fekete ajtót, mert a fekete ajtón van zár.'::text,'nyitja ki'::text,'ki fogja nyitni'::text,'kinyitja'::text,'Holnap ilyenkor nyitja ki a fekete ajtót, mert a fekete ajtón van zár.'::text),
(399747,44417,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Holztür ... mit einem Schlüssel vom großen Bund aufgeschlossen.'::text,'wurde'::text,'schloss'::text,'schloss gerade'::text,'Die Holztür wurde mit einem Schlüssel vom großen Bund aufgeschlossen.'::text),
(399751,44417,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дерев''яні двері ... ключем із великої зв''язки.'::text,'були відімкнені'::text,'відімкнули'::text,'відмикали'::text,'Дерев''яні двері були відімкнені ключем із великої зв''язки.'::text),
(399750,44417,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La puerta de madera ... con una llave del gran llavero.'::text,'fue abierta'::text,'abrió'::text,'estaba abriendo'::text,'La puerta de madera fue abierta con una llave del gran llavero.'::text),
(399749,44417,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La porte en bois ... avec une clé du grand trousseau.'::text,'a été déverrouillée'::text,'a déverrouillé'::text,'déverrouillait'::text,'La porte en bois a été déverrouillée avec une clé du grand trousseau.'::text),
(399752,44417,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahşap kapının kilidi büyük anahtarlıktaki bir anahtarla ...'::text,'açıldı'::text,'açtı'::text,'açıyordu'::text,'Ahşap kapının kilidi büyük anahtarlıktaki bir anahtarla açıldı.'::text),
(399753,44417,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fa ajtót a nagy kulcscsomó egyik kulcsával ... ki.'::text,'nyitották'::text,'nyitotta'::text,'nyitotta éppen'::text,'A fa ajtót a nagy kulcscsomó egyik kulcsával nyitották ki.'::text),
(399756,44418,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau ... die schwarze Tür mit einem kleinen Schlüssel aus dem Briefkasten auf.'::text,'schloss'::text,'wurde aufgeschlossen'::text,'aufschließend'::text,'Die Frau schloss die schwarze Tür mit einem kleinen Schlüssel aus dem Briefkasten auf.'::text),
(399760,44418,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка ... чорні двері маленьким ключем зі скриньки.'::text,'відімкнула'::text,'була відімкнена'::text,'відмикаючи'::text,'Жінка відімкнула чорні двері маленьким ключем зі скриньки.'::text),
(399759,44418,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... la puerta negra con una llavecita del buzón.'::text,'abrió'::text,'fue abierta'::text,'abriendo'::text,'La mujer abrió la puerta negra con una llavecita del buzón.'::text),
(399758,44418,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... la porte noire avec une petite clé de la boîte aux lettres.'::text,'a déverrouillé'::text,'a été déverrouillée'::text,'déverrouillant'::text,'La femme a déverrouillé la porte noire avec une petite clé de la boîte aux lettres.'::text),
(399761,44418,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın siyah kapının kilidini posta kutusundaki küçük bir anahtarla ...'::text,'açtı'::text,'açıldı'::text,'açarak'::text,'Kadın siyah kapının kilidini posta kutusundaki küçük bir anahtarla açtı.'::text),
(399762,44418,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő ... a fekete ajtót egy kis kulccsal a postaládából.'::text,'kinyitotta'::text,'ki lett nyitva'::text,'kinyitva'::text,'A nő kinyitotta a fekete ajtót egy kis kulccsal a postaládából.'::text),
(399765,44419,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, mit dem Schlüsselbund ... du diejenige sein, die die ganze Stadt aufschließt.'::text,'musst'::text,'kannst nicht'::text,'darfst nicht'::text,'Ehrlich, mit dem Schlüsselbund musst du diejenige sein, die die ganze Stadt aufschließt.'::text),
(399769,44419,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, з такою зв''язкою ключів ти ... бути тією, хто відмикає все місто.'::text,'мусиш'::text,'не можеш'::text,'не маєш права'::text,'Чесно, з такою зв''язкою ключів ти мусиш бути тією, хто відмикає все місто.'::text),
(399768,44419,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, con ese llavero ... ser la que abre toda la ciudad.'::text,'debes de'::text,'no puedes'::text,'no debes'::text,'La verdad, con ese llavero debes de ser la que abre toda la ciudad.'::text),
(399767,44419,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, avec ce trousseau, tu ... être celle qui déverrouille toute la ville.'::text,'dois'::text,'ne peux pas'::text,'ne dois pas'::text,'Franchement, avec ce trousseau, tu dois être celle qui déverrouille toute la ville.'::text),
(399770,44419,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası o anahtarlıkla bütün kasabanın kilidini açan kişi sen ...'::text,'olmalısın'::text,'olamazsın'::text,'olmamalısın'::text,'Açıkçası o anahtarlıkla bütün kasabanın kilidini açan kişi sen olmalısın.'::text),
(399771,44419,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, azzal a kulcscsomóval neked ... lenned az, aki az egész várost kinyitja.'::text,'kell'::text,'nem lehet'::text,'nem szabad'::text,'Őszintén, azzal a kulcscsomóval neked kell lenned az, aki az egész várost kinyitja.'::text),
(399774,44420,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schlüssel, ... die Holztür aufschließt, ist natürlich der erste, den sie probiert.'::text,'der'::text,'wer'::text,'dessen'::text,'Der Schlüssel, der die Holztür aufschließt, ist natürlich der erste, den sie probiert.'::text),
(399778,44420,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ключ, ... відмикає дерев''яні двері, звісно ж, перший, який вона пробує.'::text,'який'::text,'хто'::text,'чий'::text,'Ключ, який відмикає дерев''яні двері, звісно ж, перший, який вона пробує.'::text),
(399777,44420,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La llave ... abre la puerta de madera es, obviamente, la primera que prueba.'::text,'que'::text,'quien'::text,'cuya'::text,'La llave que abre la puerta de madera es, obviamente, la primera que prueba.'::text),
(399776,44420,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La clé ... ouvre la porte en bois est évidemment la première qu''elle essaie.'::text,'qui'::text,'qui'::text,'dont'::text,'La clé qui ouvre la porte en bois est évidemment la première qu''elle essaie.'::text),
(399779,44420,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anahtar, ... ahşap kapıyı açıyor, tabii ki denediği ilk anahtar.'::text,'ki'::text,'kim ki'::text,'ki onun'::text,'Anahtar, ki ahşap kapıyı açıyor, tabii ki denediği ilk anahtar.'::text),
(399780,44420,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kulcs, ... kinyitja a fa ajtót, nyilván az első, amit kipróbál.'::text,'amely'::text,'aki'::text,'amelynek'::text,'A kulcs, amely kinyitja a fa ajtót, nyilván az első, amit kipróbál.'::text),
(399783,44421,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, sie ... jede Tür in fünf Sekunden aufschließen. Offensichtlich wahr, wenn man den Schlüsselbund sieht.'::text,'würde'::text,'wird'::text,'schließt'::text,'Sie sagte, sie würde jede Tür in fünf Sekunden aufschließen. Offensichtlich wahr, wenn man den Schlüsselbund sieht.'::text),
(399787,44421,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... будь-які двері за п''ять секунд. Явно правда, судячи з тієї зв''язки ключів.'::text,'відімкне'::text,'відімкне'::text,'відмикає'::text,'Вона сказала, що відімкне будь-які двері за п''ять секунд. Явно правда, судячи з тієї зв''язки ключів.'::text),
(399786,44421,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... cualquier puerta en cinco segundos. Claramente cierto, a juzgar por ese llavero.'::text,'abriría'::text,'abrirá'::text,'abre'::text,'Dijo que abriría cualquier puerta en cinco segundos. Claramente cierto, a juzgar por ese llavero.'::text),
(399785,44421,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... chaque porte en cinq secondes. Clairement vrai, vu ce trousseau.'::text,'déverrouillerait'::text,'déverrouillera'::text,'déverrouille'::text,'Elle a dit qu''elle déverrouillerait chaque porte en cinq secondes. Clairement vrai, vu ce trousseau.'::text),
(399788,44421,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kapıyı beş saniyede ... söyledi. Şu anahtarlığa bakılırsa kesin doğru.'::text,'açacağını'::text,'açacağını'::text,'açtığını'::text,'Her kapıyı beş saniyede açacağını söyledi. Şu anahtarlığa bakılırsa kesin doğru.'::text),
(399789,44421,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy öt másodperc alatt ... minden ajtót. Nyilván igaz, ha elnézzük azt a kulcscsomót.'::text,'kinyit'::text,'ki fog nyitni'::text,'kinyit'::text,'Azt mondta, hogy öt másodperc alatt kinyit minden ajtót. Nyilván igaz, ha elnézzük azt a kulcscsomót.'::text),
(399792,44422,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Früher ... es einen winzigen Schlüssel für all diese Türen. Offensichtlich einfachere Zeiten.'::text,'gab'::text,'gäbe'::text,'war gewohnt zu geben'::text,'Früher gab es einen winzigen Schlüssel für all diese Türen. Offensichtlich einfachere Zeiten.'::text),
(399796,44422,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... один крихітний ключ, щоб відімкнути всі ці двері. Явно простіші часи.'::text,'Колись був'::text,'Був би'::text,'Звик бути'::text,'Колись був один крихітний ключ, щоб відімкнути всі ці двері. Явно простіші часи.'::text),
(399795,44422,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... haber una llavecita para abrir todas estas puertas. Claramente tiempos más simples.'::text,'Solía'::text,'Solía'::text,'Estaba acostumbrado a'::text,'Solía haber una llavecita para abrir todas estas puertas. Claramente tiempos más simples.'::text),
(399794,44422,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Autrefois, ... une toute petite clé pour ouvrir toutes ces portes. Clairement une époque plus simple.'::text,'il y avait'::text,'il y aurait'::text,'il avait l''habitude d''y avoir'::text,'Autrefois, il y avait une toute petite clé pour ouvrir toutes ces portes. Clairement une époque plus simple.'::text),
(399797,44422,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden bütün bu kapıları açmak için minicik tek bir anahtar ..., belli ki daha basit zamanlar.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Eskiden bütün bu kapıları açmak için minicik tek bir anahtar olurdu, belli ki daha basit zamanlar.'::text),
(399798,44422,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen egyetlen pici kulcs ... az összes ajtó kinyitásához. Nyilván egyszerűbb idők.'::text,'volt'::text,'lett volna'::text,'hozzá volt szokva, hogy legyen'::text,'Régen egyetlen pici kulcs volt az összes ajtó kinyitásához. Nyilván egyszerűbb idők.'::text),
(399801,44423,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schafft es, die Holztür mit einem Schlüssel vom großen Bund ...'::text,'aufzuschließen'::text,'aufschließen'::text,'aufschließen'::text,'Sie schafft es, die Holztür mit einem Schlüssel vom großen Bund aufzuschließen.'::text),
(399805,44423,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй вдається ... дерев''яні двері ключем із великої зв''язки.'::text,'відімкнути'::text,'відімкнути'::text,'відімкнути'::text,'Їй вдається відімкнути дерев''яні двері ключем із великої зв''язки.'::text),
(399804,44423,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Consigue ... la puerta de madera con una llave del gran llavero.'::text,'abrir'::text,'abrir'::text,'abrir'::text,'Consigue abrir la puerta de madera con una llave del gran llavero.'::text),
(399803,44423,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle arrive à ... la porte en bois avec une clé du grand trousseau.'::text,'déverrouiller'::text,'déverrouiller'::text,'déverrouiller'::text,'Elle arrive à déverrouiller la porte en bois avec une clé du grand trousseau.'::text),
(399806,44423,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük anahtarlıktaki bir anahtarla ahşap kapının kilidini ... başarıyor.'::text,'açmayı'::text,'açmayı'::text,'açmak'::text,'Büyük anahtarlıktaki bir anahtarla ahşap kapının kilidini açmayı başarıyor.'::text),
(399807,44423,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sikerül ... a fa ajtót a nagy kulcscsomó egyik kulcsával.'::text,'kinyitnia'::text,'kinyitás'::text,'kinyitni'::text,'Sikerül kinyitnia a fa ajtót a nagy kulcscsomó egyik kulcsával.'::text),
(399810,44424,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... hier jeden Morgen die Türen auf, deshalb trägt sie einen großen Schlüsselbund.'::text,'schließt'::text,'schließt'::text,'hat'::text,'Sie schließt hier jeden Morgen die Türen auf, deshalb trägt sie einen großen Schlüsselbund.'::text),
(399814,44424,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона щоранку ... тут двері, тому носить велику зв''язку ключів.'::text,'відмикає'::text,'відмикає'::text,'відімкнула'::text,'Вона щоранку відмикає тут двері, тому носить велику зв''язку ключів.'::text),
(399813,44424,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... las puertas aquí cada mañana, así que lleva un gran llavero.'::text,'abre'::text,'está abriendo'::text,'ha abierto'::text,'Ella abre las puertas aquí cada mañana, así que lleva un gran llavero.'::text),
(399812,44424,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les portes ici chaque matin, donc elle porte un gros trousseau de clés.'::text,'déverrouille'::text,'déverrouille'::text,'a déverrouillé'::text,'Elle déverrouille les portes ici chaque matin, donc elle porte un gros trousseau de clés.'::text),
(399815,44424,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burada her sabah kapıları ..., bu yüzden büyük bir anahtarlık taşıyor.'::text,'açar'::text,'açıyor'::text,'açtı'::text,'Burada her sabah kapıları açar, bu yüzden büyük bir anahtarlık taşıyor.'::text),
(399816,44424,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Itt minden reggel ő ... ki az ajtókat, ezért nagy kulcscsomót hord.'::text,'nyitja'::text,'nyitja'::text,'nyitotta'::text,'Itt minden reggel ő nyitja ki az ajtókat, ezért nagy kulcscsomót hord.'::text),
(360651,40073,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Familie hat zugestimmt, 50 hausgemachte Brote auf dem Markt ..., um ihr Ziel zu erreichen.'::text,'zu verkaufen'::text,'verkaufen'::text,'verkaufen'::text,'Die Familie hat zugestimmt, 50 hausgemachte Brote auf dem Markt zu verkaufen, um ihr Ziel zu erreichen.'::text),
(360655,40073,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Родина погодилася ... на ринку 50 домашніх буханців, щоб виконати план.'::text,'продати'::text,'продаж'::text,'продати'::text,'Родина погодилася продати на ринку 50 домашніх буханців, щоб виконати план.'::text),
(360654,40073,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La familia acordó ... 50 panes caseros en el mercado para cumplir su objetivo.'::text,'vender'::text,'vendiendo'::text,'vender'::text,'La familia acordó vender 50 panes caseros en el mercado para cumplir su objetivo.'::text),
(360653,40073,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La famille a accepté ... 50 pains faits maison au marché pour atteindre son objectif.'::text,'de vendre'::text,'vendant'::text,'vendre'::text,'La famille a accepté de vendre 50 pains faits maison au marché pour atteindre son objectif.'::text),
(360656,40073,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aile, hedefine ulaşmak için pazarda 50 ev yapımı somun ... kabul etti.'::text,'satmayı'::text,'satmayı'::text,'satmak'::text,'Aile, hedefine ulaşmak için pazarda 50 ev yapımı somun satmayı kabul etti.'::text),
(360657,40073,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A család beleegyezett, hogy ... 50 házi kenyeret a piacon, hogy elérje a célját.'::text,'eladjon'::text,'eladás'::text,'elad'::text,'A család beleegyezett, hogy eladjon 50 házi kenyeret a piacon, hogy elérje a célját.'::text),
(360669,40075,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die junge Frau liebt hausgemachtes Brot, und ...'::text,'die ältere Frau auch'::text,'die ältere Frau auch'::text,'die ältere Frau auch nicht'::text,'Die junge Frau liebt hausgemachtes Brot, und die ältere Frau auch.'::text),
(360673,40075,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молода жінка обожнює домашній хліб, і ...'::text,'старша жінка теж'::text,'старша жінка теж'::text,'старша жінка теж ні'::text,'Молода жінка обожнює домашній хліб, і старша жінка теж.'::text),
(360672,40075,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A la joven le encanta el pan casero, y ...'::text,'a la mujer mayor también'::text,'a la mujer mayor también'::text,'a la mujer mayor tampoco'::text,'A la joven le encanta el pan casero, y a la mujer mayor también.'::text),
(360671,40075,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jeune femme adore le pain fait maison, et ...'::text,'la femme plus âgée aussi'::text,'la femme plus âgée aussi'::text,'la femme plus âgée non plus'::text,'La jeune femme adore le pain fait maison, et la femme plus âgée aussi.'::text),
(360674,40075,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç kadın ev yapımı ekmeğe bayılıyor ve ...'::text,'yaşlı kadın da öyle'::text,'yaşlı kadın da öyle'::text,'yaşlı kadın da değil'::text,'Genç kadın ev yapımı ekmeğe bayılıyor ve yaşlı kadın da öyle.'::text),
(360675,40075,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatal nő imádja a házi kenyeret, és ...'::text,'az idősebb nő is'::text,'az idősebb nő is'::text,'az idősebb nő sem'::text,'A fiatal nő imádja a házi kenyeret, és az idősebb nő is.'::text),
(360678,40076,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Teig zwanzig Minuten lang geknetet, bevor der hausgemachte Laib rund war.'::text,'hatten'::text,'haben'::text,'kneteten'::text,'Sie hatten den Teig zwanzig Minuten lang geknetet, bevor der hausgemachte Laib rund war.'::text),
(360682,40076,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... тісто двадцять хвилин, поки домашній буханець не став круглим.'::text,'місили'::text,'місять'::text,'місили'::text,'Вони місили тісто двадцять хвилин, поки домашній буханець не став круглим.'::text),
(360681,40076,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la masa durante veinte minutos antes de que el pan casero quedara redondo.'::text,'Habían estado amasando'::text,'Han estado amasando'::text,'Estaban amasando'::text,'Habían estado amasando la masa durante veinte minutos antes de que el pan casero quedara redondo.'::text),
(360680,40076,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ... la pâte pendant vingt minutes avant que le pain fait maison soit rond.'::text,'avaient pétri'::text,'ont pétri'::text,'pétrissaient'::text,'Elles avaient pétri la pâte pendant vingt minutes avant que le pain fait maison soit rond.'::text),
(360683,40076,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev yapımı somun yuvarlak olmadan önce yirmi dakika hamur ...'::text,'yoğurmuşlardı'::text,'yoğuruyorlar'::text,'yoğuruyorlardı'::text,'Ev yapımı somun yuvarlak olmadan önce yirmi dakika hamur yoğurmuşlardı.'::text),
(360684,40076,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Húsz percig ... a tésztát, mire a házi kenyér kerek lett.'::text,'gyúrták'::text,'gyúrják'::text,'gyúrták'::text,'Húsz percig gyúrták a tésztát, mire a házi kenyér kerek lett.'::text),
(360687,40077,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, anscheinend ... sie bis Sonntag zehn hausgemachte Brote gebacken haben.'::text,'werden'::text,'werden'::text,'werden'::text,'Girl, anscheinend werden sie bis Sonntag zehn hausgemachte Brote gebacken haben.'::text),
(360691,40077,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, до неділі вони ... десять домашніх буханців.'::text,'спечуть'::text,'спечуть'::text,'пектимуть'::text,'Подруго, кажуть, до неділі вони спечуть десять домашніх буханців.'::text),
(360690,40077,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer para el domingo ... diez panes caseros.'::text,'habrán horneado'::text,'hornearán'::text,'estarán horneando'::text,'Tía, al parecer para el domingo habrán horneado diez panes caseros.'::text),
(360689,40077,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment d''ici dimanche elles ... dix pains faits maison.'::text,'auront cuit'::text,'cuiront'::text,'seront en train de cuire'::text,'Meuf, apparemment d''ici dimanche elles auront cuit dix pains faits maison.'::text),
(360692,40077,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya pazara kadar on ev yapımı somun ...'::text,'pişirmiş olacaklarmış'::text,'pişirecekler'::text,'pişiriyor olacaklar'::text,'Kızım, güya pazara kadar on ev yapımı somun pişirmiş olacaklarmış.'::text),
(360693,40077,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag vasárnapra ... tíz házi kenyeret.'::text,'megsütnek'::text,'meg fognak sütni'::text,'sütni fognak'::text,'Csajszi, állítólag vasárnapra megsütnek tíz házi kenyeret.'::text),
(360696,40078,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... du schon fünf Stunden lang hausgemachtes Brot gebacken haben, und ehrlich, Respekt.'::text,'wirst'::text,'wirst'::text,'wirst'::text,'Bis Mittag wirst du schon fünf Stunden lang hausgemachtes Brot gebacken haben, und ehrlich, Respekt.'::text),
(360700,40078,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду ти вже ... домашній хліб п''ять годин, і чесно, респект.'::text,'пектимеш'::text,'пектимеш'::text,'спечеш'::text,'До обіду ти вже пектимеш домашній хліб п''ять годин, і чесно, респект.'::text),
(360699,40078,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, ... pan casero durante cinco horas, y la verdad, respeto.'::text,'habrás estado haciendo'::text,'estarás haciendo'::text,'habrás hecho'::text,'Para el mediodía, habrás estado haciendo pan casero durante cinco horas, y la verdad, respeto.'::text),
(360698,40078,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, tu ... du pain fait maison pendant cinq heures, et franchement, respect.'::text,'auras fait'::text,'feras'::text,'auras fait'::text,'D''ici midi, tu auras fait du pain fait maison pendant cinq heures, et franchement, respect.'::text),
(360701,40078,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar beş saattir ev yapımı ekmek ..., ve açıkçası helal.'::text,'yapıyor olacaksın'::text,'yapıyor olacaksın'::text,'yapmış olacaksın'::text,'Öğlene kadar beş saattir ev yapımı ekmek yapıyor olacaksın, ve açıkçası helal.'::text),
(360702,40078,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre már öt órája ... a házi kenyeret, és őszintén, respekt.'::text,'sütöd'::text,'sütöd'::text,'megsütöd'::text,'Délre már öt órája sütöd a házi kenyeret, és őszintén, respekt.'::text),
(360705,40079,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, wenn du es mir nicht gezeigt hättest, ... ich so ein hausgemachtes Brot nicht gebacken.'::text,'hätte'::text,'werde'::text,'habe'::text,'Ehrlich gesagt, wenn du es mir nicht gezeigt hättest, hätte ich so ein hausgemachtes Brot nicht gebacken.'::text),
(360709,40079,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, якби ти мені не показала, я ... такий домашній хліб.'::text,'не спік би'::text,'не спечу'::text,'не спік'::text,'Не буду брехати, якби ти мені не показала, я не спік би такий домашній хліб.'::text),
(360708,40079,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, si no me lo hubieras enseñado, no ... un pan casero así.'::text,'habría hecho'::text,'haré'::text,'hice'::text,'No te voy a mentir, si no me lo hubieras enseñado, no habría hecho un pan casero así.'::text),
(360707,40079,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, si tu ne m''avais pas montré, je ... de pain fait maison comme ça.'::text,'n''aurais pas fait'::text,'ne ferai pas'::text,'n''ai pas fait'::text,'Je vais pas mentir, si tu ne m''avais pas montré, je n''aurais pas fait de pain fait maison comme ça.'::text),
(360710,40079,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bana göstermeseydin böyle ev yapımı ekmek ...'::text,'yapmazdım'::text,'yapmayacağım'::text,'yapmadım'::text,'Yalan yok, bana göstermeseydin böyle ev yapımı ekmek yapmazdım.'::text),
(360711,40079,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, ha nem mutattad volna meg, ... ilyen házi kenyeret.'::text,'nem sütöttem volna'::text,'nem fogok sütni'::text,'nem sütöttem'::text,'Nem fogok hazudni, ha nem mutattad volna meg, nem sütöttem volna ilyen házi kenyeret.'::text),
(360723,40081,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die ältere Frau bestritt, dass sie für den hausgemachten Laib Teig aus dem Laden ... hatte. Schockierend, natürlich.'::text,'benutzt'::text,'benutzen'::text,'benutzte'::text,'Die ältere Frau bestritt, dass sie für den hausgemachten Laib Teig aus dem Laden benutzt hatte. Schockierend, natürlich.'::text),
(360727,40081,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старша жінка заперечила, що ... магазинне тісто для домашнього буханця. Шок, звісно.'::text,'використала'::text,'використати'::text,'використала'::text,'Старша жінка заперечила, що використала магазинне тісто для домашнього буханця. Шок, звісно.'::text),
(360726,40081,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer mayor negó ... masa comprada para el pan casero. Impactante, obvio.'::text,'haber usado'::text,'usar'::text,'usó'::text,'La mujer mayor negó haber usado masa comprada para el pan casero. Impactante, obvio.'::text),
(360725,40081,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme plus âgée a nié ... de la pâte du commerce pour le pain fait maison. Choquant, évidemment.'::text,'avoir utilisé'::text,'utiliser'::text,'utilisé'::text,'La femme plus âgée a nié avoir utilisé de la pâte du commerce pour le pain fait maison. Choquant, évidemment.'::text),
(360728,40081,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı kadın ev yapımı somun için hazır hamur ... inkâr etti. Şok edici, tabii ki.'::text,'kullandığını'::text,'kullanmayı'::text,'kullandı'::text,'Yaşlı kadın ev yapımı somun için hazır hamur kullandığını inkâr etti. Şok edici, tabii ki.'::text),
(360729,40081,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idősebb nő tagadta, hogy bolti tésztát ... a házi kenyérhez. Sokkoló, nyilván.'::text,'használt'::text,'használni'::text,'használt'::text,'Az idősebb nő tagadta, hogy bolti tésztát használt a házi kenyérhez. Sokkoló, nyilván.'::text),
(360732,40082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie ... Brot kaufen können, aber hausgemacht ist einfach was anderes, echt.'::text,'hätten'::text,'müssen'::text,'können'::text,'Digga, sie hätten Brot kaufen können, aber hausgemacht ist einfach was anderes, echt.'::text),
(360736,40082,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, вони ... купити хліб, але домашній — це зовсім інший рівень, чесно.'::text,'могли б'::text,'мусили'::text,'можуть'::text,'Брате, вони могли б купити хліб, але домашній — це зовсім інший рівень, чесно.'::text),
(360735,40082,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... comprado pan, pero el casero es otro nivel, en serio.'::text,'podrían haber'::text,'deben de haber'::text,'pueden haber'::text,'Bro, podrían haber comprado pan, pero el casero es otro nivel, en serio.'::text),
(360734,40082,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ils ... acheter du pain, mais le fait maison, c''est un autre délire, sérieux.'::text,'auraient pu'::text,'ont dû'::text,'peuvent'::text,'Frère, ils auraient pu acheter du pain, mais le fait maison, c''est un autre délire, sérieux.'::text),
(360737,40082,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ekmek ..., ama ev yapımı bambaşka, cidden.'::text,'alabilirlerdi'::text,'almış olmalılar'::text,'alabilirler'::text,'Kanka, ekmek alabilirlerdi, ama ev yapımı bambaşka, cidden.'::text),
(360738,40082,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... kenyeret, de a házi az egy másik szint, komolyan.'::text,'vehettek volna'::text,'biztos vettek'::text,'vehetnek'::text,'Tesó, vehettek volna kenyeret, de a házi az egy másik szint, komolyan.'::text),
(360741,40083,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... lachen zwei Menschen so viel beim Backen von hausgemachtem Brot.'::text,''::text,'sie'::text,'sind'::text,'Selten lachen zwei Menschen so viel beim Backen von hausgemachtem Brot.'::text),
(360745,40083,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... двоє людей так сміються, коли печуть домашній хліб.'::text,''::text,'вони'::text,'є'::text,'Рідко двоє людей так сміються, коли печуть домашній хліб.'::text),
(360744,40083,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... dos personas se ríen tanto haciendo pan casero.'::text,''::text,'ellas'::text,'son'::text,'Rara vez dos personas se ríen tanto haciendo pan casero.'::text),
(360743,40083,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... deux personnes rient autant en faisant du pain maison.'::text,''::text,'elles'::text,'sont'::text,'Rarement deux personnes rient autant en faisant du pain maison.'::text),
(360746,40083,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren ... iki kişi ev yapımı ekmek yaparken bu kadar çok güler.'::text,''::text,'onlar'::text,NULL::text,'Nadiren iki kişi ev yapımı ekmek yaparken bu kadar çok güler.'::text),
(360747,40083,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... nevet két ember ennyit házi kenyér sütése közben.'::text,''::text,'ők'::text,'vannak'::text,'Ritkán nevet két ember ennyit házi kenyér sütése közben.'::text),
(395625,43959,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wusste, dass die Reisschüssel aus Stein mit der roten Chilipaste lecker ...'::text,'sein würde'::text,'sein wird'::text,'ist'::text,'Sie wusste, dass die Reisschüssel aus Stein mit der roten Chilipaste lecker sein würde.'::text),
(395629,43959,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона знала, що кам''яна миска рису з червоною пастою чилі ... смачною.'::text,'буде'::text,'буде'::text,'є'::text,'Вона знала, що кам''яна миска рису з червоною пастою чилі буде смачною.'::text),
(395628,43959,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabía que el cuenco de piedra con arroz ... delicioso con la pasta roja de chile.'::text,'estaría'::text,'estará'::text,'está siendo'::text,'Sabía que el cuenco de piedra con arroz estaría delicioso con la pasta roja de chile.'::text),
(395627,43959,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle savait que le bol de riz en pierre ... délicieux avec la pâte de piment rouge.'::text,'serait'::text,'sera'::text,'est'::text,'Elle savait que le bol de riz en pierre serait délicieux avec la pâte de piment rouge.'::text),
(395630,43959,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taş kasedeki pilavın kırmızı biber salçasıyla lezzetli ... biliyordu.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Taş kasedeki pilavın kırmızı biber salçasıyla lezzetli olacağını biliyordu.'::text),
(395631,43959,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy a kőtálas rizs a piros chilipasztával finom ...'::text,'lesz'::text,'lesz'::text,NULL::text,'Tudta, hogy a kőtálas rizs a piros chilipasztával finom lesz.'::text),
(360156,40018,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Klasse ... leise, während er ein urkomisches Video schaute. Toller Fokus, natürlich.'::text,'arbeitete'::text,'arbeitete'::text,'hat gearbeitet'::text,'Die Klasse arbeitete leise, während er ein urkomisches Video schaute. Toller Fokus, natürlich.'::text),
(360160,40018,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клас тихо ..., поки він дивився дико смішне відео. Чудова зосередженість, звісно.'::text,'працював'::text,'працював'::text,'працював'::text,'Клас тихо працював, поки він дивився дико смішне відео. Чудова зосередженість, звісно.'::text),
(360159,40018,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La clase ... en silencio mientras él veía un vídeo desternillante. Qué concentración, obvio.'::text,'estaba trabajando'::text,'trabajó'::text,'ha trabajado'::text,'La clase estaba trabajando en silencio mientras él veía un vídeo desternillante. Qué concentración, obvio.'::text),
(360158,40018,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La classe ... en silence pendant qu''il regardait une vidéo hilarante. Super concentration, évidemment.'::text,'travaillait'::text,'a travaillé'::text,'a travaillé'::text,'La classe travaillait en silence pendant qu''il regardait une vidéo hilarante. Super concentration, évidemment.'::text),
(360161,40018,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çok komik bir video izlerken sınıf sessizce ..., müthiş odaklanma tabii.'::text,'çalışıyordu'::text,'çalıştı'::text,'çalıştı'::text,'O çok komik bir video izlerken sınıf sessizce çalışıyordu, müthiş odaklanma tabii.'::text),
(360162,40018,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az osztály csendben ..., miközben ő egy iszonyú vicces videót nézett. Remek fókusz, nyilván.'::text,'dolgozott'::text,'dolgozott'::text,'dolgozott'::text,'Az osztály csendben dolgozott, miközben ő egy iszonyú vicces videót nézett. Remek fókusz, nyilván.'::text),
(360174,40020,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade auf sein Handy, als er etwas Urkomisches sah.'::text,'schaute'::text,'schaute'::text,'hat geschaut'::text,'Er schaute gerade auf sein Handy, als er etwas Urkomisches sah.'::text),
(360178,40020,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... в телефон, коли побачив щось дико смішне.'::text,'дивився'::text,'подивився'::text,'подивився'::text,'Він дивився в телефон, коли побачив щось дико смішне.'::text),
(360177,40020,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el móvil cuando vio algo desternillante.'::text,'Estaba mirando'::text,'Miró'::text,'Ha mirado'::text,'Estaba mirando el móvil cuando vio algo desternillante.'::text),
(360176,40020,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... son téléphone quand il a vu un truc hilarant.'::text,'regardait'::text,'a regardé'::text,'a regardé'::text,'Il regardait son téléphone quand il a vu un truc hilarant.'::text),
(360179,40020,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok komik bir şey gördüğünde telefonuna ...'::text,'bakıyordu'::text,'baktı'::text,'baktı'::text,'Çok komik bir şey gördüğünde telefonuna bakıyordu.'::text),
(360180,40020,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp a telefonját ..., amikor valami iszonyú viccest látott.'::text,'nézte'::text,'megnézte'::text,'megnézte'::text,'Épp a telefonját nézte, amikor valami iszonyú viccest látott.'::text),
(360183,40021,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er brachte das Mädchen mit den Zöpfen dazu, sich das urkomische Video auf seinem Handy auch ...'::text,'anzusehen'::text,'ansehen'::text,'ansehend'::text,'Er brachte das Mädchen mit den Zöpfen dazu, sich das urkomische Video auf seinem Handy auch anzusehen.'::text),
(360187,40021,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він умовив дівчину з косичками теж ... те дико смішне відео на його телефоні.'::text,'подивитися'::text,'подивитися'::text,'дивлячись'::text,'Він умовив дівчину з косичками теж подивитися те дико смішне відео на його телефоні.'::text),
(360186,40021,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Consiguió que la chica de las trenzas también ... el vídeo desternillante en su móvil.'::text,'viera'::text,'ver'::text,'viendo'::text,'Consiguió que la chica de las trenzas también viera el vídeo desternillante en su móvil.'::text),
(360185,40021,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a convaincu la fille aux tresses de ... aussi la vidéo hilarante sur son téléphone.'::text,'regarder'::text,'regarder'::text,'regardant'::text,'Il a convaincu la fille aux tresses de regarder aussi la vidéo hilarante sur son téléphone.'::text),
(360188,40021,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Örgülü kıza da telefonundaki o çok komik videoyu ...'::text,'izletti'::text,'izletti'::text,'izleyerek'::text,'Örgülü kıza da telefonundaki o çok komik videoyu izletti.'::text),
(360189,40021,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rávette a copfos lányt, hogy ő is ... meg az iszonyú vicces videót a telefonján.'::text,'nézze'::text,'nézni'::text,'nézve'::text,'Rávette a copfos lányt, hogy ő is nézze meg az iszonyú vicces videót a telefonján.'::text),
(360201,40023,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Student, ... Handy etwas Urkomisches zeigte, hat die Vorlesung komplett zerstört!'::text,'dessen'::text,'der'::text,'das'::text,'Der Student, dessen Handy etwas Urkomisches zeigte, hat die Vorlesung komplett zerstört!'::text),
(360205,40023,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Студент, ... телефон показав щось дико смішне, повністю зірвав лекцію!'::text,'чий'::text,'який'::text,'що'::text,'Студент, чий телефон показав щось дико смішне, повністю зірвав лекцію!'::text),
(360204,40023,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El estudiante, ... móvil mostró algo desternillante, destrozó por completo la clase!'::text,'cuyo'::text,'quien'::text,'el cual'::text,'¡El estudiante, cuyo móvil mostró algo desternillante, destrozó por completo la clase!'::text),
(360203,40023,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''étudiant, ... le téléphone a montré un truc hilarant, a complètement détruit le cours !'::text,'dont'::text,'qui'::text,'lequel'::text,'L''étudiant, dont le téléphone a montré un truc hilarant, a complètement détruit le cours !'::text),
(360206,40023,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğrenci, ... telefonu çok komik bir şey gösterdi, dersi tamamen mahvetti!'::text,'ki onun'::text,'ki'::text,'ki'::text,'Öğrenci, ki onun telefonu çok komik bir şey gösterdi, dersi tamamen mahvetti!'::text),
(360207,40023,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A diák, ... telefonja valami iszonyú viccest mutatott, teljesen tönkretette az előadást!'::text,'akinek a'::text,'aki'::text,'amely'::text,'A diák, akinek a telefonja valami iszonyú viccest mutatott, teljesen tönkretette az előadást!'::text),
(360210,40024,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Vorlesung konnte er nicht aufhören, über das urkomische Video zu lachen.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz der Vorlesung konnte er nicht aufhören, über das urkomische Video zu lachen.'::text),
(360214,40024,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... лекцію, він не міг перестати сміятися з дико смішного відео.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри лекцію, він не міг перестати сміятися з дико смішного відео.'::text),
(360213,40024,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la clase, no podía parar de reírse con el vídeo desternillante.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de la clase, no podía parar de reírse con el vídeo desternillante.'::text),
(360212,40024,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le cours, il ne pouvait pas s''arrêter de rire devant la vidéo hilarante.'::text,'Malgré'::text,'Bien que'::text,'En raison de'::text,'Malgré le cours, il ne pouvait pas s''arrêter de rire devant la vidéo hilarante.'::text),
(360215,40024,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Derse ... o çok komik videoya gülmeyi bırakamadı.'::text,'rağmen'::text,'olsa da'::text,'yüzünden'::text,'Derse rağmen o çok komik videoya gülmeyi bırakamadı.'::text),
(360216,40024,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az előadás ... nem tudta abbahagyni a nevetést az iszonyú vicces videón.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Az előadás ellenére nem tudta abbahagyni a nevetést az iszonyú vicces videón.'::text),
(360219,40025,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, er hat mir erzählt, er wusste, dass das Video urkomisch ..., noch bevor er es abgespielt hat.'::text,'sein würde'::text,'sein wird'::text,'ist'::text,'Girl, er hat mir erzählt, er wusste, dass das Video urkomisch sein würde, noch bevor er es abgespielt hat.'::text),
(360223,40025,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що знав, що відео ... дико смішним, ще до того, як його увімкнув.'::text,'буде'::text,'буде'::text,'є'::text,'Подруго, він сказав мені, що знав, що відео буде дико смішним, ще до того, як його увімкнув.'::text),
(360222,40025,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que sabía que el vídeo ... desternillante antes de ponerlo siquiera.'::text,'sería'::text,'será'::text,'es'::text,'Tía, me dijo que sabía que el vídeo sería desternillante antes de ponerlo siquiera.'::text),
(360221,40025,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il savait que la vidéo ... hilarante avant même de la lancer.'::text,'serait'::text,'sera'::text,'est'::text,'Meuf, il m''a dit qu''il savait que la vidéo serait hilarante avant même de la lancer.'::text),
(360224,40025,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, videoyu daha açmadan çok komik ... bildiğini söyledi.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Kızım, videoyu daha açmadan çok komik olacağını bildiğini söyledi.'::text),
(360225,40025,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, tudta, hogy a videó iszonyú vicces ..., még mielőtt elindította.'::text,'lesz'::text,'lesz'::text,NULL::text,'Csajszi, azt mondta, tudta, hogy a videó iszonyú vicces lesz, még mielőtt elindította.'::text),
(360228,40026,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend ... er sich das urkomische Video seit dem Mittagessen fünfmal angesehen.'::text,'hat'::text,'sieht'::text,'sieht'::text,'Hör zu, anscheinend hat er sich das urkomische Video seit dem Mittagessen fünfmal angesehen.'::text),
(360232,40026,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він ... те дико смішне відео з обіду вже п''ять разів.'::text,'переглянув'::text,'дивиться'::text,'дивиться'::text,'Слухай, кажуть, він переглянув те дико смішне відео з обіду вже п''ять разів.'::text),
(360231,40026,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer ... ese vídeo desternillante cinco veces desde la comida.'::text,'ha visto'::text,'está viendo'::text,'ve'::text,'Escucha, al parecer ha visto ese vídeo desternillante cinco veces desde la comida.'::text),
(360230,40026,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il ... cette vidéo hilarante cinq fois depuis midi.'::text,'a regardé'::text,'regarde'::text,'regarde'::text,'Écoute, apparemment il a regardé cette vidéo hilarante cinq fois depuis midi.'::text),
(360233,40026,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya o çok komik videoyu öğleden beri beş kez ...'::text,'izlemiş'::text,'izliyor'::text,'izler'::text,'Dinle, güya o çok komik videoyu öğleden beri beş kez izlemiş.'::text),
(360234,40026,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ebéd óta ötször ... meg azt az iszonyú vicces videót.'::text,'nézte'::text,'nézi'::text,'nézi'::text,'Figyelj, állítólag ebéd óta ötször nézte meg azt az iszonyú vicces videót.'::text),
(360237,40027,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich ikonisch: Du ... schon ewig über den urkomischen Clip gelacht, bevor es jemand gemerkt hat.'::text,'hattest'::text,'hast'::text,'hast'::text,'Ehrlich ikonisch: Du hattest schon ewig über den urkomischen Clip gelacht, bevor es jemand gemerkt hat.'::text),
(360241,40027,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, культово: ти ... з того дико смішного кліпу цілу вічність, перш ніж хтось помітив.'::text,'сміявся'::text,'сміявся'::text,'смієшся'::text,'Чесно, культово: ти сміявся з того дико смішного кліпу цілу вічність, перш ніж хтось помітив.'::text),
(360240,40027,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente icónico: ... riéndote de ese clip desternillante un montón de rato antes de que nadie se diera cuenta.'::text,'habías estado'::text,'has estado'::text,'has estado'::text,'Sinceramente icónico: habías estado riéndote de ese clip desternillante un montón de rato antes de que nadie se diera cuenta.'::text),
(360239,40027,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement iconique : tu ... de ce clip hilarant pendant des lustres avant que quelqu''un le remarque.'::text,'avais ri'::text,'as ri'::text,'ris'::text,'Franchement iconique : tu avais ri de ce clip hilarant pendant des lustres avant que quelqu''un le remarque.'::text),
(360242,40027,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası efsane: biri fark edene kadar o çok komik klibe uzun süre ...'::text,'gülmüştün'::text,'güldün'::text,'gülüyorsun'::text,'Açıkçası efsane: biri fark edene kadar o çok komik klibe uzun süre gülmüştün.'::text),
(360243,40027,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén ikonikus: már ezer éve ... azon az iszonyú vicces klipen, mire bárki észrevette.'::text,'nevettél'::text,'nevettél'::text,'nevetsz'::text,'Őszintén ikonikus: már ezer éve nevettél azon az iszonyú vicces klipen, mire bárki észrevette.'::text),
(360246,40028,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Stunde ... du das urkomische Video mit allen geteilt haben, ehrlich gesagt.'::text,'wirst'::text,'wirst'::text,'teilst'::text,'Bis zum Ende der Stunde wirst du das urkomische Video mit allen geteilt haben, ehrlich gesagt.'::text),
(360250,40028,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця уроку ти ... тим дико смішним відео з усіма, не буду брехати.'::text,'поділишся'::text,'ділитимешся'::text,'ділишся'::text,'До кінця уроку ти поділишся тим дико смішним відео з усіма, не буду брехати.'::text),
(360249,40028,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la clase, ... ese vídeo desternillante con todo el mundo, no te voy a mentir.'::text,'habrás compartido'::text,'compartirás'::text,'compartes'::text,'Para el final de la clase, habrás compartido ese vídeo desternillante con todo el mundo, no te voy a mentir.'::text),
(360248,40028,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du cours, tu ... cette vidéo hilarante avec tout le monde, je vais pas mentir.'::text,'auras partagé'::text,'partageras'::text,'partages'::text,'D''ici la fin du cours, tu auras partagé cette vidéo hilarante avec tout le monde, je vais pas mentir.'::text),
(360251,40028,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ders bitene kadar o çok komik videoyu herkesle ..., yalan yok.'::text,'paylaşmış olacaksın'::text,'paylaşacaksın'::text,'paylaşıyorsun'::text,'Ders bitene kadar o çok komik videoyu herkesle paylaşmış olacaksın, yalan yok.'::text),
(360252,40028,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az óra végére ... azt az iszonyú vicces videót mindenkivel, nem fogok hazudni.'::text,'megosztod'::text,'meg fogod osztani'::text,'megosztod'::text,'Az óra végére megosztod azt az iszonyú vicces videót mindenkivel, nem fogok hazudni.'::text),
(343191,38133,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, anscheinend ... sie das Federkostüm schon seit sechs Uhr morgens.'::text,'trägt'::text,'trägt'::text,'trägt'::text,'Girl, anscheinend trägt sie das Federkostüm schon seit sechs Uhr morgens.'::text),
(343195,38133,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... той костюм із пір''я з шостої ранку.'::text,'носить'::text,'носить'::text,'носить'::text,'Подруго, кажуть, вона носить той костюм із пір''я з шостої ранку.'::text),
(343194,38133,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... ese disfraz de plumas desde las seis de la mañana.'::text,'lleva'::text,'está llevando'::text,'lleva'::text,'Tía, al parecer lleva ese disfraz de plumas desde las seis de la mañana.'::text),
(343193,38133,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... ce costume à plumes depuis six heures ce matin.'::text,'porte'::text,'porte'::text,'porte'::text,'Meuf, apparemment elle porte ce costume à plumes depuis six heures ce matin.'::text),
(343196,38133,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya sabah altıdan beri o tüylü kostümü ...'::text,'giyiyormuş'::text,'giyiyor'::text,'giyer'::text,'Kızım, güya sabah altıdan beri o tüylü kostümü giyiyormuş.'::text),
(343197,38133,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag reggel hat óta ... azt a tollas jelmezt.'::text,'viseli'::text,'viseli'::text,'viseli'::text,'Csajszi, állítólag reggel hat óta viseli azt a tollas jelmezt.'::text),
(343200,38134,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... das Banner so selbstbewusst, als mir dein Kostüm zum ersten Mal aufgefallen ist.'::text,'trugst'::text,'trugst'::text,'hast getragen'::text,'Du trugst das Banner so selbstbewusst, als mir dein Kostüm zum ersten Mal aufgefallen ist.'::text),
(343204,38134,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... той банер так упевнено, коли я вперше помітив твій костюм.'::text,'несла'::text,'несла'::text,'несла'::text,'Ти несла той банер так упевнено, коли я вперше помітив твій костюм.'::text),
(343203,38134,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el estandarte con tanta seguridad cuando me fijé en tu disfraz por primera vez.'::text,'Llevabas'::text,'Llevaste'::text,'Has llevado'::text,'Llevabas el estandarte con tanta seguridad cuando me fijé en tu disfraz por primera vez.'::text),
(343202,38134,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... la bannière avec tellement d''assurance quand j''ai remarqué ton costume pour la première fois.'::text,'portais'::text,'as porté'::text,'as porté'::text,'Tu portais la bannière avec tellement d''assurance quand j''ai remarqué ton costume pour la première fois.'::text),
(343205,38134,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kostümünü ilk fark ettiğimde pankartı çok özgüvenli ...'::text,'taşıyordun'::text,'taşıdın'::text,'taşıdın'::text,'Kostümünü ilk fark ettiğimde pankartı çok özgüvenli taşıyordun.'::text),
(343206,38134,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan magabiztosan ... a transzparenst, amikor először kiszúrtam a jelmezedet.'::text,'vitted'::text,'vitted'::text,'vitted'::text,'Olyan magabiztosan vitted a transzparenst, amikor először kiszúrtam a jelmezedet.'::text),
(343209,38135,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... auf diesem Karneval drei Jahre in Folge das beste Kostüm getragen.'::text,'hast'::text,'hast'::text,'trägst'::text,'Ehrlich, du hast auf diesem Karneval drei Jahre in Folge das beste Kostüm getragen.'::text),
(343213,38135,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, на цьому карнавалі ти ... найкращий костюм три роки поспіль.'::text,'мала'::text,'носила'::text,'маєш'::text,'Чесно, на цьому карнавалі ти мала найкращий костюм три роки поспіль.'::text),
(343212,38135,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... el mejor disfraz de este carnaval tres años seguidos.'::text,'has llevado'::text,'has estado llevando'::text,'llevas'::text,'La verdad, has llevado el mejor disfraz de este carnaval tres años seguidos.'::text),
(343211,38135,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... le meilleur costume de ce carnaval trois ans de suite.'::text,'as porté'::text,'portes'::text,'portes'::text,'Franchement, tu as porté le meilleur costume de ce carnaval trois ans de suite.'::text),
(343214,38135,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, üç yıl üst üste bu karnavalın en iyi kostümünü sen ...'::text,'giydin'::text,'giyiyorsun'::text,'giyiyorsun'::text,'Açıkçası, üç yıl üst üste bu karnavalın en iyi kostümünü sen giydin.'::text),
(343215,38135,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, három éve egymás után neked ... a legjobb jelmezed ezen a karneválon.'::text,'volt'::text,'van'::text,'van'::text,'Őszintén, három éve egymás után neked volt a legjobb jelmezed ezen a karneválon.'::text),
(343218,38136,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Kostüm ... letzten Monat aus Hunderten Regenbogenfedern gemacht. Offensichtlich ein schneller Job.'::text,'wurde'::text,'wird'::text,'machte'::text,'Ihr Kostüm wurde letzten Monat aus Hunderten Regenbogenfedern gemacht. Offensichtlich ein schneller Job.'::text),
(343222,38136,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її костюм ... минулого місяця із сотень райдужних пір''їн. Явно швидка робота.'::text,'був зроблений'::text,'робиться'::text,'зробила'::text,'Її костюм був зроблений минулого місяця із сотень райдужних пір''їн. Явно швидка робота.'::text),
(343221,38136,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su disfraz ... el mes pasado con cientos de plumas arcoíris. Claramente un trabajo rapidito.'::text,'fue hecho'::text,'es hecho'::text,'hizo'::text,'Su disfraz fue hecho el mes pasado con cientos de plumas arcoíris. Claramente un trabajo rapidito.'::text),
(343220,38136,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son costume ... le mois dernier avec des centaines de plumes arc-en-ciel. Clairement un travail vite fait.'::text,'a été fait'::text,'est fait'::text,'a fait'::text,'Son costume a été fait le mois dernier avec des centaines de plumes arc-en-ciel. Clairement un travail vite fait.'::text),
(343223,38136,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kostümü geçen ay yüzlerce gökkuşağı tüyünden ..., belli ki hızlı bir iş.'::text,'yapıldı'::text,'yapılıyor'::text,'yaptı'::text,'Kostümü geçen ay yüzlerce gökkuşağı tüyünden yapıldı, belli ki hızlı bir iş.'::text),
(343224,38136,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jelmezét múlt hónapban ... több száz szivárványszínű tollból. Nyilván gyors meló.'::text,'készítették'::text,'készítik'::text,'készítette'::text,'A jelmezét múlt hónapban készítették több száz szivárványszínű tollból. Nyilván gyors meló.'::text),
(343227,38137,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand ... ihr Regenbogen-Federkostüm. Offensichtlich ein sehr unauffälliges Outfit.'::text,'bemerkte'::text,'wurde bemerkt'::text,'bemerkend'::text,'Niemand bemerkte ihr Regenbogen-Federkostüm. Offensichtlich ein sehr unauffälliges Outfit.'::text),
(343231,38137,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто не ... її райдужного костюма з пір''я. Явно дуже непомітний образ.'::text,'помітив'::text,'був помічений'::text,'помічаючи'::text,'Ніхто не помітив її райдужного костюма з пір''я. Явно дуже непомітний образ.'::text),
(343230,38137,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadie ... su disfraz de plumas arcoíris. Claramente un conjunto muy discreto.'::text,'notó'::text,'fue notado'::text,'notando'::text,'Nadie notó su disfraz de plumas arcoíris. Claramente un conjunto muy discreto.'::text),
(343229,38137,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne n''a ... son costume à plumes arc-en-ciel. Clairement une tenue très discrète.'::text,'remarqué'::text,'été remarqué'::text,'remarquant'::text,'Personne n''a remarqué son costume à plumes arc-en-ciel. Clairement une tenue très discrète.'::text),
(343232,38137,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse onun gökkuşağı tüylü kostümünü ..., belli ki çok sade bir kombin.'::text,'fark etmedi'::text,'fark edilmedi'::text,'fark etmeyerek'::text,'Kimse onun gökkuşağı tüylü kostümünü fark etmedi, belli ki çok sade bir kombin.'::text),
(343233,38137,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki sem ... a szivárványos tollas jelmezét. Nyilván egy nagyon visszafogott szett.'::text,'vette észre'::text,'lett észrevéve'::text,'észrevéve'::text,'Senki sem vette észre a szivárványos tollas jelmezét. Nyilván egy nagyon visszafogott szett.'::text),
(343236,38138,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, das Federkostüm ... eine Tonne wiegen, kein Witz.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Digga, das Federkostüm muss eine Tonne wiegen, kein Witz.'::text),
(343240,38138,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, той костюм із пір''я ... важити тонну, без брехні.'::text,'мусить'::text,'не може'::text,'має'::text,'Брате, той костюм із пір''я мусить важити тонну, без брехні.'::text),
(343239,38138,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese disfraz de plumas ... pesar una tonelada, en serio.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Bro, ese disfraz de plumas debe de pesar una tonelada, en serio.'::text),
(343238,38138,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ce costume à plumes ... peser une tonne, sans mentir.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Frère, ce costume à plumes doit peser une tonne, sans mentir.'::text),
(343241,38138,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o tüylü kostüm bir ton ..., yalan yok.'::text,'çekiyor olmalı'::text,'çekemez'::text,'çekmeli'::text,'Kanka, o tüylü kostüm bir ton çekiyor olmalı, yalan yok.'::text),
(343242,38138,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, annak a tollas jelmeznek ... egy tonnát nyomnia, komolyan.'::text,'kell'::text,'nem lehet'::text,'kéne'::text,'Tesó, annak a tollas jelmeznek kell egy tonnát nyomnia, komolyan.'::text),
(343245,38139,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Frau, ... Kostüm all diese Federn hat, ist schon ziemlich ikonisch.'::text,'deren'::text,'die'::text,'das'::text,'Yo, die Frau, deren Kostüm all diese Federn hat, ist schon ziemlich ikonisch.'::text),
(343249,38139,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, жінка, ... костюм має всі ці пір''їни, доволі культова.'::text,'чий'::text,'яка'::text,'що'::text,'Йо, жінка, чий костюм має всі ці пір''їни, доволі культова.'::text),
(343248,38139,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, la mujer ... disfraz tiene todas esas plumas es bastante icónica.'::text,'cuyo'::text,'que'::text,'la cual'::text,'Oye, la mujer cuyo disfraz tiene todas esas plumas es bastante icónica.'::text),
(343247,38139,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, la femme ... le costume a toutes ces plumes est plutôt iconique.'::text,'dont'::text,'qui'::text,'laquelle'::text,'Yo, la femme dont le costume a toutes ces plumes est plutôt iconique.'::text),
(343250,38139,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kadın, ... kostümünde bütün o tüyler var, baya ikonik.'::text,'ki onun'::text,'ki'::text,'ki'::text,'Kanka, kadın, ki onun kostümünde bütün o tüyler var, baya ikonik.'::text),
(343251,38139,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a nő, ... jelmezén ott van az összes toll, elég ikonikus.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Tesó, a nő, akinek a jelmezén ott van az összes toll, elég ikonikus.'::text),
(343254,38140,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Organisator sagte, das Kostüm ... 400 Euro aus dem Umzugsbudget gekostet.'::text,'habe'::text,'hat'::text,'kostet'::text,'Der Organisator sagte, das Kostüm habe 400 Euro aus dem Umzugsbudget gekostet.'::text),
(343258,38140,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Організатор сказав, що костюм ... 400 євро з бюджету параду.'::text,'коштував'::text,'коштував'::text,'коштує'::text,'Організатор сказав, що костюм коштував 400 євро з бюджету параду.'::text),
(343257,38140,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El organizador dijo que el disfraz ... 400 euros del presupuesto del desfile.'::text,'había costado'::text,'ha costado'::text,'cuesta'::text,'El organizador dijo que el disfraz había costado 400 euros del presupuesto del desfile.'::text),
(343256,38140,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''organisateur a dit que le costume ... 400 euros sur le budget du défilé.'::text,'avait coûté'::text,'a coûté'::text,'coûte'::text,'L''organisateur a dit que le costume avait coûté 400 euros sur le budget du défilé.'::text),
(343259,38140,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Organizatör kostümün geçit bütçesinden 400 euroya ... söyledi.'::text,'mal olduğunu'::text,'mal olduğunu'::text,'mal olduğunu'::text,'Organizatör kostümün geçit bütçesinden 400 euroya mal olduğunu söyledi.'::text),
(343260,38140,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szervező azt mondta, hogy a jelmez 400 euróba ... a felvonulás költségvetéséből.'::text,'került'::text,'került'::text,'kerül'::text,'A szervező azt mondta, hogy a jelmez 400 euróba került a felvonulás költségvetéséből.'::text),
(343263,38141,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Kind ... sie jedes Jahr ein kleines Kostüm zum Karneval.'::text,'trug'::text,'trug'::text,'war gewohnt zu tragen'::text,'Als Kind trug sie jedes Jahr ein kleines Kostüm zum Karneval.'::text),
(343267,38141,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У дитинстві вона щороку ... на карнавал маленький костюм.'::text,'вдягала'::text,'вдягала'::text,'звикла вдягати'::text,'У дитинстві вона щороку вдягала на карнавал маленький костюм.'::text),
(343266,38141,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De niña, ... un disfraz pequeño al carnaval cada año.'::text,'llevaba'::text,'solía llevar'::text,'estaba acostumbrada a llevar'::text,'De niña, llevaba un disfraz pequeño al carnaval cada año.'::text),
(343265,38141,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enfant, elle ... un petit costume au carnaval chaque année.'::text,'portait'::text,'portait'::text,'avait l''habitude de porter'::text,'Enfant, elle portait un petit costume au carnaval chaque année.'::text),
(343268,38141,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken her yıl karnavala küçük bir kostüm ...'::text,'giyerdi'::text,'giyerdi'::text,'giymeye alışkındı'::text,'Çocukken her yıl karnavala küçük bir kostüm giyerdi.'::text),
(343269,38141,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekként minden évben kis jelmezt ... a karneválra.'::text,'vett fel'::text,'szokott felvenni'::text,'hozzá volt szokva, hogy felvegyen'::text,'Gyerekként minden évben kis jelmezt vett fel a karneválra.'::text),
(390423,43381,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du Milch verschüttest, ... der Tisch nass, weil Milch nass ist.'::text,'wird'::text,'wurde'::text,'wird'::text,'Wenn du Milch verschüttest, wird der Tisch nass, weil Milch nass ist.'::text),
(390427,43381,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо розлити молоко, стіл ... мокрим, бо молоко мокре.'::text,'стає'::text,'став'::text,'стане'::text,'Якщо розлити молоко, стіл стає мокрим, бо молоко мокре.'::text),
(390426,43381,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si derramas leche, la mesa ... mojada, porque la leche está mojada.'::text,'se queda'::text,'se quedó'::text,'se quedará'::text,'Si derramas leche, la mesa se queda mojada, porque la leche está mojada.'::text),
(390425,43381,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu renverses du lait, la table ... mouillée, parce que le lait, c''est mouillé.'::text,'devient'::text,'est devenue'::text,'deviendra'::text,'Si tu renverses du lait, la table devient mouillée, parce que le lait, c''est mouillé.'::text),
(390428,43381,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süt dökersen masa ..., çünkü süt ıslaktır.'::text,'ıslanır'::text,'ıslandı'::text,'ıslanacak'::text,'Süt dökersen masa ıslanır, çünkü süt ıslaktır.'::text),
(390429,43381,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha kiöntöd a tejet, az asztal vizes ..., mert a tej vizes.'::text,'lesz'::text,'lett'::text,'lesz'::text,'Ha kiöntöd a tejet, az asztal vizes lesz, mert a tej vizes.'::text),
(390441,43383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast nicht wegen der verschütteten Milch geweint, und ...'::text,'ich auch nicht'::text,'ich auch'::text,'ich auch nicht'::text,'Ehrlich, du hast nicht wegen der verschütteten Milch geweint, und ich auch nicht.'::text),
(390445,43383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти не плакала через розлите молоко, і ...'::text,'я теж ні'::text,'я теж'::text,'я теж ні'::text,'Чесно, ти не плакала через розлите молоко, і я теж ні.'::text),
(390444,43383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, no lloraste por la leche derramada, y ...'::text,'yo tampoco'::text,'yo también'::text,'yo tampoco'::text,'La verdad, no lloraste por la leche derramada, y yo tampoco.'::text),
(390443,43383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu n''as pas pleuré pour le lait renversé, et ...'::text,'moi non plus'::text,'moi aussi'::text,'moi non plus'::text,'Franchement, tu n''as pas pleuré pour le lait renversé, et moi non plus.'::text),
(390446,43383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, dökülen süt için ağlamadın, ...'::text,'ben de ağlamadım'::text,'ben de ağladım'::text,'ben de değildim'::text,'Açıkçası, dökülen süt için ağlamadın, ben de ağlamadım.'::text),
(390447,43383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, nem sírtál a kiömlött tej miatt, és ...'::text,'én sem'::text,'én is'::text,'én sem'::text,'Őszintén, nem sírtál a kiömlött tej miatt, és én sem.'::text),
(390450,43384,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Bis die Milch aufhört auszulaufen, ... du den ganzen Tisch sauber gemacht haben.'::text,'wirst'::text,'wirst'::text,'hast'::text,'Respekt: Bis die Milch aufhört auszulaufen, wirst du den ganzen Tisch sauber gemacht haben.'::text),
(390454,43384,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: поки молоко перестане текти, ти вже ... весь стіл.'::text,'витреш'::text,'витреш'::text,'витерла'::text,'Респект: поки молоко перестане текти, ти вже витреш весь стіл.'::text),
(390453,43384,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: para cuando la leche deje de salirse, ... toda la mesa.'::text,'habrás limpiado'::text,'limpiarás'::text,'has limpiado'::text,'Respeto: para cuando la leche deje de salirse, habrás limpiado toda la mesa.'::text),
(390452,43384,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : le temps que le lait arrête de couler, tu ... toute la table.'::text,'auras nettoyé'::text,'nettoieras'::text,'as nettoyé'::text,'Respect : le temps que le lait arrête de couler, tu auras nettoyé toute la table.'::text),
(390455,43384,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal: süt akmayı bırakana kadar bütün masayı ...'::text,'silmiş olacaksın'::text,'sileceksin'::text,'sildin'::text,'Helal: süt akmayı bırakana kadar bütün masayı silmiş olacaksın.'::text),
(390456,43384,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: mire a tej abbahagyja a folyást, ... az egész asztalt.'::text,'letörlöd'::text,'le fogod törölni'::text,'letörölted'::text,'Respekt: mire a tej abbahagyja a folyást, letörlöd az egész asztalt.'::text),
(390459,43385,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Karton nicht aufgeplatzt wäre, ... sie die Milch nicht auf den Tisch verschüttet.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn der Karton nicht aufgeplatzt wäre, hätte sie die Milch nicht auf den Tisch verschüttet.'::text),
(390463,43385,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби пакет не розірвався, вона ... молоко на стіл.'::text,'не розлила б'::text,'не розіллє'::text,'не розлила'::text,'Якби пакет не розірвався, вона не розлила б молоко на стіл.'::text),
(390462,43385,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el cartón no se hubiera roto, no ... la leche en la mesa.'::text,'habría derramado'::text,'derramará'::text,'derramó'::text,'Si el cartón no se hubiera roto, no habría derramado la leche en la mesa.'::text),
(390461,43385,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la brique ne s''était pas fendue, elle ... le lait sur la table.'::text,'n''aurait pas renversé'::text,'ne renversera pas'::text,'n''a pas renversé'::text,'Si la brique ne s''était pas fendue, elle n''aurait pas renversé le lait sur la table.'::text),
(390464,43385,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kutu yırtılmasaydı sütü masaya ...'::text,'dökmezdi'::text,'dökmeyecek'::text,'dökmedi'::text,'Kutu yırtılmasaydı sütü masaya dökmezdi.'::text),
(390465,43385,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a doboz nem repedt volna ki, nem ... a tejet az asztalra.'::text,'öntötte volna ki'::text,'fogja kiönteni'::text,'öntötte ki'::text,'Ha a doboz nem repedt volna ki, nem öntötte volna ki a tejet az asztalra.'::text),
(390468,43386,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie stritt ab, die Milch ..., und sagte, der Karton sei von selbst aufgeplatzt.'::text,'verschüttet zu haben'::text,'zu verschütten'::text,'verschütten'::text,'Sie stritt ab, die Milch verschüttet zu haben, und sagte, der Karton sei von selbst aufgeplatzt.'::text),
(390472,43386,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона заперечила, що ... молоко, і сказала, що пакет розірвався сам.'::text,'розлила'::text,'розлити'::text,'розлити'::text,'Вона заперечила, що розлила молоко, і сказала, що пакет розірвався сам.'::text),
(390471,43386,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... la leche y dijo que el cartón se rompió solo.'::text,'haber derramado'::text,'derramar'::text,'derramar'::text,'Negó haber derramado la leche y dijo que el cartón se rompió solo.'::text),
(390470,43386,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a nié ... le lait et a dit que la brique s''était fendue toute seule.'::text,'avoir renversé'::text,'renverser'::text,'renverser'::text,'Elle a nié avoir renversé le lait et a dit que la brique s''était fendue toute seule.'::text),
(390473,43386,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sütü ... inkâr etti ve kutunun kendi kendine yırtıldığını söyledi.'::text,'döktüğünü'::text,'dökmeyi'::text,'dökmek'::text,'Sütü döktüğünü inkâr etti ve kutunun kendi kendine yırtıldığını söyledi.'::text),
(390474,43386,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy ... a tejet, és azt mondta, hogy a doboz magától repedt ki.'::text,'kiöntötte'::text,'kiönteni'::text,'kiönteni'::text,'Tagadta, hogy kiöntötte a tejet, és azt mondta, hogy a doboz magától repedt ki.'::text),
(390486,43388,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'OMG, man munkelt, sie hat das undichte Rohr endlich ... lassen, nachdem es überall Wasser verspritzt hat.'::text,'reparieren'::text,'reparieren'::text,'reparieren'::text,'OMG, man munkelt, sie hat das undichte Rohr endlich reparieren lassen, nachdem es überall Wasser verspritzt hat.'::text),
(390490,43388,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Божечки, кажуть, вона нарешті домоглася, щоб ... трубу, що протікала, після того як з неї всюди розлилася вода.'::text,'полагодили'::text,'полагодити'::text,'полагодити'::text,'Божечки, кажуть, вона нарешті домоглася, щоб полагодили трубу, що протікала, після того як з неї всюди розлилася вода.'::text),
(390489,43388,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dios mío, dicen que por fin hizo ... la tubería que goteaba después de que soltara agua por todas partes.'::text,'arreglar'::text,'arreglar'::text,'arreglar'::text,'Dios mío, dicen que por fin hizo arreglar la tubería que goteaba después de que soltara agua por todas partes.'::text),
(390488,43388,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'OMG, il paraît qu''elle a enfin fait ... le tuyau qui fuyait après qu''il a mis de l''eau partout.'::text,'réparer'::text,'réparer'::text,'réparer'::text,'OMG, il paraît qu''elle a enfin fait réparer le tuyau qui fuyait après qu''il a mis de l''eau partout.'::text),
(390491,43388,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman tanrım, dediklerine göre sızdıran boruyu her yere su döktükten sonra sonunda ...'::text,'tamir ettirmiş'::text,'tamir etmek'::text,'tamir etmeye'::text,'Aman tanrım, dediklerine göre sızdıran boruyu her yere su döktükten sonra sonunda tamir ettirmiş.'::text),
(390492,43388,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, állítólag végre ... a csöpögő csövet, miután mindenhova kifolyt belőle a víz.'::text,'megjavíttatta'::text,'megjavít'::text,'megjavítani'::text,'Úristen, állítólag végre megjavíttatta a csöpögő csövet, miután mindenhova kifolyt belőle a víz.'::text),
(390495,43389,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie wünschte, sie ... die ganze Milch nicht verschüttet, echt.'::text,'hätte'::text,'hätte'::text,'würde'::text,'Digga, sie wünschte, sie hätte die ganze Milch nicht verschüttet, echt.'::text),
(390499,43389,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Брате, краще б вона ... все те молоко, чесно.'::text,'не розлила'::text,'не розливала'::text,'не розлила'::text,'Брате, краще б вона не розлила все те молоко, чесно.'::text),
(390498,43389,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella desearía ... toda esa leche, en serio.'::text,'no haber derramado'::text,'no derramar'::text,'no derramar'::text,'Bro, ella desearía no haber derramado toda esa leche, en serio.'::text),
(390497,43389,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle aimerait ... tout ce lait, sérieux.'::text,'ne pas avoir renversé'::text,'ne pas renverser'::text,'ne pas renverser'::text,'Frère, elle aimerait ne pas avoir renversé tout ce lait, sérieux.'::text),
(390500,43389,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, keşke bütün o sütü ... diyor, cidden.'::text,'dökmeseydim'::text,'dökmesem'::text,'dökmezdim'::text,'Kanka, keşke bütün o sütü dökmeseydim diyor, cidden.'::text),
(390501,43389,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt kívánja, bárcsak ne ... ki azt a sok tejet, komolyan.'::text,'öntötte volna'::text,'öntené'::text,'öntené'::text,'Tesó, azt kívánja, bárcsak ne öntötte volna ki azt a sok tejet, komolyan.'::text),
(390504,43390,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, der Karton, ... Milch sich über den ganzen Tisch ergießt, ist komplett hinüber.'::text,'dessen'::text,'der'::text,'das'::text,'Nee, der Karton, dessen Milch sich über den ganzen Tisch ergießt, ist komplett hinüber.'::text),
(390508,43390,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, той пакет, ... молоко розливається по всьому столу, вже повністю все.'::text,'чиє'::text,'який'::text,'що'::text,'Не, той пакет, чиє молоко розливається по всьому столу, вже повністю все.'::text),
(390507,43390,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, el cartón, ... leche se está derramando por toda la mesa, está totalmente destrozado.'::text,'cuya'::text,'el cual'::text,'que'::text,'Nah, el cartón, cuya leche se está derramando por toda la mesa, está totalmente destrozado.'::text),
(390506,43390,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, la brique, ... le lait se répand sur toute la table, est complètement foutue.'::text,'dont'::text,'laquelle'::text,'que'::text,'Nan, la brique, dont le lait se répand sur toute la table, est complètement foutue.'::text),
(390509,43390,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, kutu, ... sütü bütün masaya dökülüyor, tamamen bitik.'::text,'ki onun'::text,'ki'::text,'ki'::text,'Yok, kutu, ki onun sütü bütün masaya dökülüyor, tamamen bitik.'::text),
(390510,43390,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, a doboz, ... teje az egész asztalra folyik, teljesen kész van.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'Nem, a doboz, amelynek a teje az egész asztalra folyik, teljesen kész van.'::text),
